To achieve the desired setup, we will create a Terraform configuration that provisions:

1. An AWS Route 53 hosted zone named "main".
2. A primary RDS instance in the `us-west-1` region.
3. Three replica RDS instances in the `us-east-1`, `eu-central-1`, and `ap-southeast-1` regions.
4. A Route 53 record set with a weighted routing policy to distribute traffic among the three replica instances.

We'll use provider aliases to manage resources across different regions. Additionally, we'll create necessary IAM roles and policies for RDS replication.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  alias  = "main"
  region = "us-west-1"
}

provider "aws" {
  alias  = "us-east"
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu-central"
  region = "eu-central-1"
}

provider "aws" {
  alias  = "ap-southeast"
  region = "ap-southeast-1"
}

resource "aws_route53_zone" "main" {
  provider = aws.main
  name     = "main"
}

resource "aws_db_subnet_group" "primary" {
  provider = aws.main

  name       = "primary-subnet-group"
  subnet_ids = ["subnet-00000000000000001", "subnet-00000000000000002"]

  tags = {
    Name = "PrimaryDBSubnetGroup"
  }
}

resource "aws_db_instance" "primary" {
  provider = aws.main

  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  name                 = "primary"
  username             = "admin"
  password             = "password"
  parameter_group_name = "default.mysql8.0"
  skip_final_snapshot  = true
  db_subnet_group_name = aws_db_subnet_group.primary.name

  tags = {
    Name = "PrimaryDBInstance"
  }
}

resource "aws_db_subnet_group" "replica_us_east" {
  provider = aws.us-east

  name       = "replica-us-east-subnet-group"
  subnet_ids = ["subnet-00000000000000003", "subnet-00000000000000004"]

  tags = {
