# IAM Role and Policy for RDS Replication
resource "aws_iam_role" "rds_replication_role" {
  provider = aws.main

  name = "rds-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "rds_replication_policy" {
  provider = aws.main

  name        = "rds-replication-policy"
  description = "Policy for RDS replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_replication_policy_attachment" {
  provider = aws.main

  role       = aws_iam_role.rds_replication_role.name
  policy_arn = aws_iam_policy.rds_replication_policy.arn
}
```

### Notes:
- Replace the `subnet_ids` in the `aws_db_subnet_group` resources with actual subnet IDs from your VPCs in the respective regions.
- The `password` for the RDS instances should be securely managed using AWS Secrets Manager or another secure method.
- Ensure that the IAM role and policies are correctly configured for your specific use case and security requirements.
- This configuration assumes that the necessary VPCs and subnets already exist in the specified regions. If not, you will need to create them first.

