To achieve the desired configuration, we will set up two Route 53 hosted zones: one for internal users (`private`) and another for external users (`public`). Each zone will have a record pointing to a different RDS instance. We'll also create the necessary RDS instances and a DB subnet group named `main`. For simplicity, we'll use MySQL as the database engine, but this can be adjusted as needed.

Here's the Terraform configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_id" {
  description = "The VPC ID where the RDS instances will be deployed."
  type        = string
  default     = "vpc-0123456789abcdef0"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the DB subnet group."
  type        = list(string)
  default     = ["subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
}

variable "internal_db_name" {
  description = "The name of the internal RDS database."
  type        = string
  default     = "internaldb"
}

variable "public_db_name" {
  description = "The name of the public RDS database."
  type        = string
  default     = "publicdb"
}

variable "db_username" {
  description = "The username for the RDS databases."
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "The password for the RDS databases."
  type        = string
  sensitive   = true
  default     = "securepassword123"
}

# IAM role for RDS
resource "aws_iam_role" "rds_role" {
  name = "rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_role.name
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = var.subnet_ids

  tags = {
    Name = "MainDBSubnetGroup"
  }
}

# Internal RDS Instance
resource "aws_db_instance" "internal" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  name                 = var.internal_db_name
  username             = var.db_username
  password             = var.db_password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.internal_rds_sg.id]
  skip_final_snapshot  = true

  tags = {
    Name = "InternalRDS"
  }
}

# Public RDS Instance
resource "aws_db_instance" "public" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  name                 = var.public_db_name
  username             = var.db_username
  password             = var.db_password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.public_rds_sg.id]
  publicly_accessible  = true
  skip_final_snapshot  = true

  tags = {
    Name = "PublicRDS"
  }
}

# Security Groups
resource "aws_security_group" "internal_rds_sg" {
  name        = "internal-rds-sg"
  description = "Security group for internal RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # Adjust according to your internal network
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "public_rds_sg" {
  name        = "public-rds-sg"
  description = "Security group for public RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Open to the world, adjust as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Route 53 Hosted Zones
resource "aws_route53_zone" "private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public" {
  name = "public.example.com"
}

# Route 53 Records
resource "aws_route53_record" "internal_db" {
  zone_id = aws_route53_zone.private.zone_id
  name    = "db.private.example.com"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.internal.endpoint]
}

resource "aws_route53_record" "public_db" {
  zone_id = aws_route53_zone.public.zone_id
  name    = "db.public.example.com"
  type    = "CNAME"
  ttl     = 300
  records = [aws_db_instance.public.endpoint]
}
```

### Explanation:
- **Provider Configuration**: Configured for AWS with a specific region.
- **Variables**: Defined with default values for flexibility.
- **IAM Role**: Created for RDS with full access.
- **DB Subnet Group**: Created with the provided subnet IDs.
- **RDS Instances**: Two instances created, one internal and one public.
- **Security Groups**: Configured for both RDS instances.
- **Route 53 Hosted Zones**: Created for internal and public DNS zones.
- **Route 53 Records**: CNAME records pointing to the respective RDS endpoints.

Make sure to replace the default values for `vpc_id` and `subnet_ids` with your actual VPC and subnet IDs. Also, adjust the security group rules according to your network requirements.

