The Terraform program I will define will create an Elastic Beanstalk environment with autoscaling settings based on CPU utilization thresholds. It will also create an IAM role named `eb_ec2_role`, an instance profile named `eb_ec2_profile`, and an Elastic Beanstalk application named `my_api_app`. The configuration will be deployable with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

Here is the Terraform HCL program:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Create an IAM role for EC2 instances in the Elastic Beanstalk environment
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "eb_ec2_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.eb_ec2_role.name
}

# Create an instance profile and attach the IAM role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Create an Elastic Beanstalk application
resource "aws_elastic_beanstalk_application" "my_api_app" {
  name        = "my_api_app"
  description = "Elastic Beanstalk application for my API"
}

# Create an Elastic Beanstalk application version
resource "aws_elastic_beanstalk_application_version" "my_api_app_version" {
  application = aws_elastic_beanstalk_application.my_api_app.name
  name        = "v1.0.0"
  bucket      = "your-s3-bucket-name"  # Replace with your S3 bucket name
  key         = "path/to/your/application.zip"  # Replace with your application zip file path in S3
}

# Create an Elastic Beanstalk environment
resource "aws_elastic_beanstalk_environment" "my_api_env" {
  name                = "my-api-env"
  application         = aws_elastic_beanstalk_application.my_api_app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Corretto 17"
  version_label       = aws_elastic_beanstalk_application_version.my_api_app_version.name
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "4"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "MeasureName"
    value       = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "Statistic"
    value       = "Average"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "Unit"
    value       = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "Period"
    value       = "120"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "EvaluationPeriods"
    value       = "2"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "UpperThreshold"
    value       = "70"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    option_name = "LowerThreshold"
    value       = "30"
  }
}
```

### Notes:
- Replace `"your-s3-bucket-name"` and `"path/to/your/application.zip"` with your actual S3 bucket name and the path to your application zip file stored in S3.
- The `solution_stack_name` can be adjusted based on the runtime and platform you need for your application.
- The region in the provider block can be changed to any region where you want to deploy your Elastic Beanstalk environment.

