To achieve the task of configuring Route 53 to manage a domain and direct traffic to an Elastic Beanstalk environment, we need to set up several AWS resources:

1. **Route 53 Hosted Zone**: To manage DNS records for the domain.
2. **Elastic Beanstalk Application**: The application that will host the web application.
3. **Elastic Beanstalk Environment**: The environment where the application version will run.
4. **IAM Role and Instance Profile**: For the EC2 instances running in the Elastic Beanstalk environment.
5. **S3 Bucket and Object**: To store the application version.

Below is the Terraform HCL configuration that accomplishes this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "domain_name" {
  default = "example.com"
}

variable "bucket_name" {
  default = "unique-bucket-name-for-myapp"
}

# Route 53 Hosted Zone
resource "aws_route53_zone" "main" {
  name = var.domain_name
}

# S3 Bucket
resource "aws_s3_bucket" "myapp_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  tags = {
    Name = "myapp-bucket"
  }
}

# S3 Bucket Object
resource "aws_s3_bucket_object" "examplebucket_object" {
  bucket = aws_s3_bucket.myapp_bucket.id
  key    = "example-object.txt"
  source = "path/to/example-object.txt"

  etag = filemd5("path/to/example-object.txt")
}

# IAM Role for Elastic Beanstalk EC2 Instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy Attachment for the Role
resource "aws_iam_role_policy_attachment" "eb_ec2_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.eb_ec2_role.name
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Elastic Beanstalk Application"
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.myapp_bucket.id
  key         = aws_s3_bucket_object.examplebucket_object.key
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "eb_env" {
  name                = "eb-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label       = aws_elastic_beanstalk_application_version.version.name

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "EnvironmentType"
    value       = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:instances"
    option_name = "IamInstanceProfile"
    value       = aws_iam_instance_profile.eb_ec2_profile.name
  }

  # Route 53 Record Set for the Elastic Beanstalk Environment
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "Domain"
    value       = "${aws_route53_zone.main.name}"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "Subdomain"
    value       = "www"
  }
}

# Route 53 Record Set for the Elastic Beanstalk Environment
resource "aws_route53_record" "eb_env_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.${aws_route53_zone.main.name}"
  type    = "A"

  alias {
    name                   = aws_elastic_beanstalk_environment.eb_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eb_env.cname_options.zone_id
    evaluate_target_health = true
  }
}
