To configure a Blue/Green deployment using AWS Elastic Beanstalk and Route53 with a Weighted Routing Policy, we need to create two Elastic Beanstalk environments named "blue" and "green". We'll also set up a Route53 record with a weighted routing policy to distribute traffic between these two environments.

The Terraform configuration will include:
- An IAM role and policy for the Elastic Beanstalk application.
- Two Elastic Beanstalk applications and their respective environments.
- A Route53 hosted zone and a weighted routing policy record set.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role and Policy for Elastic Beanstalk
resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "eb_service_policy" {
  name        = "eb-service-policy"
  description = "Policy for Elastic Beanstalk service role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "ecs:*",
          "elasticloadbalancing:*",
          "autoscaling:*",
          "cloudwatch:*",
          "s3:*",
          "sns:*",
          "rds:*",
          "dynamodb:*",
          "sqs:*",
          "logs:*",
          "events:*",
          "iam:GetRole",
          "iam:PassRole"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_service_policy_attachment" {
  policy_arn = aws_iam_policy.eb_service_policy.arn
  role       = aws_iam_role.eb_service_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-blue-green-app"
  description = "Application for Blue/Green Deployment"
}

# Elastic Beanstalk Environment - Blue
resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue-env"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label       = "v1"
  instance_type       = "t2.micro"
  environment_variables = {
    ENVIRONMENT = "blue"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "2"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "ServiceRole"
    value       = aws_iam_role.eb_service_role.arn
  }
}

# Elastic Beanstalk Environment - Green
resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green-env"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label       = "v1"
  instance_type       = "t2.micro"
  environment_variables = {
    ENVIRONMENT = "green"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "2"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "ServiceRole"
    value       = aws_iam_role.eb_service_role.arn
  }
}

# Route53 Hosted Zone
resource "aws_route53_zone" "primary" {
  name = "example.com"
}

# Route53 Record Set with Weighted Routing Policy
resource "aws_route53_record" "weighted" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "www.example.com"
  type    = "A"

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.blue.cname
    zone_id                = data.aws_route53_zone.default.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "weighted_green" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "www.example.com"
  type    = "A"

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.green.cname
    zone_id                = data.aws_route53_zone.default.zone_id
    evaluate_target_health = true
  }
}

# Data Source for Route53 Zone ID
data "aws_route53_zone" "default" {
  name = "example.com"
}
```

### Explanation:
- **IAM Role and Policy**: The IAM role `eb-service-role` is created with necessary permissions for Elastic Beanstalk to manage its resources.
- **Elastic Beanstalk Application**: A single Elastic Beanstalk application is created, and two environments ("blue" and "green") are deployed from it.
- **Route53 Hosted Zone**: A Route53 hosted zone is created for the domain `example.com`.
- **Weighted Routing Policy**: Two A records are created in the Route53 hosted zone with a weighted routing policy, directing 50% of the traffic to each environment.

Make sure to replace `"example.com"` with your actual domain name and adjust the `solution_stack_name` and `version_label` according to your application requirements.

