To achieve the desired setup, we will configure two AWS Elastic Beanstalk environments in the `us-west-2` and `eu-central-1` regions. We'll also set up Amazon Route 53 to route traffic to the closest environment based on the user's geolocation using latency-based routing.

Here's a breakdown of the resources we will create:

1. **IAM Roles and Policies**: Necessary IAM roles and policies for Elastic Beanstalk.
2. **Elastic Beanstalk Applications**: One application for both environments.
3. **Elastic Beanstalk Environments**: Two environments, one in `us-west-2` and one in `eu-central-1`.
4. **Route 53 Hosted Zone**: A hosted zone for our domain.
5. **Route 53 Latency Records**: Latency records pointing to the Elastic Beanstalk environments.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-west-2"
}

variable "domain_name" {
  type    = string
  default = "example.com"
}

variable "application_name" {
  type    = string
  default = "my-application"
}

variable "environment_name_us_west" {
  type    = string
  default = "us_west"
}

variable "environment_name_eu_central" {
  type    = string
  default = "eu_central"
}

resource "aws_iam_role" "beanstalk_service" {
  name = "${var.application_name}-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "beanstalk_policy" {
  name        = "${var.application_name}-policy"
  description = "Policy for Elastic Beanstalk"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "ecs:*",
          "elasticloadbalancing:*",
          "autoscaling:*",
          "cloudwatch:*",
          "s3:*",
          "sns:*",
          "sqs:*",
          "rds:*",
          "dynamodb:*",
          "lambda:*",
          "events:*",
          "logs:*",
          "route53:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "beanstalk_policy_attachment" {
  policy_arn = aws_iam_policy.beanstalk_policy.arn
  role       = aws_iam_role.beanstalk_service.name
}

resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "us_west_env" {
  name                = var.environment_name_us_west
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label       = "v1"
  instance_type       = "t2.micro"
  environment_variables = {
    ENVIRONMENT = "us_west"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", data.aws_subnets.default.ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = data.aws_vpc.default.id
  }

  tags = {
    Name = "${var.environment_name_us_west}-env"
  }

  provider = aws.us_west_2
}

resource "aws_elastic_beanstalk_environment" "eu_central_env" {
  name                = var.environment_name_eu_central
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label       = "v1"
  instance_type       = "t2.micro"
  environment_variables = {
    ENVIRONMENT = "eu_central"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", data.aws_subnets.default.ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = data.aws_vpc.default.id
  }

  tags = {
    Name = "${var.environment_name_eu_central}-env"
  }

  provider = aws.eu_central_1
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

resource "aws_route53_zone" "zone" {
  name = var.domain_name
}

resource "aws_route53_record" "us_west_record" {
  zone_id = aws_route53_zone.zone.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_elastic_beanstalk_environment.us_west_env.cname
    zone_id                = aws_elastic_beanstalk_environment.us_west_env.cname_options.zone_id
    evaluate_target_health = false
  }

  health_check_region = "us-west-2"
}

resource "aws_route53_record" "eu_central_record" {
  zone_id = aws_route53_zone.zone.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eu_central_env.cname_options.zone_id
    evaluate_target_health = false
  }

  health_check_region = "eu-central-1"
}

resource "aws_route53_latency_alias_record" "latency_record" {
  zone_id = aws_route53_zone.zone.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  set_identifier = "us-west-2"
  evaluate_target_health = false

  alias {
    name                   = aws_elastic_beanstalk_environment.us_west_env.cname
    zone_id                = aws_elastic_beanstalk_environment.us_west_env.cname_options.zone_id
    evaluate_target_health = false
  }

  provider = aws.us_west_2
}

resource "aws_route53_latency_alias_record" "latency_record_eu" {
  zone_id = aws_route53_zone.zone.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  set_identifier = "eu-central-1"
  evaluate_target_health = false

  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eu_central_env.cname_options.zone_id
    evaluate_target_health = false
  }

  provider = aws.eu_central_1
}
```

### Explanation:
- **Provider Configuration**: The provider is configured with a default region (`us-west-2`). However, specific providers are defined for `us-west-2` and `eu-central-1` when creating resources in those regions.
- **IAM Role and Policy**: An IAM role and policy are created for Elastic Beanstalk to manage its resources.
- **Elastic Beanstalk Application and Environments**: An application is created, and two environments are created in `us-west-2` and `eu-central-1`.
- **Route 53 Resources**: A hosted zone is created, and latency-based routing is set up to direct traffic to the closest environment based on geolocation.

This configuration ensures that the infrastructure is fully specified and deployable with Terraform.

