LLM Output #0:
To configure an Elastic Beanstalk environment linked to a relational database instance, we need to set up several AWS resources:

1. **IAM Role and Instance Profile**: We'll create an IAM role named `eb_ec2_role` and an instance profile named `eb_ec2_profile` for the EC2 instances running in the Elastic Beanstalk environment. This role will have policies attached to allow access to the RDS instance.

2. **RDS Database Instance**: We'll create an RDS instance named `default`. For simplicity, we'll use MySQL as the database engine.

3. **Elastic Beanstalk Application and Environment**: We'll create an Elastic Beanstalk application and an environment linked to the RDS instance.

4. **Security Group**: We'll create a security group to control inbound traffic to the RDS instance.

Below is the complete Terraform HCL configuration to achieve this setup:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Security Group for RDS
resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  description = "Allow traffic from Elastic Beanstalk to RDS"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # In production, restrict this to your EB environment's security group
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# IAM Role for Elastic Beanstalk EC2 Instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM Role
resource "aws_iam_role_policy_attachment" "rds_access" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
  role       = aws_iam_role.eb_ec2_role.name
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# RDS Database Instance
resource "aws_db_instance" "default" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  name                 = "default"
  username             = "admin"
  password             = "password123"  # In production, use a more secure method to manage passwords
  parameter_group_name = "default.mysql8.0"
  skip_final_snapshot  = true

  vpc_security_group_ids = [aws_security_group.rds_sg.id]
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-beanstalk-app"
  description = "My Elastic Beanstalk Application"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "env" {
  name                = "my-beanstalk-env"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Corretto 17"

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "EnvironmentType"
    value       = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:vpc"
    option_name = "VPCId"
    value       = var.vpc_id
  }

  setting {
    namespace = "aws:ec2:vpc"
    option_name = "Subnets"
    value       = join(",", var.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    option_name = "ELBSubnets"
    value       = join(",", var.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    option_name = "AssociatePublicIpAddress"
    value       = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    option_name = "IamInstanceProfile"
    value       = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:rds:dbinstance"
    option_name = "DBInstanceIdentifier"
    value       = aws_db_instance.default.identifier
  }

  setting {
    namespace = "aws:rds:dbinstance"
    option_name = "DBUser"
    value       = aws_db_instance.default.username
  }

  setting {
    namespace = "aws:rds:dbinstance"
    option_name = "DBPassword"
    value       = aws_db_instance.default.password
  }
}

# Variables
variable "vpc_id" {
  description = "The VPC ID where the Elastic Beanstalk environment will be deployed."
  type        = string
  default     = "vpc-0123456789abcdef0"  # Replace with your VPC ID
}

variable "subnet_ids" {
  description = "A list of subnet IDs within the VPC where the Elastic Beanstalk environment will be deployed."
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]  # Replace with your subnet IDs
}
```

### Notes:
- **Security Group**: The RDS security group allows inbound traffic on port 3306 from any IP (`0.0.0.0/0`). In a production environment, you should restrict this to only the Elastic Beanstalk environment's security group.
- **IAM Role and Policy**: The IAM role `eb_ec2_role` is attached with the `AmazonRDSFullAccess` policy for simplicity. In a production environment, it's recommended to create a custom policy with the minimum necessary permissions.
- **Database Credentials**: The RDS instance uses hardcoded credentials (`admin` and `password123`). In a production environment, consider using AWS Secrets Manager or Parameter Store to manage sensitive information securely.
- **VPC and Subnets**: The `vpc_id` and `subnet_ids` variables are placeholders. You need to replace them with your actual VPC and subnet IDs.

This configuration sets up a basic Elastic Beanstalk environment linked to an RDS instance, ensuring that the EC2 instances in the environment can communicate with the RDS instance.

