LLM Output #0:
The Terraform program will configure two AWS Elastic Beanstalk environments for production and staging, each associated with its own Amazon RDS instance. The production environment will be linked to a database named `prod_db`, and the staging environment will be linked to a database named `staging_db`. An IAM role named `eb_ec2_profile` will be created and attached to the EC2 instances running in these environments. The configuration will specify the necessary resources, including the Elastic Beanstalk application, environments, RDS instances, and IAM roles and policies.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Variables with default values
variable "application_name" {
  default = "my-application"
}

variable "instance_type" {
  default = "t3.micro"
}

variable "db_engine" {
  default = "mysql"
}

variable "db_version" {
  default = "8.0"
}

variable "db_username" {
  default = "admin"
}

variable "db_password" {
  default = "securepassword123"  # In practice, use a more secure method to handle passwords
}

variable "allocated_storage" {
  default = 20
}

# IAM Role for Elastic Beanstalk EC2 Instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_profile"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Elastic Beanstalk EC2 Instances
resource "aws_iam_policy" "eb_ec2_policy" {
  name        = "eb_ec2_policy"
  description = "Policy for Elastic Beanstalk EC2 instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "logs:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:Describe*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "eb_ec2_policy_attachment" {
  policy_arn = aws_iam_policy.eb_ec2_policy.arn
  role       = aws_iam_role.eb_ec2_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "Elastic Beanstalk application for production and staging"
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "app_version" {
  name        = "${var.application_name}-v1"
  application = aws_elastic_beanstalk_application.app.name
  bucket      = "your-s3-bucket-name"  # Replace with your S3 bucket name
  key         = "path/to/your/application.zip"  # Replace with your application zip file path
}

# Elastic Beanstalk Environment for Production
resource "aws_elastic_beanstalk_environment" "prod_env" {
  name                = "${var.application_name}-prod"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Corretto 17"
  version_label       = aws_elastic_beanstalk_application_version.app_version.name

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "2"
  }

  setting {
    namespace = "aws:ec2:instances"
    option_name = "InstanceType"
    value       = var.instance_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "EnvironmentType"
    value       = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:vpc"
    option_name = "IAMInstanceProfile"
    value       = aws_iam_role.eb_ec2_role.name
  }

  setting {
    namespace = "aws:rds:dbinstance"
    option_name = "DBInstanceIdentifier"
    value       = aws_db_instance.prod_db.identifier
  }
}

# Elastic Beanstalk Environment for Staging
resource "aws_elastic_beanstalk_environment" "staging_env" {
  name                = "${var.application_name}-staging"
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Corretto 17"
  version_label       = aws_elastic_beanstalk_application_version.app_version.name

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "2"
  }

  setting {
    namespace = "aws:ec2:instances"
    option_name = "InstanceType"
    value       = var.instance_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "EnvironmentType"
    value       = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:vpc"
    option_name = "IAMInstanceProfile"
    value       = aws_iam_role.eb_ec2_role.name
  }

  setting {
    namespace = "aws:rds:dbinstance"
    option_name = "DBInstanceIdentifier"
    value       = aws_db_instance.staging_db.identifier
  }
}

# RDS Instance for Production
resource "aws_db_instance" "prod_db" {
  identifier              = "prod_db"
  engine                  = var.db_engine
  engine_version          = var.db_version
  instance_class          = var.instance_type
  allocated_storage       = var.allocated_storage
  name                    = "prod_db"
  username                = var.db_username
  password                = var.db_password
  skip_final_snapshot     = true
  publicly_accessible     = false
  multi_az                = false
  storage_type            = "gp2"
  backup_retention_period = 5
}

# RDS Instance for Staging
resource "aws_db_instance" "staging_db" {
  identifier              = "staging_db"
  engine                  = var.db_engine
  engine_version          = var.db_version
  instance_class          = var.instance_type
  allocated_storage       = var.allocated_storage
  name                    = "staging_db"
  username                = var.db_username
  password                = var.db_password
  skip_final_snapshot     = true
  publicly_accessible     = false
  multi_az                = false
  storage_type            = "gp2"
  backup_retention_period = 5
}
```

### Notes:
- Replace `"your-s3-bucket-name"` and `"path/to/your/application.zip"` with your actual S3 bucket name and application zip file path.
- Ensure that the `db_password` variable is handled securely in a real-world scenario, possibly using AWS Secrets Manager or environment variables.
- Adjust the `solution_stack_name` if you need a different runtime environment for your application.
- The `skip_final_snapshot` parameter is set to `true` for simplicity; in a production environment, you should manage snapshots appropriately to avoid data loss.

