To configure a blue/green deployment using AWS Route 53 for directing traffic between two separate environments while connecting them to a shared RDS database, we need to set up several AWS resources. These include:

1. **IAM Role and Instance Profile**: An IAM role with necessary permissions for EC2 instances to access the RDS database, and an instance profile associated with this role.
2. **RDS Database**: A shared RDS database named `myapp_db`.
3. **Route 53 Hosted Zone**: A DNS zone where we will create records for the blue and green environments.
4. **Route 53 Health Checks**: Health checks for the blue and green environments.
5. **Route 53 Record Sets**: Records for the blue and green environments with failover routing policies.

Below is the Terraform HCL configuration that accomplishes this setup:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "db_instance_class" {
  default = "db.t3.micro"
}

variable "db_allocated_storage" {
  default = 20
}

variable "db_engine" {
  default = "mysql"
}

variable "db_engine_version" {
  default = "8.0"
}

variable "db_username" {
  default = "admin"
}

variable "db_password" {
  default = "securepassword123"
}

variable "db_name" {
  default = "myapp_db"
}

variable "hosted_zone_name" {
  default = "example.com."
}

variable "domain_name_blue" {
  default = "blue.example.com"
}

variable "domain_name_green" {
  default = "green.example.com"
}

# IAM Role and Instance Profile
resource "aws_iam_role" "ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonRDSFullAccess"
  role       = aws_iam_role.ec2_role.name
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.ec2_role.name
}

# RDS Database
resource "aws_db_subnet_group" "default" {
  name       = "main"
  subnet_ids = ["subnet-12345678", "subnet-87654321"] # Replace with your subnet IDs

  tags = {
    Name = "Main"
  }
}

resource "aws_db_instance" "myapp_db" {
  allocated_storage    = var.db_allocated_storage
  engine               = var.db_engine
  engine_version       = var.db_engine_version
  instance_class       = var.db_instance_class
  name                 = var.db_name
  username             = var.db_username
  password             = var.db_password
  parameter_group_name = "default.mysql8.0"
  skip_final_snapshot  = true
  db_subnet_group_name = aws_db_subnet_group.default.name
  vpc_security_group_ids = ["sg-12345678"] # Replace with your security group ID
}

# Route 53 Hosted Zone
resource "aws_route53_zone" "primary" {
  name = var.hosted_zone_name
}

# Route 53 Health Checks
resource "aws_route53_health_check" "blue_health_check" {
  fqdn              = var.domain_name_blue
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
}

resource "aws_route53_health_check" "green_health_check" {
  fqdn              = var.domain_name_green
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
}

# Route 53 Record Sets
resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name_blue
  type    = "A"
  ttl     = 300

  set_identifier = "Blue"
  weight         = 100

  failover_routing_policy {
    type = "PRIMARY"
  }

  alias {
    name                   = "ec2-12-34-56-78.compute-1.amazonaws.com" # Replace with your blue environment ELB DNS name
    zone_id                = "Z3DZXE2PTZX4RR" # Replace with your blue environment ELB hosted zone ID
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name_green
  type    = "A"
  ttl     = 300

  set_identifier = "Green"
  weight         = 100

  failover_routing_policy {
    type = "SECONDARY"
  }

  alias {
    name                   = "ec2-87-65-43-21.compute-1.amazonaws.com" # Replace with your green environment ELB DNS name
    zone_id                = "Z3DZXE2PTZX4RR" # Replace with your green environment ELB hosted zone ID
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "blue_failover_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name_blue
  type    = "A"
  ttl     = 300

  set_identifier = "BlueFailover"
  weight         = 100

  failover_routing_policy {
    type = "SECONDARY"
  }

  alias {
    name                   = "ec2-87-65-43-21.compute-1.amazonaws.com" # Replace with your green environment ELB DNS name
    zone_id                = "Z3DZXE2PTZX4RR" # Replace with your green environment ELB hosted zone ID
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "green_failover_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name_green
  type    = "A"
  ttl     = 300

  set_identifier = "GreenFailover"
  weight         = 100

  failover_routing_policy {
    type = "PRIMARY"
  }

  alias {
    name                   = "ec2-12-34-56-78.compute-1.amazonaws.com" # Replace with your blue environment ELB DNS name
    zone_id                = "Z3DZXE2PTZX4RR" # Replace with your blue environment ELB hosted zone ID
    evaluate_target_health = true
  }
}
```

### Notes:
- Replace `"subnet-12345678"` and `"subnet-87654321"` with your actual subnet IDs.
- Replace `"sg-12345678"` with your actual security group ID.
- Replace `"ec2-12-34-56-78.compute-1.amazonaws.com"` and `"ec2-87-65-43-21.compute-1.amazonaws.com"` with the actual DNS names of your blue and green environment Elastic Load Balancers (ELBs).
- Replace `"Z3DZXE2PTZX4RR"` with the actual hosted zone ID of your ELBs.
- Ensure that the health check paths (`resource_path`) and ports match your application's configuration.

This configuration sets up a blue/green deployment with failover routing in Route 53, ensuring that traffic is directed to the healthy environment.

