The Terraform program I will define will create an Elastic Beanstalk application named `my_application` and an environment for it. It will also create an IAM role named `eb_ec2_role` and an instance profile named `eb_ec2_profile` that will be attached to the EC2 instances running in the Elastic Beanstalk environment. The configuration will be deployable with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`. The AWS region will be set to `us-west-2`, but this can be changed via a variable.

Here is the Terraform HCL program:

```hcl
provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my_application"
  description = "My Elastic Beanstalk Application"
}

resource "aws_elastic_beanstalk_environment" "my_env" {
  name                = "my-env"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v5.8.3 running Corretto 17"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "4"
  }

  setting {
    namespace = "aws:ec2:instances"
    option_name = "InstanceTypes"
    value       = "t2.micro"
  }
}
```

This configuration sets up the necessary IAM role and instance profile for the Elastic Beanstalk environment and creates the application and environment itself. The `solution_stack_name` specifies the platform version for the environment, which in this case is Amazon Linux 2 with Corretto 17. You can adjust the `solution_stack_name`, `MinSize`, `MaxSize`, and `InstanceTypes` settings as needed.

