Certainly! Below is a Terraform configuration that sets up an AWS Elastic Beanstalk application running a Go application. This template includes:

- An IAM role and policy for the Elastic Beanstalk environment.
- An Elastic Beanstalk application.
- An Elastic Beanstalk application version.
- An Elastic Beanstalk environment.

This configuration assumes you have a Go application packaged into a ZIP file that you want to deploy. The ZIP file should contain your compiled Go binary and any necessary files.

### Description:
1. **IAM Role and Policy**: Creates an IAM role with policies that allow the Elastic Beanstalk environment to perform necessary actions like logging to CloudWatch.
2. **Elastic Beanstalk Application**: Defines the Elastic Beanstalk application.
3. **Elastic Beanstalk Application Version**: Uploads a version of the application to Elastic Beanstalk.
4. **Elastic Beanstalk Environment**: Creates an environment for the application using the specified version.

### Terraform Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables
variable "application_name" {
  description = "The name of the Elastic Beanstalk application"
  default     = "GoApp"
}

variable "environment_name" {
  description = "The name of the Elastic Beanstalk environment"
  default     = "GoEnv"
}

variable "version_label" {
  description = "The label for this version of the application"
  default     = "v1"
}

variable "zip_file_path" {
  description = "The path to the ZIP file containing the Go application"
  default     = "./go-app.zip"
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "eb_role" {
  name = "${var.application_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "eb_policy" {
  name        = "${var.application_name}-policy"
  description = "Policy for Elastic Beanstalk environment"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ecs:Describe*",
          "elasticloadbalancing:Describe*",
          "autoscaling:Describe*",
          "cloudwatch:PutMetricAlarm",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_policy_attachment" {
  policy_arn = aws_iam_policy.eb_policy.arn
  role       = aws_iam_role.eb_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "Elastic Beanstalk application for Go"
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "app_version" {
  application = aws_elastic_beanstalk_application.app.name
  bucket      = "your-s3-bucket-name" # Replace with your S3 bucket name
  key         = "${var.version_label}.zip"
  version_label = var.version_label

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [aws_s3_bucket_object.app_zip]
}

# Upload the ZIP file to S3
resource "aws_s3_bucket" "app_bucket" {
  bucket = "your-s3-bucket-name" # Replace with your S3 bucket name
  acl    = "private"
}

resource "aws_s3_bucket_object" "app_zip" {
  bucket = aws_s3_bucket.app_bucket.id
  key    = "${var.version_label}.zip"
  source = var.zip_file_path
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Go 1.x"
  version_label       = aws_elastic_beanstalk_application_version.app_version.version_label

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
