To provision and scale a web application using Terraform, we can use Amazon Web Services (AWS) Elastic Beanstalk. Elastic Beanstalk simplifies the deployment, from source code to a running application, and automatically handles the infrastructure scaling. 

The Terraform configuration will include:
- An AWS provider configuration.
- An IAM role and policy for the Elastic Beanstalk environment.
- An Elastic Beanstalk application.
- An Elastic Beanstalk application version.
- An Elastic Beanstalk environment.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "application_name" {
  description = "The name of the Elastic Beanstalk application"
  type        = string
  default     = "MyWebApp"
}

variable "environment_name" {
  description = "The name of the Elastic Beanstalk environment"
  type        = string
  default     = "MyWebApp-env"
}

variable "version_label" {
  description = "The label for the application version"
  type        = string
  default     = "v1.0"
}

variable "bucket_name" {
  description = "The S3 bucket name where the application version is stored"
  type        = string
  default     = "my-webapp-bucket"
}

variable "key_name" {
  description = "The S3 key name for the application version"
  type        = string
  default     = "my-webapp-v1.0.zip"
}

resource "aws_iam_role" "eb_instance_profile_role" {
  name = "${var.application_name}-instance-profile-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "eb_instance_profile_policy" {
  name        = "${var.application_name}-instance-profile-policy"
  description = "Policy for Elastic Beanstalk instance profile"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::${var.bucket_name}",
          "arn:aws:s3:::${var.bucket_name}/*"
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_instance_profile_policy_attachment" {
  policy_arn = aws_iam_policy.eb_instance_profile_policy.arn
  role       = aws_iam_role.eb_instance_profile_role.name
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "${var.application_name}-instance-profile"
  role = aws_iam_role.eb_instance_profile_role.name
}

resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "Elastic Beanstalk application for ${var.application_name}"
}

resource "aws_elastic_beanstalk_application_version" "app_version" {
  name        = var.version_label
  application = aws_elastic_beanstalk_application.app.name
  bucket      = var.bucket_name
  key         = var.key_name
}

resource "aws_elastic_beanstalk_environment" "env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Corretto 17"
  version_label       = aws_elastic_beanstalk_application_version.app_version.name

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MinSize"
    value       = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    option_name = "MaxSize"
    value       = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    option_name = "EnvironmentType"
    value       = "LoadBalanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    option_name = "IamInstanceProfile"
    value       = aws_iam_instance_profile.eb_instance_profile.name
  }
}
```

This configuration sets up an Elastic Beanstalk application and environment, along with necessary IAM roles and policies. The `solution_stack_name` can be adjusted based on the supported programming language of your web application. The `bucket_name` and `key_name` should point to the S3 location where your application version is stored.

