Certainly! Below is a Terraform configuration that creates a basic AWS CodeBuild project with an associated IAM role and a GitHub source. The configuration includes a provider setup for AWS, defines necessary IAM policies and roles, and sets up the CodeBuild project to use a GitHub repository as its source.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role and Policy**: Creates an IAM role with policies that allow CodeBuild to access necessary AWS services and GitHub.
- **CodeBuild Project**: Sets up a CodeBuild project with a GitHub source, specifying the repository and branch.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Variables with default values
variable "github_owner" {
  description = "GitHub owner (username or organization)"
  type        = string
  default     = "your-github-username"
}

variable "github_repo" {
  description = "GitHub repository name"
  type        = string
  default     = "your-repo-name"
}

variable "github_branch" {
  description = "GitHub branch to build"
  type        = string
  default     = "main"
}

variable "github_oauth_token" {
  description = "GitHub OAuth token for authentication"
  type        = string
  sensitive   = true
  default     = ""  # Ensure you set this value securely
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy"
  description = "Policy for CodeBuild to access necessary services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::codepipeline*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::codepipeline*/*"
      },
      {
        Action = [
          "codecommit:GitPull"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "example" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild project"
  service_role  = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_owner}/${var.github_repo}.git"
    git_clone_depth = 1
    auth {
      type        = "OAUTH"
      resource    = var.github_oauth_token
    }
    buildspec     = <<EOF
version: 0.2

phases:
  install:
    commands:
      - echo Installing dependencies...
  build:
    commands:
      - echo Building...
  post_build:
    commands:
      - echo Build completed on `date`
artifacts:
  files:
    - '**/*'
EOF
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:6.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "GITHUB_TOKEN"
      value = var.github_oauth_token
    }
  }

  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
      group_name = "/aws/codebuild/example-codebuild-project"
      stream_name = "build-log"
    }
  }
}
```

### Notes:
- Replace `your-github-username` and `your-repo-name` with your actual GitHub username and repository name.
- Set the `github_oauth_token` variable with a valid GitHub OAuth token. This token should have the necessary permissions to access the repository.
- The `region` in the provider block can be changed to any AWS region where you want to deploy the resources.
- Ensure that the IAM role and policies have the necessary permissions for your specific use case. The provided policies are quite broad and may need to be adjusted based on your requirements.

