Certainly! Below is a Terraform configuration that creates an AWS CodeBuild project with an example IAM role, a GitHub source, environment variables, and a cache.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role for CodeBuild**: Creates an IAM role with necessary policies for CodeBuild to access other AWS services.
- **CodeBuild Project**: Defines a CodeBuild project with:
  - A GitHub source.
  - Environment variables.
  - A cache configuration.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildAdminAccess"
  role       = aws_iam_role.codebuild_role.name
}

# Define the CodeBuild project
resource "aws_codebuild_project" "example" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild project"
  service_role  = aws_iam_role.codebuild_role.arn

  # Source configuration
  source {
    type            = "GITHUB"
    location        = "https://github.com/your-github-username/your-repo.git"
    git_clone_depth = 1
    buildspec       = "buildspec.yml"
    auth {
      type = "OAUTH"
      resource = var.github_oauth_token
    }
  }

  # Environment configuration
  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "EXAMPLE_VAR"
      value = "example-value"
    }
  }

  # Cache configuration
  cache {
    type     = "LOCAL"
    modes    = ["LOCAL_SOURCE_CACHE", "LOCAL_DOCKER_LAYER_CACHE"]
    location = "/var/cache/codebuild"
  }

  # Artifacts configuration
  artifacts {
    type = "NO_ARTIFACTS"
  }

  # Logs configuration
  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
      group_name = "/aws/codebuild/example-codebuild-project"
      stream_name = "build-log-stream"
    }
    s3_logs {
      status = "DISABLED"
    }
  }
}

# Variable for GitHub OAuth token
variable "github_oauth_token" {
  description = "GitHub OAuth token for accessing the repository"
  type        = string
  default     = "" # Provide your GitHub OAuth token here
}
```

### Notes:
- Replace `"https://github.com/your-github-username/your-repo.git"` with the URL of your GitHub repository.
- Replace `var.github_oauth_token` with your actual GitHub OAuth token or provide it via a `.tfvars` file or environment variable.
- The `AWSCodeBuildAdminAccess` policy is attached to the IAM role for simplicity, but in a production environment, it's recommended to use more restrictive policies based on your needs.
- The `location` field in the `cache` block is optional and can be omitted if not needed.

