Certainly! Below is a Terraform configuration that creates an AWS CodeBuild project with an example IAM role, a GitHub source, an artifact, and a cache. The configuration includes all necessary resources and variables with default values.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role for CodeBuild**: Creates an IAM role with policies that allow CodeBuild to access necessary AWS services.
- **CodeBuild Project**: Defines a CodeBuild project with a GitHub source, an artifact, and a cache.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "github_owner" {
  description = "GitHub repository owner"
  type        = string
  default     = "your-github-username"
}

variable "github_repo" {
  description = "GitHub repository name"
  type        = string
  default     = "your-repo-name"
}

variable "github_token" {
  description = "GitHub personal access token with repo scope"
  type        = string
  sensitive   = true
  default     = "your-github-token"
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy"
  description = "Policy for CodeBuild to access necessary AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::codepipeline-*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::codepipeline-*/*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "example" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild project"
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:6.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "GITHUB_TOKEN"
      value = var.github_token
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_owner}/${var.github_repo}.git"
    git_clone_depth = 1
    auth {
      type        = "OAUTH"
      resource    = var.github_token
    }
  }

  cache {
    type     = "LOCAL"
    modes    = ["LOCAL_DOCKER_LAYER_CACHE", "LOCAL_SOURCE_CACHE"]
  }

  tags = {
    Name = "example-codebuild-project"
  }
}
```

### Notes:
- Replace `your-github-username`, `your-repo-name`, and `your-github-token` with your actual GitHub username, repository name, and a personal access token with `repo` scope.
- The `region` in the provider block can be changed to any AWS region where you want to deploy the resources.
- The `artifacts` section is set to `NO_ARTIFACTS` for simplicity. You can modify it to store artifacts in S3 if needed.
- The `environment_variable` for `GITHUB_TOKEN` is included in the environment variables for the build, which might not be necessary depending on your build script. Adjust as needed.

