Certainly! Below is a Terraform configuration that creates an AWS CodeBuild project with an example IAM role, environment variables, secondary sources, and secondary artifacts. The configuration includes a valid provider setup for AWS and ensures all necessary resources and variables are declared.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region (`us-west-2`).
- **IAM Role**: Created specifically for the CodeBuild project with necessary policies attached.
- **CodeBuild Project**: Configured with environment variables, secondary sources, and secondary artifacts.
- **Secondary Sources**: Added a secondary source from an S3 bucket.
- **Secondary Artifacts**: Configured to store secondary artifacts in an S3 bucket.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildAdminAccess"
  role       = aws_iam_role.codebuild_role.name
}

# Create an S3 bucket for primary source and secondary artifacts
resource "aws_s3_bucket" "primary_source_bucket" {
  bucket = "primary-source-bucket-${var.bucket_suffix}"
}

resource "aws_s3_bucket" "secondary_source_bucket" {
  bucket = "secondary-source-bucket-${var.bucket_suffix}"
}

resource "aws_s3_bucket" "secondary_artifacts_bucket" {
  bucket = "secondary-artifacts-bucket-${var.bucket_suffix}"
}

# Upload a sample file to the primary source bucket
resource "aws_s3_bucket_object" "primary_source_file" {
  bucket = aws_s3_bucket.primary_source_bucket.id
  key    = "buildspec.yml"
  content = <<EOF
version: 0.2

phases:
  build:
    commands:
      - echo Build started on `date`
artifacts:
  files:
    - '**/*'
EOF
}

# Upload a sample file to the secondary source bucket
resource "aws_s3_bucket_object" "secondary_source_file" {
  bucket = aws_s3_bucket.secondary_source_bucket.id
  key    = "additional-files.zip"
  content = <<EOF
This is a zip file containing additional files.
EOF
}

# Define the CodeBuild project
resource "aws_codebuild_project" "example" {
  name          = "example-codebuild-project"
  description   = "Example CodeBuild project with secondary sources and artifacts"
  service_role  = aws_iam_role.codebuild_role.arn

  source {
    type     = "S3"
    location = "${aws_s3_bucket.primary_source_bucket.bucket}/${aws_s3_bucket_object.primary_source_file.key}"

    git_clone_depth = 1
  }

  secondary_sources {
    type     = "S3"
    location = "${aws_s3_bucket.secondary_source_bucket.bucket}/${aws_s3_bucket_object.secondary_source_file.key}"
  }

  secondary_artifacts {
    type           = "S3"
    location       = aws_s3_bucket.secondary_artifacts_bucket.bucket
    name           = "secondary-artifacts"
    namespace_type = "NONE"
    packaging      = "ZIP"
    path           = "artifacts/"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:6.0"
    type         = "LINUX_CONTAINER"

    environment_variable {
      name  = "EXAMPLE_VAR"
      value = "example-value"
    }
  }

  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
      group_name = "/aws/codebuild/example-codebuild-project"
      stream_name = "build-log-stream"
    }
  }

  tags = {
    Name = "ExampleCodeBuildProject"
  }
}

# Variables with default values
variable "bucket_suffix" {
  description = "Suffix for S3 bucket names to ensure uniqueness"
  default     = "unique-suffix"
}
```

### Explanation:
- **IAM Role**: The IAM role `codebuild-role` is created with the `AWSCodeBuildAdminAccess` policy attached, which provides full access to CodeBuild and related services.
- **S3 Buckets**: Three S3 buckets are created for primary source, secondary source, and secondary artifacts.
- **S3 Objects**: Sample files are uploaded to the primary and secondary source buckets.
- **CodeBuild Project**: Configured with a primary source from the primary S3 bucket, a secondary source from the secondary S3 bucket, and secondary artifacts stored in another S3 bucket.
- **Environment Variables**: An example environment variable `EXAMPLE_VAR` is set.
- **Logs Configuration**: CloudWatch Logs are enabled for the build logs.

This configuration is fully self-contained and can be deployed using Terraform. Make sure to adjust the `bucket_suffix` variable if needed to ensure unique bucket names.

