To create an AWS Lex bot for ordering pizzas that is meant for kids, we need to define several resources in Terraform. These resources include:

1. **IAM Role**: An IAM role that allows the Lex bot to perform necessary actions, such as logging and interacting with other AWS services.
2. **IAM Policy**: A policy that defines the permissions for the IAM role.
3. **Lex Bot**: The main Lex bot resource that will handle the conversation with users.
4. **Lex Intents**: Intents represent the action that the user wants to perform, such as "OrderPizza".
5. **Lex Slots**: Slots are the pieces of information that the bot needs to fulfill the intent, such as "PizzaType" and "Quantity".
6. **Lex Slot Types**: Custom slot types that define the possible values for the slots.

Below is the Terraform HCL configuration that sets up this infrastructure:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-policy"
  description = "Policy for Lex Bot to log and interact with other AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  policy_arn = aws_iam_policy.lex_bot_policy.arn
  role       = aws_iam_role.lex_bot_role.name
}

# Lex Slot Type for PizzaType
resource "aws_lex_slot_type" "pizza_type" {
  name = "PizzaType"

  enumeration_value {
    value = "Cheese"
  }

  enumeration_value {
    value = "Pepperoni"
  }

  enumeration_value {
    value = "Vegetarian"
  }

  enumeration_value {
    value = "Hawaiian"
  }

  enumeration_value {
    value = "Margherita"
  }
}

# Lex Slot Type for Quantity
resource "aws_lex_slot_type" "quantity" {
  name = "Quantity"

  enumeration_value {
    value = "One"
  }

  enumeration_value {
    value = "Two"
  }

  enumeration_value {
    value = "Three"
  }

  enumeration_value {
    value = "Four"
  }

  enumeration_value {
    value = "Five"
  }
}

# Lex Intent for Ordering Pizza
resource "aws_lex_intent" "order_pizza" {
  name               = "OrderPizza"
  confirmation_prompt {
    max_attempts = 2
    messages = [{
      content_type = "PlainText"
      content      = "Sure, I can order that for you. Is this correct?"
    }]
  }

  rejection_statement {
    messages = [{
      content_type = "PlainText"
      content      = "Okay, let's start over."
    }]
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  sample_utterances = [
    "I want to order a pizza",
    "Can I get a pizza?",
    "Order me a pizza"
  ]

  slot {
    name        = "PizzaType"
    slot_type   = aws_lex_slot_type.pizza_type.name
    prompt {
      max_attempts = 2
      messages = [{
        content_type = "PlainText"
        content      = "What type of pizza would you like?"
      }]
    }
    rejection_statement {
      messages = [{
        content_type = "PlainText"
        content      = "I didn't understand that. Please choose from Cheese, Pepperoni, Vegetarian, Hawaiian, or Margherita."
      }]
    }
  }

  slot {
    name        = "Quantity"
    slot_type   = aws_lex_slot_type.quantity.name
    prompt {
      max_attempts = 2
      messages = [{
        content_type = "PlainText"
        content      = "How many pizzas do you want?"
      }]
    }
    rejection_statement {
      messages = [{
        content_type = "PlainText"
        content      = "I didn't understand that. Please choose a number between one and five."
      }]
    }
  }
}

# Lex Bot for Ordering Pizza
resource "aws_lex_bot" "order_pizza_bot" {
  name                        = "OrderPizzaBot"
  locale                      = "en-US"
  child_directed              = true
  clarification_prompt {
    max_attempts = 2
    messages = [{
      content_type = "PlainText"
      content      = "I'm sorry, I didn't understand that. Can you please repeat?"
    }]
  }

  abort_statement {
    messages = [{
      content_type = "PlainText"
      content      = "Okay, let's start over."
    }]
  }

  idle_session_ttl_in_seconds = 300

  voice_id                    = "Joanna"

  process_behavior            = "BUILD"

  intents = [aws_lex_intent.order_pizza.name]

  iam_role = aws_iam_role.lex_bot_role.arn
}
```

