Below is the Terraform HCL configuration to achieve this:

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-policy"
  description = "Policy for Lex Bot to perform necessary actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  policy_arn = aws_iam_policy.lex_bot_policy.arn
  role       = aws_iam_role.lex_bot_role.name
}

# Slot Type for Pizza Types
resource "aws_lex_slot_type" "pizza_type" {
  name           = "PizzaType"
  enumeration_value {
    value = "Margherita"
  }
  enumeration_value {
    value = "Pepperoni"
  }
  enumeration_value {
    value = "Vegetarian"
  }
}

# Intent for Ordering Pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name                        = "OrderPizzaIntent"
  confirmation_prompt         = var.confirmation_prompt
  rejection_statement         = var.rejection_statement
  fulfillment_activity        = var.fulfillment_activity
  slots                       = [var.pizza_type_slot, var.quantity_slot]
  sample_utterances           = ["I want to order a pizza", "Can I order a pizza"]
  nlu_intent_confidence_threshold = 0.5
}

# Slot for Pizza Type
variable "pizza_type_slot" {
  default = {
    name        = "PizzaType"
    slot_type   = aws_lex_slot_type.pizza_type.name
    value_elicitation_prompt = {
      messages = ["What type of pizza would you like?", "Which type of pizza do you prefer?"]
      max_attempts = 3
    }
  }
}

# Slot for Quantity
variable "quantity_slot" {
  default = {
    name        = "Quantity"
    slot_type   = "AMAZON.NUMBER"
