  default = {
    messages = ["Okay, no problem. Let me know if you change your mind.", "No worries, feel free to ask if you need anything else."]
  }
}

# Fulfillment Activity for Intent
variable "fulfillment_activity" {
  default = {
    type = "ReturnIntent"
  }
}

# Lex Bot Definition
