  name                        = "OrderPizzaBot"
  locale                      = "en-US"
  child_directed              = false
  clarification_prompt        = var.clarification_prompt
  abort_statement             = var.abort_statement
  idle_session_ttl_in_seconds = 300
  voice_id                    = "Joanna"
  intents                     = [aws_lex_intent.order_pizza_intent.name]
  iam_role                    = aws_iam_role.lex_bot_role.arn
}

# Clarification Prompt for Bot
variable "clarification_prompt" {
  default = {
    messages = ["I'm not sure what you mean. Can you please repeat?", "Could you please clarify your request?"]
    max_attempts = 3
  }
}

# Abort Statement for Bot
variable "abort_statement" {
  default = {
    messages = ["Okay, let's start over.", "No problem, starting over."]
