```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-policy"
  description = "Policy for Lex Bot to perform necessary actions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "lex_bot_policy_attachment" {
  policy_arn = aws_iam_policy.lex_bot_policy.arn
  role       = aws_iam_role.lex_bot_role.name
}

# AWS Lex V2 Bot
resource "aws_lexv2models_bot" "my_lex_bot" {
  name                        = "MyLexBot"
  description                 = "A simple Lex V2 bot"
  idle_session_ttl_in_seconds = 300
  role_arn                    = aws_iam_role.lex_bot_role.arn

  data_privacy {
    child_directed = false
  }

  test_bot_alias_tags = {
    Purpose = "Testing"
  }

  voice_id = "Joanna"

  bot_locale {
    locale_id = "en_US"

    nlu_confidence_threshold = 0.5

    voice_settings {
      voice_id = "Joanna"
    }

    text_log_setting {
      enabled = true
      destination {
        cloud_watch {
          log_group_arn = aws_cloudwatch_log_group.lex_bot_logs.arn
        }
      }
    }

    sentiment_analysis_settings {
      detect_sentiment = false
    }
  }
}

# CloudWatch Log Group for Lex Bot Logs
resource "aws_cloudwatch_log_group" "lex_bot_logs" {
  name = "/aws/lex/MyLexBot"
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-east-1`).
- **IAM Role**: Creates an IAM role that Lex can assume.
- **IAM Policy**: Defines a policy that allows logging to CloudWatch.
- **IAM Role Policy Attachment**: Attaches the policy to the IAM role.
- **AWS Lex V2 Bot**: Creates a Lex V2 bot with a specified name, description, session TTL, and role ARN.
- **CloudWatch Log Group**: Creates a CloudWatch log group to store logs generated by the Lex bot.

This configuration is deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`. All necessary resources and variables are fully specified.

