}

# Create an IAM role for the Connect instance
resource "aws_iam_role" "connect_instance_role" {
  name = "connect-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "connect_instance_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonConnectFullAccess"
  role       = aws_iam_role.connect_instance_role.name
}

# Create an AWS Connect instance
resource "aws_connect_instance" "connect_instance" {
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true

  instance_alias = "kids-connect-instance"

  depends_on = [aws_iam_role_policy_attachment.connect_instance_policy]
}

# Assume you have a Lex bot already created; here we just reference it
variable "lex_bot_name" {
  description = "The name of the Lex bot to associate with the Connect instance"
  type        = string
  default     = "KidsBot" # Replace with your actual Lex bot name
}

variable "lex_bot_region" {
  description = "The region where the Lex bot is located"
  type        = string
  default     = "us-east-1"
}

# Create an IAM role for the Lex bot association
resource "aws_iam_role" "lex_bot_association_role" {
  name = "lex-bot-association-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the Lex bot association role
resource "aws_iam_role_policy_attachment" "lex_bot_association_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonLexReadOnly"
  role       = aws_iam_role.lex_bot_association_role.name
}

# Associate the Lex bot with the Connect instance
resource "aws_connect_bot_association" "bot_association" {
  instance_id = aws_connect_instance.connect_instance.id

  lex_bot {
    name            = var.lex_bot_name
    lex_region      = var.lex_bot_region
    alias_arn       = "arn:aws:lex:${var.lex_bot_region}:${data.aws_caller_identity.current.account_id}:bot-alias/${var.lex_bot_name}/$LATEST"
  }

  depends_on = [aws_iam_role_policy_attachment.lex_bot_association_policy]
}

# Data source to get the current caller identity
data "aws_caller_identity" "current" {}
```

This configuration sets up an AWS Connect instance, creates the necessary IAM roles and policies, and associates a pre-existing Lex bot with the Connect instance. Make sure to replace `"KidsBot"` with the actual name of your Lex bot if different. Also, ensure that the Lex bot exists in the specified region (`us-east-1` by default).

