To create a Kinesis Firehose Delivery Stream with an extended S3 Destination and Dynamic Partitioning enabled, we need to set up several AWS resources:

1. **IAM Role**: An IAM role for the Firehose delivery stream to write data to S3.
2. **IAM Policy**: A policy attached to the IAM role granting necessary permissions.
3. **S3 Bucket**: The destination bucket where the Firehose stream will deliver data.
4. **Kinesis Firehose Delivery Stream**: The main resource that will stream data to the S3 bucket with dynamic partitioning.

Below is the Terraform HCL configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "bucket_name" {
  description = "The name of the S3 bucket to store the Firehose data"
  default     = "my-kinesis-firehose-bucket"
}

variable "firehose_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  default     = "my-kinesis-firehose-stream"
}

# Create an S3 bucket
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = var.bucket_name

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name = "Kinesis Firehose Bucket"
  }
}

# Create an IAM role for Firehose
resource "aws_iam_role" "firehose_role" {
  name = "${var.firehose_stream_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for Firehose
resource "aws_iam_policy" "firehose_policy" {
  name        = "${var.firehose_stream_name}-policy"
  description = "Policy for Kinesis Firehose to write to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.firehose_bucket.arn,
          "${aws_s3_bucket.firehose_bucket.arn}/*"
        ]
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  policy_arn = aws_iam_policy.firehose_policy.arn
  role       = aws_iam_role.firehose_role.name
}

# Create the Kinesis Firehose Delivery Stream with S3 destination and dynamic partitioning
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = var.firehose_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn                 = aws_iam_role.firehose_role.arn
    bucket_arn               = aws_s3_bucket.firehose_bucket.arn
    buffering_size           = 5
    buffering_interval       = 300
    error_output_prefix      = "error/"
    prefix                   = "data/"
    dynamic_partitioning_configuration {
      enabled = true
      retry_options {
        duration_in_seconds = 300
      }
    }
  }

  tags = {
    Name = "Kinesis Firehose Stream"
  }
}
```

This configuration sets up an S3 bucket, an IAM role with the necessary permissions, and a Kinesis Firehose delivery stream configured to use the S3 bucket as its destination with dynamic partitioning enabled. The `buffering_size` and `buffering_interval` are set to 5 MB and 300 seconds respectively, which are common settings for such configurations. Adjust these values as needed based on your specific requirements.

