To create a Kinesis Firehose Delivery Stream with an Elasticsearch destination, we need to set up several AWS resources:

1. **IAM Role**: An IAM role for the Kinesis Firehose delivery stream to allow it to write to Elasticsearch and optionally log errors to S3.
2. **S3 Bucket**: An S3 bucket to store any error logs from the Kinesis Firehose delivery stream.
3. **Elasticsearch Domain**: An Elasticsearch domain where the data from the Kinesis Firehose will be delivered.
4. **Kinesis Firehose Delivery Stream**: The main resource that will deliver data to the Elasticsearch domain.

Below is the Terraform HCL configuration that sets up these resources:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variable for the name prefix
variable "name_prefix" {
  default = "kinesis-firehose-es"
}

# S3 bucket for storing error logs
resource "aws_s3_bucket" "firehose_error_logs" {
  bucket = "${var.name_prefix}-error-logs"
  acl    = "private"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = "${var.name_prefix}-error-logs-logging"
    target_prefix = "log/"
  }
}

# Elasticsearch domain
resource "aws_elasticsearch_domain" "es_domain" {
  domain_name           = "${var.name_prefix}-es-domain"
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type = "t2.micro.elasticsearch"
    instance_count = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp2"
    volume_size = 10
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "es.amazonaws.com"
        }
        Action    = "es:*"
        Resource  = "arn:aws:es:${var.region}:${data.aws_caller_identity.current.account_id}:domain/${aws_elasticsearch_domain.es_domain.domain_name}/*"
      },
      {
        Effect   = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose_role.arn
        }
        Action    = "es:ESHttpPost"
        Resource  = "arn:aws:es:${var.region}:${data.aws_caller_identity.current.account_id}:domain/${aws_elasticsearch_domain.es_domain.domain_name}/_bulk"
      }
    ]
  })

  tags = {
    Name = "${var.name_prefix}-es-domain"
  }
}

# IAM role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "${var.name_prefix}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM policy for Kinesis Firehose
resource "aws_iam_policy" "firehose_policy" {
  name        = "${var.name_prefix}-firehose-policy"
  description = "Policy for Kinesis Firehose to write to Elasticsearch and log errors to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "es:Describe*",
          "es:List*",
          "es:Search*",
          "es:Get*",
          "es:ESHttp*"
        ]
        Resource = "arn:aws:es:${var.region}:${data.aws_caller_identity.current.account_id}:domain/${aws_elasticsearch_domain.es_domain.domain_name}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = [
          "arn:aws:s3:::${aws_s3_bucket.firehose_error_logs.bucket}",
          "arn:aws:s3:::${aws_s3_bucket.firehose_error_logs.bucket}/*"
        ]
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  policy_arn = aws_iam_policy.firehose_policy.arn
  role       = aws_iam_role.firehose_role.name
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_to_es" {
  name        = "${var.name_prefix}-delivery-stream"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn = aws_elasticsearch_domain.es_domain.arn
    index_name = "firehose-index"
    role_arn   = aws_iam_role.firehose_role.arn

    buffering_size = 5
    buffering_interval = 300

    s3_backup_mode = "FailedDocumentsOnly"

    s3_configuration {
      role_arn   = aws_iam_role.firehose_role.arn
      bucket_arn = aws_s3_bucket.firehose_error_logs.arn
    }
  }

  tags = {
    Name = "${var.name_prefix}-delivery-stream"
  }
}

# Data source to get the current caller identity
data "aws_caller_identity" "current" {}
```

This configuration sets up all necessary components for a Kinesis Firehose Delivery Stream with an Elasticsearch destination, including the required IAM roles and policies, an S3 bucket for error logs, and an Elasticsearch domain. Make sure to adjust the `region` in the provider block if you want to deploy this in a different AWS region.

