To create a Kinesis Firehose Delivery Stream with an OpenSearch destination using Terraform, we need to set up several AWS resources:

1. **IAM Role and Policy**: The Firehose delivery stream needs an IAM role with policies that allow it to write to OpenSearch and perform other necessary actions.
2. **OpenSearch Domain**: We need an OpenSearch domain where the data from the Firehose stream will be delivered.
3. **Kinesis Firehose Delivery Stream**: This is the main resource that will deliver data to the OpenSearch domain.

Below is the complete Terraform configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "opensearch_domain_name" {
  description = "The name of the OpenSearch domain"
  default     = "my-opensearch-domain"
}

variable "firehose_delivery_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  default     = "my-firehose-stream"
}

# Create an OpenSearch domain
resource "aws_opensearch_domain" "example" {
  domain_name           = var.opensearch_domain_name
  engine_version        = "OpenSearch_1.3"
  cluster_config {
    instance_type = "t3.small.search"
    instance_count   = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp2"
    volume_size = 10
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "es:*"
        Resource  = "${aws_opensearch_domain.example.arn}/*"
      }
    ]
  })
}

# Create an IAM role for Firehose to write to OpenSearch
resource "aws_iam_role" "firehose_to_opensearch" {
  name = "firehose-to-opensearch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach policies to the IAM role
resource "aws_iam_role_policy_attachment" "firehose_to_opensearch_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisFirehoseFullAccess"
  role       = aws_iam_role.firehose_to_opensearch.name
}

resource "aws_iam_role_policy_attachment" "firehose_to_opensearch_es_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonESFullAccess"
  role       = aws_iam_role.firehose_to_opensearch.name
}

# Create the Kinesis Firehose delivery stream with OpenSearch as the destination
resource "aws_kinesis_firehose_delivery_stream" "example" {
  name        = var.firehose_delivery_stream_name
  destination = "opensearchservice"

  opensearchservice_configuration {
    domain_arn = aws_opensearch_domain.example.arn
    index_name = "my-index"
    role_arn   = aws_iam_role.firehose_to_opensearch.arn

    buffering_hints {
      interval_in_seconds = 60
      size_in_megabytes   = 5
    }

    s3_backup_mode = "FailedDocumentsOnly"

    s3_configuration {
      role_arn   = aws_iam_role.firehose_to_opensearch.arn
      bucket_arn = "arn:aws:s3:::my-backup-bucket"
    }
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region.
- **Variables**: Define the names for the OpenSearch domain and Firehose delivery stream with default values.
- **OpenSearch Domain**: Creates an OpenSearch domain with basic configurations.
- **IAM Role**: Creates an IAM role that allows Firehose to write to OpenSearch and attaches necessary policies.
- **Kinesis Firehose Delivery Stream**: Configures the Firehose delivery stream to send data to the OpenSearch domain, with buffering hints and S3 backup mode.

