To create a Kinesis Firehose Delivery Stream with an Elasticsearch Destination within a VPC using Terraform, we need to set up several AWS resources. These include:

1. **IAM Roles and Policies**: To allow Kinesis Firehose to deliver data to Elasticsearch Service and to access the VPC.
2. **VPC, Subnets, Security Groups**: To define the network environment for the Elasticsearch cluster.
3. **Elasticsearch Domain**: Configured to use the VPC.
4. **Kinesis Firehose Delivery Stream**: Configured to send data to the Elasticsearch domain.

Below is the complete Terraform configuration to achieve this setup:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "es_domain_name" {
  default = "my-es-domain"
}

variable "firehose_delivery_stream_name" {
  default = "my-firehose-stream"
}

# Create VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainIGW"
  }
}

# Create Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet-${count.index}"
  }
}

# Create Security Group for Elasticsearch
resource "aws_security_group" "es_sg" {
  name_prefix = "es-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust as necessary for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ElasticsearchSG"
  }
}

# Create Elasticsearch Domain
resource "aws_elasticsearch_domain" "main" {
  domain_name           = var.es_domain_name
  elasticsearch_version = "7.10"

  cluster_config {
    instance_type = "t2.micro.elasticsearch"
    instance_count = 1
  }

  vpc_options {
    subnet_ids = aws_subnet.public[*].id
    security_group_ids = [aws_security_group.es_sg.id]
  }

  tags = {
    Name = "MyElasticsearchDomain"
  }
}

# Create IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Attach policies to the IAM Role
resource "aws_iam_role_policy_attachment" "firehose_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseElasticsearchAccess"
  role       = aws_iam_role.firehose_role.name
}

resource "aws_iam_role_policy_attachment" "firehose_vpc_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseVPCEndpointAccess"
  role       = aws_iam_role.firehose_role.name
}

# Create Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = var.firehose_delivery_stream_name
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn = aws_elasticsearch_domain.main.arn
    index_name = "my-index"
    role_arn   = aws_iam_role.firehose_role.arn
    type_name  = "my-type"
  }

  tags = {
    Name = "MyFirehoseStream"
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region.
- **VPC Setup**: Creates a VPC, Internet Gateway, and public subnets.
- **Security Group**: Allows inbound traffic on port 443 for Elasticsearch.
- **Elasticsearch Domain**: Configured to use the VPC and security group.
- **IAM Role and Policies**: Allows Kinesis Firehose to write to Elasticsearch and access the VPC.
- **Kinesis Firehose Delivery Stream**: Configured to send data to the Elasticsearch domain.

This configuration is deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`. Adjust the `subnet_cidr_blocks`, `es_domain_name`, and `firehose_delivery_stream_name` variables as needed for your specific requirements.

