Certainly! Below is a Terraform configuration that creates an Amazon Kinesis Firehose delivery stream with an extended S3 destination. This configuration includes the necessary IAM roles and policies for the Firehose to write data to the S3 bucket.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role and Policy**: Creates an IAM role with the necessary permissions for Kinesis Firehose to write to an S3 bucket.
- **S3 Bucket**: Creates an S3 bucket where the Firehose will deliver data.
- **Kinesis Firehose Delivery Stream**: Sets up a Kinesis Firehose delivery stream with the S3 bucket as the destination.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Variables with default values
variable "bucket_name" {
  description = "The name of the S3 bucket"
  type        = string
  default     = "my-kinesis-firehose-bucket"
}

variable "firehose_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  type        = string
  default     = "my-kinesis-firehose-stream"
}

# Create an S3 bucket
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = var.bucket_name

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name = "Kinesis Firehose Bucket"
  }
}

# Create an IAM role for Kinesis Firehose
resource "aws_iam_role" "firehose_role" {
  name = "${var.firehose_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the necessary policy to the IAM role
resource "aws_iam_role_policy" "firehose_policy" {
  name = "${var.firehose_name}-policy"
  role = aws_iam_role.firehose_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::${aws_s3_bucket.firehose_bucket.id}",
          "arn:aws:s3:::${aws_s3_bucket.firehose_bucket.id}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Create the Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = var.firehose_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn                 = aws_iam_role.firehose_role.arn
    bucket_arn               = aws_s3_bucket.firehose_bucket.arn
    buffering_size           = 5
    buffering_interval       = 300
    compression_format       = "GZIP"
    error_output_prefix      = "errors/"
    prefix                   = "data/"

    dynamic_partitioning_configuration {
      enabled = true

      retry_options {
        duration_in_seconds = 300
      }
    }

    processing_configuration {
      enabled = true

      processors {
        type = "Lambda"

        parameters {
          parameter_name  = "LambdaArn"
          parameter_value = "arn:aws:lambda:us-west-2:123456789012:function:MyLambdaFunction"
        }

        parameters {
          parameter_name  = "BufferSizeInMBs"
          parameter_value = "1"
        }

        parameters {
          parameter_name  = "BufferIntervalInSeconds"
          parameter_value = "300"
        }
      }
    }
  }

  tags = {
    Name = "Kinesis Firehose Stream"
  }
}
```

### Notes:
- The `processing_configuration` section includes a Lambda processor as an example. You can modify or remove it based on your requirements.
- Replace `"arn:aws:lambda:us-west-2:123456789012:function:MyLambdaFunction"` with the actual ARN of your Lambda function if you are using one.
- Adjust the `region` in the provider block and any other settings as needed for your environment.

