To create a basic Amazon Kinesis Data Analytics application using Terraform, we will define a Kinesis Data Stream, an IAM role with necessary permissions, and the Kinesis Data Analytics application itself configured to run a SQL-based application. The Kinesis Data Analytics application will process data from the Kinesis Data Stream.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region.
- **Kinesis Data Stream**: A stream to which data records are sent.
- **IAM Role**: An IAM role with policies that allow the Kinesis Data Analytics application to read from the Kinesis Data Stream.
- **Kinesis Data Analytics Application**: A SQL-based application that processes data from the Kinesis Data Stream.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "stream_name" {
  description = "Name of the Kinesis Data Stream"
  default     = "example-kinesis-stream"
}

variable "analytics_app_name" {
  description = "Name of the Kinesis Data Analytics Application"
  default     = "example-kinesis-analytics-app"
}

# Create a Kinesis Data Stream
resource "aws_kinesis_stream" "example" {
  name        = var.stream_name
  shard_count = 1
}

# Create an IAM role for Kinesis Data Analytics
resource "aws_iam_role" "kinesis_analytics_role" {
  name = "${var.analytics_app_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "kinesis_analytics_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisReadOnlyAccess"
  role       = aws_iam_role.kinesis_analytics_role.name
}

# Create a Kinesis Data Analytics Application
resource "aws_kinesis_analytics_application" "example" {
  name = var.analytics_app_name

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.example.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    schema {
      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json_mapping_parameters {
            record_row_path = "$"
          }
        }
      }

      record_encoding = "UTF-8"
    }
  }

  outputs {
    name = "DESTINATION_SQL_STREAM"

    schema {
      record_format_type = "JSON"
    }

    kinesis_firehose {
      resource_arn = "arn:aws:firehose:us-west-2:123456789012:deliverystream/example-delivery-stream"
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }
  }

  cloudwatch_logging_options {
    log_level = "INFO"
    log_stream_arn = "arn:aws:logs:us-west-2:123456789012:log-group:/aws/kinesis-analytics/example-log-group:log-stream:example-log-stream"
    role_arn       = aws_iam_role.kinesis_analytics_role.arn
  }

  application_code = <<EOF
CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
    "ticker_symbol" VARCHAR(4),
    "sector"        VARCHAR(16),
    "change"        DOUBLE,
    "price"         DOUBLE
);

CREATE OR REPLACE PUMP "STREAM_PUMP" AS INSERT INTO "DESTINATION_SQL_STREAM"
SELECT STREAM "ticker_symbol", "sector", "change", "price"
FROM   "SOURCE_SQL_STREAM";
EOF
}
```

### Notes:
- The `kinesis_firehose` output and `cloudwatch_logging_options` are included for completeness but require existing Firehose delivery streams and CloudWatch log groups/streams. You can modify these ARNs to match your existing resources or remove them if not needed.
- The `application_code` is a simple SQL example that reads from the source stream and writes to the destination stream. Modify this code according to your specific use case.
- Ensure that the AWS account has the necessary permissions to create and manage Kinesis Data Streams, IAM roles, and Kinesis Data Analytics applications.

