  description = "The name of the primary DNS record"
  type        = string
  default     = "www"
}

variable "secondary_record_name" {
  description = "The name of the secondary DNS record"
  type        = string
  default     = "www"
}

variable "primary_target" {
  description = "The IP address or domain name of the primary target"
  type        = string
  default     = "192.0.2.1"  # Replace with your actual primary target
}

variable "secondary_target" {
  description = "The IP address or domain name of the secondary target"
  type        = string
  default     = "192.0.2.2"  # Replace with your actual secondary target
}

resource "aws_route53_zone" "primary" {
  name = "primary.example.com"  # Replace with your actual domain name
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = var.fqdn
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
}

resource "aws_route53_record" "primary_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "${var.primary_record_name}.${aws_route53_zone.primary.name}"
  type    = "A"

  set_identifier = "Primary"
  ttl            = 60

  weighted_routing_policy {
    weight = 100
  }

  health_check_id = aws_route53_health_check.primary_health_check.id

  alias {
    name                   = var.primary_target
    zone_id                = "Z1K5UJ28D1V33F"  # Replace with the correct zone ID for your primary target
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "secondary_record" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = "${var.secondary_record_name}.${aws_route53_zone.primary.name}"
  type    = "A"

  set_identifier = "Secondary"
  ttl            = 60

  failover_routing_policy {
    type = "SECONDARY"
  }

  alias {
    name                   = var.secondary_target
    zone_id                = "Z1K5UJ28D1V33F"  # Replace with the correct zone ID for your secondary target
    evaluate_target_health = false
  }
}
```

### Notes:
- Replace `primary.example.com` with your actual domain name.
- Replace `example.com` with the actual FQDN you want to monitor.
- Replace `192.0.2.1` and `192.0.2.2` with the actual IP addresses or domain names of your primary and secondary targets.
- Replace `Z1K5UJ28D1V33F` with the correct Route 53 Hosted Zone ID for your primary and secondary targets.
- The `region` in the provider block can be changed to any AWS region where you want to deploy the resources.

This configuration sets up a basic active-passive failover setup using Route 53. The primary record will be served if it passes the health check, and the secondary record will be served if the primary record fails.

