### Description

The Terraform program will create an AWS EKS (Elastic Kubernetes Service) cluster using a provided `cluster_name` variable. It will configure the EKS cluster with specified VPC subnet IDs for networking. An IAM role will be created and attached to the EKS cluster with necessary policies for managing the cluster and its services. The program will use `local-exec` provisioners to manage the `kubectl` configuration during the creation and destruction of the EKS cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = "my-eks-cluster"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the EKS cluster"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]  # Replace with your subnet IDs
}

variable "vpc_id" {
  description = "VPC ID for the EKS cluster"
  type        = string
  default     = "vpc-0123456789abcdef0"  # Replace with your VPC ID
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "${var.cluster_name}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_eks_cluster" "this" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_service_policy,
  ]

  provisioner "local-exec" {
    command = <<EOF
aws eks --region ${provider.aws.region} update-kubeconfig --name ${var.cluster_name}
EOF
  }

  provisioner "local-exec" {
    when    = destroy
    command = <<EOF
kubectl config delete-context ${var.cluster_name}
EOF
  }
}
```

### Notes:
