  description = "The ARN of the IAM policy to attach"
  type        = string
  default     = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

variable "principal_arn" {
  description = "The ARN of the principal (e.g., IAM user or role)"
  type        = string
  default     = "arn:aws:iam::123456789012:user/example-user"
}

