}

variable "subnet_cidrs" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create VPC
resource "aws_vpc" "demo_eks" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "demo_eks" {
  vpc_id = aws_vpc.demo_eks.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

# Create Public Subnets
resource "aws_subnet" "demo_eks_public" {
  count                   = length(var.subnet_cidrs)
  vpc_id                  = aws_vpc.demo_eks.id
  cidr_block              = element(var.subnet_cidrs, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "${var.cluster_name}-public-subnet-${count.index + 1}"
  }
}

# Create Route Table for Public Subnets
resource "aws_route_table" "demo_eks_public" {
  vpc_id = aws_vpc.demo_eks.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo_eks.id
  }

  tags = {
    Name = "${var.cluster_name}-public-route-table"
  }
}

# Associate Route Table with Public Subnets
resource "aws_route_table_association" "demo_eks_public" {
  count          = length(var.subnet_cidrs)
  subnet_id      = element(aws_subnet.demo_eks_public.*.id, count.index)
  route_table_id = aws_route_table.demo_eks_public.id
}

# Create Security Group for EKS Cluster
resource "aws_security_group" "demo_eks_cluster" {
  name_prefix = "${var.cluster_name}-cluster-sg"
  vpc_id      = aws_vpc.demo_eks.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.cluster_name}-cluster-sg"
  }
}

# Create IAM Role for EKS
resource "aws_iam_role" "demo_eks" {
  name = var.cluster_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = var.cluster_name
  }
}

# Attach AmazonEKSClusterPolicy to IAM Role
resource "aws_iam_role_policy_attachment" "demo_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.demo_eks.name
}

# Attach AmazonEKSVPCResourceController to IAM Role
resource "aws_iam_role_policy_attachment" "demo_eks_vpc_resource_controller_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.demo_eks.name
}

# Create EKS Cluster
resource "aws_eks_cluster" "demo_eks" {
  name     = var.cluster_name
  role_arn = aws_iam_role.demo_eks.arn

  vpc_config {
    subnet_ids = aws_subnet.demo_eks_public[*].id
    security_group_ids = [aws_security_group.demo_eks_cluster.id]
  }

  depends_on = [
    aws_iam_role_policy_attachment.demo_eks_cluster_policy,
    aws_iam_role_policy_attachment.demo_eks_vpc_resource_controller_policy
  ]

  tags = {
    Name = var.cluster_name
  }
}
```

This configuration ensures that the IAM role is created with the necessary policies before the EKS cluster is created, thus maintaining proper dependency handling. All required resources and variables are fully specified within the configuration.

