### Description

The Terraform program will create two AWS S3 buckets:
1. A bucket for CloudGoat data storage with a private ACL and ownership controls set for ObjectWriter access. The bucket name will dynamically incorporate the `bucket_suffix` variable.
2. A bucket for web data storage with a similar dynamic name. This bucket will have public access block settings configured to ignore public ACLs, block public ACLs, and restrict public buckets. An object named `order_data2.csv` will be uploaded to this bucket from a local file path.

Additionally, a bucket policy will be created to allow the `s3:PutObject` action for all principals on the web data bucket's objects.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_suffix" {
  description = "Suffix to append to bucket names"
  type        = string
  default     = "test"
}

resource "aws_s3_bucket" "cloudgoat_data" {
  bucket = "cloudgoat-data-${var.bucket_suffix}"

  acl = "private"

  ownership_controls {
    rule {
      object_ownership = "ObjectWriter"
    }
  }

  tags = {
    Name        = "CloudGoat Data Bucket"
    Environment = "Test"
  }
}

resource "aws_s3_bucket" "web_data" {
  bucket = "web-data-${var.bucket_suffix}"

  acl = "public-read"

  public_access_block_configuration {
    block_public_acls   = true
    ignore_public_acls  = true
    restrict_public_buckets = true
  }

  tags = {
    Name        = "Web Data Bucket"
    Environment = "Test"
  }
}

resource "aws_s3_bucket_object" "order_data2_csv" {
  bucket = aws_s3_bucket.web_data.id
  key    = "order_data2.csv"
  source = "./order_data2.csv"
}

resource "aws_s3_bucket_policy" "web_data_policy" {
  bucket = aws_s3_bucket.web_data.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = "*",
        Action = "s3:PutObject",
        Resource = "${aws_s3_bucket.web_data.arn}/*"
      }
    ]
  })
}
```

### Notes
- Ensure that the `order_data2.csv` file exists at the specified local file path (`./order_data2.csv`) before running the Terraform apply command.
- The region is set to `us-west-2`, but you can change it to any other region as per your requirement.
- The `bucket_suffix` variable has a default value of `"test"`, which can be overridden when running the Terraform configuration.

