The Terraform program will create the following resources:

1. An SNS topic named `s3-event-notification-topic`.
2. An IAM policy document that allows the `s3.amazonaws.com` service to publish to the SNS topic, with a condition that restricts the action to a specific S3 bucket.
3. An IAM policy attached to the SNS topic's resource policy.
4. An S3 bucket named `your-bucket-name`.
5. A notification configuration on the S3 bucket to send `s3:ObjectCreated:*` events with a `.log` suffix to the SNS topic.

Below is the Terraform HCL code to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

resource "aws_sns_topic" "s3_event_notification_topic" {
  name = "s3-event-notification-topic"
}

data "aws_iam_policy_document" "sns_publish_policy" {
  statement {
    effect = "Allow"

    actions = [
      "SNS:Publish",
    ]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    resources = [
      aws_sns_topic.s3_event_notification_topic.arn,
    ]

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.your_bucket_name.arn]
    }
  }
}

resource "aws_sns_topic_policy" "sns_topic_policy" {
  arn    = aws_sns_topic.s3_event_notification_topic.arn
  policy = data.aws_iam_policy_document.sns_publish_policy.json
}

resource "aws_s3_bucket" "your_bucket_name" {
  bucket = "your-bucket-name"  # Ensure this bucket name is globally unique

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle_rule {
    id      = "log-expiration"
    enabled = true

    noncurrent_version_expiration {
      noncurrent_days = 30
    }
  }
}

resource "aws_s3_bucket_notification" "bucket_notification" {
  bucket = aws_s3_bucket.your_bucket_name.id

  topic {
    topic_arn = aws_sns_topic.s3_event_notification_topic.arn
    events    = ["s3:ObjectCreated:*"]

    filter_prefix = ""
    filter_suffix = ".log"
  }
}
```

This configuration sets up the necessary AWS resources and policies to enable S3 event notifications for `.log` files created in the specified S3 bucket, sending those notifications to the designated SNS topic. Make sure to replace `"your-bucket-name"` with a globally unique bucket name before deploying.

