### Description

The Terraform configuration provided below sets up two AWS S3 buckets with distinct names. The first bucket (`primary_bucket`) is configured with private access control, while the second bucket (`log_bucket`) is configured to allow log delivery writes from the `primary_bucket`. Additionally, S3 bucket logging is enabled on the `primary_bucket` to send its logs to the `log_bucket`, with a specified log file prefix.

### Terraform Configuration

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "primary_bucket_name" {
  default = "my-primary-bucket-unique-name"
}

variable "log_bucket_name" {
  default = "my-log-bucket-unique-name"
}

variable "log_file_prefix" {
  default = "logs/"
}

# IAM policy for log delivery
resource "aws_iam_policy" "s3_log_delivery_policy" {
  name        = "S3LogDeliveryPolicy"
  description = "Policy to allow S3 log delivery"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action = [
          "s3:PutObject"
        ],
        Resource = [
          "${aws_s3_bucket.log_bucket.arn}/*"
        ],
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Effect = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action = [
          "s3:GetBucketAcl"
        ],
        Resource = [
          aws_s3_bucket.log_bucket.arn
        ]
      }
    ]
  })
}

# IAM role for log delivery
resource "aws_iam_role" "s3_log_delivery_role" {
  name = "S3LogDeliveryRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "s3_log_delivery_policy_attachment" {
  policy_arn = aws_iam_policy.s3_log_delivery_policy.arn
  role       = aws_iam_role.s3_log_delivery_role.name
}

# Primary S3 bucket with private ACL
resource "aws_s3_bucket" "primary_bucket" {
  bucket = var.primary_bucket_name
  acl    = "private"

  logging {
    target_bucket = aws_s3_bucket.log_bucket.id
    target_prefix = var.log_file_prefix
  }

  tags = {
    Name        = "Primary Bucket"
    Environment = "production"
  }
}

# Log S3 bucket with log delivery write permissions
resource "aws_s3_bucket" "log_bucket" {
  bucket = var.log_bucket_name
  acl    = "log-delivery-write"

  tags = {
    Name        = "Log Bucket"
    Environment = "production"
  }
}
```

### Explanation

1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **Variables**: Three variables are defined with default values:
   - `primary_bucket_name`: The name of the primary bucket.
   - `log_bucket_name`: The name of the log bucket.
   - `log_file_prefix`: The prefix for log files stored in the log bucket.
3. **IAM Policy and Role**: An IAM policy and role are created to allow S3 log delivery to the `log_bucket`.
4. **Primary S3 Bucket**: Configured with a private ACL and logging enabled to send logs to the `log_bucket` with a specified prefix.
5. **Log S3 Bucket**: Configured with a `log-delivery-write` ACL to allow log delivery from the `primary_bucket`.

This configuration ensures that the `primary_bucket` logs are securely stored in the `log_bucket` with appropriate access controls.

