### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role**: Creates an IAM role with policies to allow S3 operations.
- **S3 Bucket**: Creates an S3 bucket with a specified name.
- **S3 Bucket Object**: Uploads an object to the S3 bucket with a specified key and source file path.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Variables with default values
variable "bucket_name" {
  description = "The name of the S3 bucket"
  default     = "your_bucket_name"
}

variable "object_key" {
  description = "The key for the S3 object"
  default     = "new_object_key"
}

variable "source_file_path" {
  description = "The path to the source file to upload"
  default     = "path/to/file"
}

# IAM Role for S3 Operations
resource "aws_iam_role" "s3_access_role" {
  name = "s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for S3 Operations
resource "aws_iam_policy" "s3_access_policy" {
  name        = "s3-access-policy"
  description = "Policy to allow S3 operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::${var.bucket_name}",
          "arn:aws:s3:::${var.bucket_name}/*"
        ]
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "s3_access_policy_attachment" {
  policy_arn = aws_iam_policy.s3_access_policy.arn
  role       = aws_iam_role.s3_access_role.name
}

# S3 Bucket
resource "aws_s3_bucket" "my_bucket" {
  bucket = var.bucket_name

  tags = {
    Name        = "MyBucket"
    Environment = "Dev"
  }
}

# S3 Bucket Object
resource "aws_s3_bucket_object" "my_object" {
  bucket = aws_s3_bucket.my_bucket.id
  key    = var.object_key
  source = var.source_file_path
}
```

### Notes:
- Ensure that the `source_file_path` points to a valid file on your local system.
- The IAM role created here assumes it will be assumed by an EC2 instance. If you're running this from a different context, adjust the `assume_role_policy` accordingly.
- The region specified in the provider block (`us-west-2`) can be changed to any other AWS region as per your requirement.
- This configuration assumes you have the necessary permissions to create IAM roles and policies in your AWS account.

