### Description

The Terraform program will create a Virtual Private Cloud (VPC) with one public and one private subnet. An EC2 Fleet will be defined to launch a total of 9 instances: 5 On-Demand and 4 Spot Instances. The instances will use the latest Amazon Linux 2 AMI. A Launch Template will be created to ensure configuration consistency across all instances.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainInternetGateway"
  }
}

# Create a Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet"
  }
}

# Create a Route Table for Public Subnet
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

# Associate the Public Subnet with the Public Route Table
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Create a Private Subnet
resource "aws_subnet" "private" {
  vpc_id     = aws_vpc.main.id
  cidr_block = var.private_subnet_cidr_block

  tags = {
    Name = "PrivateSubnet"
  }
}

# Create an IAM Role for EC2 Instances
resource "aws_iam_role" "ec2_fleet_role" {
  name = "EC2FleetRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM Role
resource "aws_iam_role_policy_attachment" "ec2_fleet_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2SpotFleetTaggingRole"
  role       = aws_iam_role.ec2_fleet_role.name
}

# Create an IAM Instance Profile
resource "aws_iam_instance_profile" "ec2_fleet_profile" {
  name = "EC2FleetProfile"
  role = aws_iam_role.ec2_fleet_role.name
}

# Get the latest Amazon Linux 2 AMI
data "aws_ami" "amazon_linux2" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  owners = ["amazon"]
}

# Create a Launch Template
resource "aws_launch_template" "ec2_fleet_lt" {
  name_prefix   = "EC2FleetLT-"
  image_id      = data.aws_ami.amazon_linux2.id
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_profile.name
  }

  network_interfaces {
    associate_public_ip_address = true
    subnet_id                   = aws_subnet.public.id
  }

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "EC2FleetInstance"
    }
  }
}

# Create an EC2 Fleet
resource "aws_ec2_fleet" "main" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.ec2_fleet_lt.id
    }

    override {
      instance_requirements {
        memory_mib {
          min = 512
        }
        vcpu_count {
          min = 1
        }
      }
    }
  }

  target_capacity_specification {
    default_target_capacity_type = "spot"
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
    total_target_capacity        = 9
  }

  type = "maintain"

  tags = {
    Name = "MainEC2Fleet"
  }
}
```

This Terraform configuration sets up a VPC with a public and private subnet, creates an IAM role and instance profile for EC2 instances, defines a launch template using the latest Amazon Linux 2 AMI, and finally launches an EC2 Fleet with 5 On-Demand and 4 Spot Instances. All necessary resources and variables are fully specified.

