To provide a Redis instance using Terraform, we will create an AWS ElastiCache cluster configured for Redis. This setup includes creating an IAM role with necessary permissions if required, defining the VPC and subnet group for the ElastiCache cluster, and setting up the security group to control access to the Redis instance.

The Terraform configuration will:
- Define the AWS provider with a specific region.
- Create a VPC and subnets.
- Create an ElastiCache subnet group.
- Create a security group to allow traffic on the Redis port (6379).
- Create an ElastiCache cluster with Redis engine.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "List of CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "redis_port" {
  description = "Port for Redis"
  default     = 6379
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "RedisVPC"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "RedisIGW"
  }
}

# Create Subnets
resource "aws_subnet" "main" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "RedisSubnet-${count.index}"
  }
}

# Create Route Table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "RedisRouteTable"
  }
}

# Associate Route Table with Subnets
resource "aws_route_table_association" "main" {
  count          = length(aws_subnet.main)
  subnet_id      = element(aws_subnet.main.*.id, count.index)
  route_table_id = aws_route_table.main.id
}

# Create Security Group for Redis
resource "aws_security_group" "redis" {
  name_prefix = "redis-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = var.redis_port
    to_port     = var.redis_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust this to restrict access as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "RedisSecurityGroup"
  }
}

# Create ElastiCache Subnet Group
resource "aws_elasticache_subnet_group" "main" {
  name       = "redis-subnet-group"
  subnet_ids = aws_subnet.main[*].id

  tags = {
    Name = "RedisSubnetGroup"
  }
}

# Create ElastiCache Cluster
resource "aws_elasticache_cluster" "main" {
  cluster_id           = "redis-cluster"
  engine               = "redis"
  node_type            = "cache.t3.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis6.x"
  subnet_group_name    = aws_elasticache_subnet_group.main.name
  security_group_ids   = [aws_security_group.redis.id]

  tags = {
    Name = "RedisCluster"
  }
}
```

This configuration sets up a basic Redis instance in AWS using ElastiCache. The VPC, subnets, route tables, and security groups are also created to support the Redis instance. You can adjust the `subnet_cidr_blocks` and `redis_port` variables as needed. The security group allows inbound traffic on the Redis port from any IP address (`0.0.0.0/0`), which you should restrict to specific IPs in a production environment.

