data "aws_subnets" "default" {
  filter {
    name   = "default-for-az"
    values = ["true"]
  }
}

# Define a Redshift cluster parameter group
resource "aws_redshift_cluster_parameter_group" "redshift_parameter_group" {
  name   = "redshift-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = {
    Name = "redshift-parameter-group"
  }
}

# Define an IAM role for the Redshift cluster
