### Description

The Terraform program will create a Virtual Private Cloud (VPC) in the `us-east-1` region. Within this VPC, two subnets will be created in the availability zones `us-east-1a` and `us-east-1b`. Additionally, a Redshift subnet group will be created using these two subnets.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_a_cidr_block" {
  description = "CIDR block for the subnet in us-east-1a"
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr_block" {
  description = "CIDR block for the subnet in us-east-1b"
  default     = "10.0.2.0/24"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainIGW"
  }
}

# Create subnets in us-east-1a and us-east-1b
resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr_block
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "SubnetA"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr_block
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = true

  tags = {
    Name = "SubnetB"
  }
}

# Create a Redshift subnet group
resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "RedshiftSubnetGroup"
  }
}
```

This configuration sets up a VPC with two subnets in different availability zones and creates a Redshift subnet group using those subnets. The necessary resources are fully specified, and all variables have default values provided.

