LLM Output #0:
To set up a 2-node Amazon Redshift cluster in `us-east-1` and replicate it to `us-east-2`, we need to create several resources including Redshift clusters, IAM roles for Redshift, and replication configurations. 

The Terraform program will:
1. Define the AWS provider for both regions (`us-east-1` and `us-east-2`).
2. Create an IAM role with necessary policies for Redshift in both regions.
3. Set up a Redshift cluster in `us-east-1`.
4. Configure cross-region replication from the primary cluster in `us-east-1` to the secondary cluster in `us-east-2`.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = var.region_primary
}

provider "aws" {
  alias  = "secondary"
  region = var.region_secondary
}

variable "region_primary" {
  description = "Primary AWS region for Redshift cluster"
  type        = string
  default     = "us-east-1"
}

variable "region_secondary" {
  description = "Secondary AWS region for Redshift cluster"
  type        = string
  default     = "us-east-2"
}

variable "cluster_identifier_primary" {
  description = "Identifier for the primary Redshift cluster"
  type        = string
  default     = "redshift-primary-cluster"
}

variable "cluster_identifier_secondary" {
  description = "Identifier for the secondary Redshift cluster"
  type        = string
  default     = "redshift-secondary-cluster"
}

variable "node_type" {
  description = "Node type for the Redshift clusters"
  type        = string
  default     = "dc2.large"
}

variable "number_of_nodes" {
  description = "Number of nodes in the Redshift clusters"
  type        = number
  default     = 2
}

variable "master_username" {
  description = "Master username for the Redshift clusters"
  type        = string
  default     = "adminuser"
}

variable "master_password" {
  description = "Master password for the Redshift clusters"
  type        = string
  sensitive   = true
  default     = "yourStrong(!)Password123"
}

resource "aws_iam_role" "redshift_role_primary" {
  name = "${var.cluster_identifier_primary}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_policy_primary" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.redshift_role_primary.name
}

resource "aws_iam_role" "redshift_role_secondary" {
  provider = aws.secondary

  name = "${var.cluster_identifier_secondary}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_policy_secondary" {
  provider = aws.secondary

  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.redshift_role_secondary.name
}

resource "aws_redshift_cluster" "primary" {
  cluster_identifier                  = var.cluster_identifier_primary
  node_type                           = var.node_type
  master_username                     = var.master_username
  master_password                     = var.master_password
  iam_roles                           = [aws_iam_role.redshift_role_primary.arn]
  cluster_subnet_group_name           = "default"
  automated_snapshot_retention_period = 1
  allow_version_upgrade               = true
  skip_final_snapshot                 = true
}

resource "aws_redshift_cluster" "secondary" {
  provider = aws.secondary

  cluster_identifier                  = var.cluster_identifier_secondary
  node_type                           = var.node_type
  master_username                     = var.master_username
  master_password                     = var.master_password
  iam_roles                           = [aws_iam_role.redshift_role_secondary.arn]
  cluster_subnet_group_name           = "default"
  automated_snapshot_retention_period = 1
  allow_version_upgrade               = true
  skip_final_snapshot                 = true
}

resource "aws_redshift_event_subscription" "primary" {
  subscription_name = "${var.cluster_identifier_primary}-event-subscription"
  sns_topic_arn     = aws_sns_topic.redshift_events.arn
  source_type       = "cluster"
  source_ids        = [aws_redshift_cluster.primary.id]
  event_categories  = ["configuration", "management", "monitoring", "security"]
}

resource "aws_redshift_event_subscription" "secondary" {
  provider = aws.secondary

  subscription_name = "${var.cluster_identifier_secondary}-event-subscription"
  sns_topic_arn     = aws_sns_topic.redshift_events.arn
  source_type       = "cluster"
  source_ids        = [aws_redshift_cluster.secondary.id]
  event_categories  = ["configuration", "management", "monitoring", "security"]
}

resource "aws_sns_topic" "redshift_events" {
  name = "redshift-events"
}

resource "aws_redshift_snapshot_copy_grant" "primary" {
  snapshot_copy_grant_name = "${var.cluster_identifier_primary}-snapshot-copy-grant"
}

resource "aws_redshift_snapshot_copy_grant" "secondary" {
  provider = aws.secondary

  snapshot_copy_grant_name = "${var.cluster_identifier_secondary}-snapshot-copy-grant"
}

resource "aws_redshift_cluster_snapshot_schedule_association" "primary" {
  cluster_identifier         = aws_redshift_cluster.primary.id
  snapshot_schedule_identifier = aws_redshift_snapshot_schedule.schedule.id
}

resource "aws_redshift_cluster_snapshot_schedule_association" "secondary" {
  provider = aws.secondary

  cluster_identifier         = aws_redshift_cluster.secondary.id
  snapshot_schedule_identifier = aws_redshift_snapshot_schedule.schedule.id
}

resource "aws_redshift_snapshot_schedule" "schedule" {
  schedule_definitions = ["cron(0 23 * * ? *)"] # Daily at 11 PM UTC
}

resource "aws_redshift_cluster_cross_region_copy_configuration" "primary" {
  destination_region         = var.region_secondary
  retention_period           = 7
  snapshot_copy_grant_name   = aws_redshift_snapshot_copy_grant.primary.snapshot_copy_grant_name
  manual_snapshot_retention_period = 7
}

resource "aws_redshift_cluster" "primary_with_replication" {
  cluster_identifier                  = var.cluster_identifier_primary
  node_type                           = var.node_type
  master_username                     = var.master_username
  master_password                     = var.master_password
  iam_roles                           = [aws_iam_role.redshift_role_primary.arn]
  cluster_subnet_group_name           = "default"
  automated_snapshot_retention_period = 1
  allow_version_upgrade               = true
  skip_final_snapshot                 = true
  snapshot_copy_grants                = [aws_redshift_snapshot_copy_grant.primary.snapshot_copy_grant_name]
  cross_region_copy_configuration     = [aws_redshift_cluster_cross_region_copy_configuration.primary]
}
```

### Explanation:
- **Providers**: Configured for both `us-east-1` and `us-east-2`.
- **IAM Roles**: Created for both clusters with S3 read-only access.
- **Redshift Clusters**: Two clusters, one in each region.
- **Event Subscriptions**: For monitoring events on both clusters.
- **Snapshot Copy Grants**: To enable snapshot copying between regions.
- **Snapshot Schedule**: Daily snapshots at 11 PM UTC.
- **Cross-Region Copy Configuration**: Configures the primary cluster to copy snapshots to the secondary region.

This configuration ensures that the Redshift cluster in `us-east-1` is replicated to `us-east-2` using snapshot copying. Adjust the `master_password` and other parameters as needed before deployment.

