  iam_roles                           = [aws_iam_role.redshift_role.arn]
  cluster_type                        = "multi-node"
  number_of_nodes                     = 2
  publicly_accessible                 = false
  skip_final_snapshot                 = true  # For demonstration purposes; set to false in production
}

# Create a resource policy for the Redshift cluster
resource "aws_redshift_resource_policy" "redshift_resource_policy" {
  resource_arn = aws_redshift_cluster.redshift_cluster.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "redshift:GetClusterCredentials",
          "redshift:DescribeClusters"
        ]
        Condition = {
          StringEqualsIgnoreCase = {
            "aws:SourceVpc" = "vpc-12345678"  # Replace with your VPC ID
          }
        }
      },
    ]
  })
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured to use the `us-west-2` region. You can change this to any other region as per your requirement.
- **IAM Role**: An IAM role named `redshift-cluster-role` is created, which allows Redshift to assume the role. The role is attached with the `AmazonS3ReadOnlyAccess` policy, which provides read-only access to S3 buckets.
- **Redshift Cluster**: A Redshift cluster named `my-redshift-cluster` is created with two nodes (`dc2.large`). The cluster uses the IAM role created earlier. The `skip_final_snapshot` parameter is set to `true` for demonstration purposes; in a production environment, you should set it to `false` and manage snapshots appropriately.
- **Resource Policy**: A resource policy is attached to the Redshift cluster, allowing actions like `GetClusterCredentials` and `DescribeClusters` from a specific VPC (`vpc-12345678`). Replace `vpc-12345678` with your actual VPC ID.

Make sure to replace placeholder values such as `yourpassword123` and `vpc-12345678` with appropriate values before deploying the configuration.

