Certainly! Below is a Terraform configuration that creates a CloudWatch Metric Alarm. This alarm will monitor the CPU utilization of an EC2 instance and trigger if the average CPU usage exceeds 80% over a period of 5 minutes.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region (`us-west-2`).
- **IAM Role**: An IAM role is created with permissions to publish to CloudWatch Logs, which is necessary for the alarm actions.
- **CloudWatch Metric Alarm**: Monitors the `CPUUtilization` metric of an EC2 instance. The alarm triggers when the average CPU utilization exceeds 80% over a 5-minute period.
- **SNS Topic**: An SNS topic is created to send notifications when the alarm state changes.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an SNS topic for alarm notifications
resource "aws_sns_topic" "alarm_notifications" {
  name = "cloudwatch-alarm-notifications"
}

# Create an IAM policy for publishing to CloudWatch Logs
resource "aws_iam_policy" "cloudwatch_logs_publish" {
  name        = "cloudwatch_logs_publish_policy"
  description = "Policy to allow publishing to CloudWatch Logs"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "*"
      }
    ]
  })
}

# Create an IAM role for the alarm actions
resource "aws_iam_role" "alarm_actions_role" {
  name = "cloudwatch_alarm_actions_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_cloudwatch_logs_publish" {
  policy_arn = aws_iam_policy.cloudwatch_logs_publish.arn
  role       = aws_iam_role.alarm_actions_role.name
}

# Create a CloudWatch Metric Alarm
resource "aws_cloudwatch_metric_alarm" "high_cpu_utilization" {
  alarm_name          = "HighCPUUtilization"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 1
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 300
  statistic           = "Average"
  threshold           = 80

  dimensions = {
    InstanceId = var.ec2_instance_id
  }

  alarm_description = "This metric monitors ec2 cpu utilization"
  alarm_actions     = [aws_sns_topic.alarm_notifications.arn]
}
```

### Variables:
- `ec2_instance_id`: The ID of the EC2 instance to monitor. You need to provide this value when applying the configuration.

### Usage:
To apply this configuration, save it to a file (e.g., `main.tf`), and then run the following commands in your terminal:

```bash
terraform init
terraform plan -var="ec2_instance_id=i-1234567890abcdef0"
terraform apply -var="ec2_instance_id=i-1234567890abcdef0"
```

Replace `i-1234567890abcdef0` with the actual ID of your EC2 instance.

