To address your request, I'll create a Terraform configuration that sets up a DynamoDB Global Table with a primary region and a replica in another region. The configuration will include necessary IAM roles for DynamoDB to manage the global table.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region (us-west-2 in this case).
- **DynamoDB Global Table**: Created with a primary region (`us-west-2`) and a replica in another region (`us-east-1`).
- **IAM Role**: Created with necessary permissions for DynamoDB to manage the global table.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = var.primary_region
}

variable "primary_region" {
  type    = string
  default = "us-west-2"
}

variable "replica_region" {
  type    = string
  default = "us-east-1"
}

resource "aws_iam_role" "dynamodb_global_table_role" {
  name = "dynamodb-global-table-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "dynamodb_global_table_policy" {
  name        = "dynamodb-global-table-policy"
  description = "Policy for DynamoDB Global Table"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:CreateTable",
          "dynamodb:DeleteTable",
          "dynamodb:UpdateTable",
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:DescribeStream",
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:ListStreams"
        ],
        Effect   = "Allow",
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dynamodb_global_table_policy_attachment" {
  policy_arn = aws_iam_policy.dynamodb_global_table_policy.arn
  role       = aws_iam_role.dynamodb_global_table_role.name
}

resource "aws_dynamodb_global_table" "example" {
  name           = "example-global-table"
  billing_mode   = "PAY_PER_REQUEST"
  replica {
    region_name = var.primary_region
  }
  replica {
    region_name = var.replica_region
  }

  depends_on = [aws_iam_role_policy_attachment.dynamodb_global_table_policy_attachment]
}
```

This configuration sets up a DynamoDB Global Table named `example-global-table` with a primary region and a replica in another region. It also creates an IAM role with the necessary permissions for DynamoDB to manage the global table. The `depends_on` argument ensures that the IAM role policy attachment is completed before creating the global table.

