To create a SageMaker Space resource using Terraform, we need to set up the necessary AWS provider configuration, define the required variables, and create the IAM roles and policies needed for the SageMaker Space. The SageMaker Space requires a Domain to be created first, and then a User Profile can be created within that Domain. Finally, a Space can be created within the User Profile.

Below is a complete Terraform configuration that sets up a SageMaker Domain, a User Profile, and a Space. This configuration includes the necessary IAM roles and policies.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **Variables**: Defines variables for the region, domain name, user profile name, and space name with default values.
- **IAM Role and Policy**: Creates an IAM role and policy that allows SageMaker to perform necessary actions.
- **SageMaker Domain**: Creates a SageMaker Domain.
- **User Profile**: Creates a User Profile within the SageMaker Domain.
- **SageMaker Space**: Creates a SageMaker Space within the User Profile.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to create resources in"
  type        = string
  default     = "us-west-2"
}

variable "domain_name" {
  description = "The name of the SageMaker Domain"
  type        = string
  default     = "example-domain"
}

variable "user_profile_name" {
  description = "The name of the User Profile"
  type        = string
  default     = "example-user-profile"
}

variable "space_name" {
  description = "The name of the SageMaker Space"
  type        = string
  default     = "example-space"
}

resource "aws_iam_role" "sagemaker_domain_role" {
  name = "${var.domain_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "sagemaker_domain_policy" {
  name        = "${var.domain_name}-policy"
  description = "Policy for SageMaker Domain"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:CreateBucket",
          "s3:ListBucket",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:DescribeRepositories",
          "ecr:ListImages"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_domain_policy_attachment" {
  policy_arn = aws_iam_policy.sagemaker_domain_policy.arn
  role       = aws_iam_role.sagemaker_domain_role.name
}

resource "aws_sagemaker_domain" "example_domain" {
  domain_name = var.domain_name
  auth_mode   = "IAM"
  vpc_id      = "vpc-12345678" # Replace with your VPC ID
  subnet_ids  = ["subnet-12345678"] # Replace with your Subnet IDs

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_domain_role.arn
  }

  tags = {
    Name = "Example SageMaker Domain"
  }
}

resource "aws_sagemaker_user_profile" "example_user_profile" {
  domain_id         = aws_sagemaker_domain.example_domain.id
  user_profile_name = var.user_profile_name

  user_settings {
    execution_role = aws_iam_role.sagemaker_domain_role.arn
  }

  tags = {
    Name = "Example User Profile"
  }
}

resource "aws_sagemaker_space" "example_space" {
