    ]
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_app_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSageMakerFullAccess"
  role       = aws_iam_role.sagemaker_app_role.name
}

resource "aws_sagemaker_app" "jupyter_server_app" {
  domain_id         = var.domain_id
  user_profile_name = var.user_profile_name
  app_type          = "JupyterServer"

  tags = {
    Name = "MyJupyterServerApp"
  }

  resource_spec {
    instance_type = "ml.t3.medium"
  }
}
```

### Explanation:
1. **Provider Configuration**: The `aws` provider is configured with a region variable that defaults to `us-west-2`.
2. **Variables**:
   - `region`: Specifies the AWS region.
   - `domain_id`: The ID of the SageMaker Domain to which this app belongs.
   - `user_profile_name`: The name of the UserProfile to which this app belongs.
3. **IAM Role**:
   - `aws_iam_role.sagemaker_app_role`: Defines an IAM role that SageMaker can assume.
   - `aws_iam_role_policy_attachment.sagemaker_app_policy`: Attaches the `AmazonSageMakerFullAccess` policy to the role.
4. **SageMaker App**:
   - `aws_sagemaker_app.jupyter_server_app`: Creates a JupyterServer app within the specified SageMaker Domain and UserProfile.
   - `resource_spec`: Specifies the instance type for the JupyterServer.

This configuration assumes that you have already created a SageMaker Domain and a UserProfile within that domain. You will need to provide the `domain_id` and `user_profile_name` when applying this configuration.

