To reduce the number of database calls, we can implement a caching mechanism using Amazon ElastiCache. ElastiCache provides in-memory data stores that can be used to cache data from a database, reducing the number of database calls and improving application performance.

In this Terraform configuration, we will set up an ElastiCache Redis cluster. We'll also create an IAM role and policy that allows the EC2 instances (or any other service that needs to access the cache) to interact with the ElastiCache cluster securely.

Here's the Terraform HCL program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a VPC for the ElastiCache cluster
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "ElastiCacheVPC"
  }
}

# Define an Internet Gateway for the VPC
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "ElastiCacheIGW"
  }
}

# Define subnets for the ElastiCache cluster
resource "aws_subnet" "main" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.${count.index + 1}.0/24"][0]
  availability_zone = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "ElastiCacheSubnet-${count.index}"
  }
}

# Define a subnet group for the ElastiCache cluster
resource "aws_elasticache_subnet_group" "main" {
  name       = "elasti-cache-subnet-group"
  subnet_ids = aws_subnet.main[*].id

  tags = {
    Name = "ElastiCacheSubnetGroup"
  }
}

# Define a security group for the ElastiCache cluster
resource "aws_security_group" "main" {
  name_prefix = "elasti-cache-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ElastiCacheSecurityGroup"
  }
}

# Define an IAM role for EC2 instances to access ElastiCache
resource "aws_iam_role" "ec2_elasticache_access" {
  name = "ec2-elasticache-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Define an IAM policy for EC2 instances to access ElastiCache
resource "aws_iam_policy" "ec2_elasticache_access_policy" {
  name        = "ec2-elasticache-access-policy"
  description = "Policy to allow EC2 instances to access ElastiCache"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:Describe*",
          "elasticache:CreateCacheCluster",
          "elasticache:DeleteCacheCluster",
          "elasticache:ModifyCacheCluster"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "ec2_elasticache_access_policy_attachment" {
  policy_arn = aws_iam_policy.ec2_elasticache_access_policy.arn
  role       = aws_iam_role.ec2_elasticache_access.name
}

# Define the ElastiCache Redis cluster
resource "aws_elasticache_cluster" "main" {
  cluster_id           = "my-redis-cluster"
  engine               = "redis"
  node_type            = "cache.t3.micro"
  num_cache_nodes      = 1
  parameter_group_name = "default.redis6.x"
  subnet_group_name    = aws_elasticache_subnet_group.main.name
  security_group_ids   = [aws_security_group.main.id]

  tags = {
    Name = "MyRedisCluster"
  }
}

# Data source to get available AZs
data "aws_availability_zones" "available" {}
```

This configuration sets up a basic infrastructure for an ElastiCache Redis cluster within a new VPC. It includes subnets, a subnet group, a security group, and an IAM role with policies to allow EC2 instances to interact with the ElastiCache cluster. Adjust the `region` in the provider block and other parameters as necessary for your specific use case.

