LLM Output #0:
To create an Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes using Terraform, we need to define several resources including the MSK cluster itself, the necessary IAM roles, and the VPC and subnets where the MSK cluster will reside. Below is a complete Terraform configuration that accomplishes this.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **VPC and Subnets**: Creates a VPC and three public subnets across different availability zones.
- **Internet Gateway**: Attaches an internet gateway to the VPC.
- **Route Table**: Configures a route table to allow internet access from the subnets.
- **Security Group**: Creates a security group to control inbound and outbound traffic to the MSK cluster.
- **IAM Role and Policy**: Creates an IAM role and policy for MSK to manage its resources.
- **MSK Cluster**: Creates an MSK cluster with 3 broker nodes.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "broker_instance_type" {
  default = "kafka.m5.large"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "msk-igw"
  }
}

# Create Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "msk-subnet-${count.index + 1}"
  }
}

# Create Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "msk-route-table"
  }
}

# Associate Route Table with Subnets
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Create Security Group
resource "aws_security_group" "msk" {
  name_prefix = "msk-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust as necessary for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# Data Source for Availability Zones
data "aws_availability_zones" "available" {}

# Create IAM Role for MSK
resource "aws_iam_role" "msk" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "managedstreampkafka.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "msk-role"
  }
}

# Create IAM Policy for MSK
resource "aws_iam_policy" "msk" {
  name        = "msk-policy"
  description = "Policy for MSK to manage resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeRouteTables",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeVpcAttribute",
          "ec2:DescribeInstances",
          "ec2:DescribeElasticGpus",
          "ec2:DescribeVolumes"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })

  tags = {
    Name = "msk-policy"
  }
}

# Attach IAM Policy to MSK Role
resource "aws_iam_role_policy_attachment" "msk" {
  policy_arn = aws_iam_policy.msk.arn
  role       = aws_iam_role.msk.name
}

# Create MSK Cluster
resource "aws_msk_cluster" "main" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = var.broker_instance_type
    client_subnets  = aws_subnet.public[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
      firehose {
        enabled = false
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

# Create KMS Key for MSK Encryption
resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 7

  tags = {
    Name = "msk-kms-key"
  }
}

# Create CloudWatch Log Group for MSK Logs
resource "aws_cloudwatch_log_group" "msk" {
  name = "/aws/msk/my-msk-cluster"

  tags = {
    Name = "msk-log-group"
  }
}
```

This configuration sets up a complete environment for an MSK cluster with 3 broker nodes, including networking, security, and logging components. Make sure to adjust the `cidr_blocks` and `subnet_cidr_blocks` as necessary to fit your network requirements and ensure they do not overlap with existing resources.

