To create a managed Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region using Terraform, we need to define several resources:

1. **VPC**: A Virtual Private Cloud where the MSK cluster will reside.
2. **Subnets**: At least two subnets in different availability zones within the VPC.
3. **Security Group**: To control inbound and outbound traffic to the MSK cluster.
4. **IAM Role**: For MSK to access other AWS services if necessary.
5. **MSK Cluster**: The main resource that will be created.

Below is the complete Terraform configuration to achieve this:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "broker_instance_type" {
  default = "kafka.m5.large"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "msk-igw"
  }
}

# Create Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "msk-subnet-${count.index + 1}"
  }
}

# Data source to get available AZs
data "aws_availability_zones" "available" {}

# Create Security Group
resource "aws_security_group" "msk_sg" {
  name_prefix = "msk-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust as necessary for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# Create IAM Role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "msk_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_role.name
}

# Create MSK Cluster
resource "aws_msk_cluster" "main" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = var.broker_instance_type
    client_subnets  = aws_subnet.public[*].id
    security_groups = [aws_security_group.msk_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
      firehose {
        enabled = false
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

# Create KMS Key for MSK Encryption
resource "aws_kms_key" "msk_key" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 10

  tags = {
    Name = "msk-kms-key"
  }
}

# Create CloudWatch Log Group for MSK Logs
resource "aws_cloudwatch_log_group" "msk_logs" {
  name = "/aws/msk/my-msk-cluster"

  tags = {
    Name = "msk-log-group"
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-east-1`).
- **VPC and Subnets**: Creates a VPC and two public subnets in different availability zones.
- **Security Group**: Allows inbound traffic on port 9092 (default Kafka port) from any IP address.
- **IAM Role**: An IAM role with full MSK access is created and attached to the MSK cluster.
- **MSK Cluster**: Configures a MSK cluster with 3 broker nodes, specifying the instance type, subnets, and security group.
- **Encryption and Logging**: Sets up encryption using a KMS key and enables logging to CloudWatch.

This configuration is fully self-contained and can be deployed directly with Terraform. Adjust the security settings as necessary for your specific use case.

