LLM Output #0:
To create a managed Amazon Managed Streaming for Kafka (MSK) cluster in the `us-east-1` region and configure it to log to an S3 bucket, we need to perform the following steps:

1. **Create an S3 Bucket**: This will store the logs from the MSK cluster.
2. **Create an IAM Role and Policy**: The MSK cluster needs permissions to write logs to the S3 bucket.
3. **Create the MSK Cluster**: Configure the cluster to use the IAM role for logging.

Below is the Terraform HCL configuration that accomplishes this:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an S3 bucket for MSK logs
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-cluster-logs-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name        = "MSK Logs Bucket"
    Environment = var.environment
  }
}

# Create an IAM policy that allows MSK to write logs to the S3 bucket
resource "aws_iam_policy" "msk_logging_policy" {
  name        = "msk-logging-policy-${var.environment}"
  description = "Policy to allow MSK to write logs to S3"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = ["s3:PutObject"],
        Resource = "${aws_s3_bucket.msk_logs_bucket.arn}/*"
      },
      {
        Effect   = "Allow",
        Action   = ["s3:GetBucketLocation"],
        Resource = aws_s3_bucket.msk_logs_bucket.arn
      }
    ]
  })
}

# Create an IAM role for MSK
resource "aws_iam_role" "msk_logging_role" {
  name = "msk-logging-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "logs.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "msk_logging_policy_attachment" {
  policy_arn = aws_iam_policy.msk_logging_policy.arn
  role       = aws_iam_role.msk_logging_role.name
}

# Create the MSK cluster
resource "aws_msk_cluster" "example" {
  cluster_name           = "msk-cluster-${var.environment}"
  kafka_version          = "3.4.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [var.subnet_ids[0], var.subnet_ids[1], var.subnet_ids[2]]
    security_groups = [var.security_group_id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  logging_info {
    broker_logs {
      s3 {
        enabled   = true
        bucket    = aws_s3_bucket.msk_logs_bucket.id
        prefix    = "logs/msk/"
        log_format = "JSON"
      }
    }
  }

  tags = {
    Name        = "Example MSK Cluster"
    Environment = var.environment
  }
}

# Variables with default values
variable "environment" {
  description = "Environment identifier (e.g., dev, staging, prod)"
  default     = "dev"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = ["subnet-00000000000000000", "subnet-11111111111111111", "subnet-22222222222222222"]
}

variable "security_group_id" {
  description = "Security group ID for the MSK cluster"
  default     = "sg-00000000000000000"
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-east-1`).
- **S3 Bucket**: Created for storing MSK logs.
- **IAM Role and Policy**: The IAM role allows MSK to write logs to the S3 bucket.
- **MSK Cluster**: Configured with three broker nodes, using the specified subnets and security group. Logging is enabled and configured to send logs to the S3 bucket.

### Note:
- Replace the default values for `subnet_ids` and `security_group_id` with actual values from your AWS environment.
- Ensure that the `environment` variable matches your deployment context (e.g., `dev`, `staging`, `prod`).

