LLM Output #0:
To create a managed Amazon MSK (Managed Streaming for Kafka) cluster in the `us-east-1` region and configure it to log to a Kinesis Firehose, we need to set up several AWS resources:

1. **IAM Roles and Policies**: We need an IAM role for MSK to send logs to Kinesis Firehose.
2. **Kinesis Firehose Delivery Stream**: This will receive logs from MSK.
3. **MSK Cluster**: The main resource where Kafka brokers will run.

Below is the Terraform HCL configuration that accomplishes this:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables with default values
variable "msk_cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "firehose_delivery_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  default     = "my-firehose-stream"
}

# IAM Role for MSK to send logs to Kinesis Firehose
resource "aws_iam_role" "msk_firehose_role" {
  name = "${var.msk_cluster_name}-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK to send logs to Kinesis Firehose
resource "aws_iam_policy" "msk_firehose_policy" {
  name        = "${var.msk_cluster_name}-firehose-policy"
  description = "Policy for MSK to send logs to Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_firehose_delivery_stream.firehose_stream.arn
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "msk_firehose_role_policy_attachment" {
  policy_arn = aws_iam_policy.msk_firehose_policy.arn
  role       = aws_iam_role.msk_firehose_role.name
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = var.firehose_delivery_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.firehose_bucket.arn
    role_arn   = aws_iam_role.firehose_role.arn

    buffering_size = 5
    buffering_interval = 300

    compression_format = "GZIP"
  }
}

# S3 Bucket for Firehose Delivery Stream
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "${var.firehose_delivery_stream_name}-bucket"
}

# IAM Role for Firehose to write to S3
resource "aws_iam_role" "firehose_role" {
  name = "${var.firehose_delivery_stream_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Firehose to write to S3
resource "aws_iam_policy" "firehose_policy" {
  name        = "${var.firehose_delivery_stream_name}-policy"
  description = "Policy for Firehose to write to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.firehose_bucket.arn,
          "${aws_s3_bucket.firehose_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "firehose_role_policy_attachment" {
  policy_arn = aws_iam_policy.firehose_policy.arn
  role       = aws_iam_role.firehose_role.name
}

# MSK Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = "3.4.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m6.large"
    client_subnets = [
      aws_subnet.public_subnet_a.id,
      aws_subnet.public_subnet_b.id,
      aws_subnet.public_subnet_c.id
    ]
    security_groups = [aws_security_group.msk_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  logging_info {
    broker_logs {
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.firehose_stream.name
      }
    }
  }

  tags = {
    Name = var.msk_cluster_name
  }
}

# VPC and Subnets for MSK
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.msk_cluster_name}-vpc"
  }
}

resource "aws_subnet" "public_subnet_a" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  availability_zone = "us-east-1a"

  tags = {
    Name = "${var.msk_cluster_name}-subnet-a"
  }
}

resource "aws_subnet" "public_subnet_b" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  availability_zone = "us-east-1b"

  tags = {
    Name = "${var.msk_cluster_name}-subnet-b"
  }
}

resource "aws_subnet" "public_subnet_c" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.3.0/24"
  map_public_ip_on_launch = true

  availability_zone = "us-east-1c"

  tags = {
    Name = "${var.msk_cluster_name}-subnet-c"
  }
}

# Security Group for MSK
resource "aws_security_group" "msk_sg" {
  vpc_id = aws_vpc.vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.msk_cluster_name}-sg"
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-east-1`).
- **Variables**: Define names for the MSK cluster and Kinesis Firehose delivery stream with default values.
- **IAM Roles and Policies**: Create IAM roles and policies necessary for MSK to send logs to Kinesis Firehose and for Firehose to write to S3.
- **Kinesis Firehose Delivery Stream**: Configures a Kinesis Firehose delivery stream that sends data to an S3 bucket.
- **S3 Bucket**: Creates an S3 bucket to store the logs from the Firehose delivery stream.
- **MSK Cluster**: Sets up an MSK cluster with three broker nodes, specifying the necessary configurations including logging to the Kinesis Firehose delivery stream.
- **VPC and Subnets**: Creates a VPC and three public subnets across different availability zones for the MSK cluster.
- **Security Group**: Configures a security group to allow traffic on port 9092 for Kafka communication.

This configuration is fully self-contained and can be deployed using Terraform. Make sure to adjust any settings according to your specific requirements.

