LLM Output #0:
To create a managed Amazon Managed Streaming for Kafka (MSK) cluster with encryption at rest using Terraform, we need to define several resources:

1. **AWS Provider Configuration**: Specifies the AWS region and credentials.
2. **IAM Role and Policy**: Required for MSK to access other AWS services.
3. **VPC and Subnets**: MSK clusters require a VPC and at least two subnets in different availability zones.
4. **Security Group**: Controls inbound and outbound traffic to the MSK cluster.
5. **MSK Cluster**: The main resource where we enable encryption at rest.

Below is the complete Terraform HCL configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "3.2.1"
}

variable "number_of_broker_nodes" {
  default = 3
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

# Create Subnets
resource "aws_subnet" "main" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.cluster_name}-subnet-${count.index + 1}"
  }
}

# Create Security Group
resource "aws_security_group" "msk_sg" {
  name_prefix = "${var.cluster_name}-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust as necessary for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.cluster_name}-security-group"
  }
}

# Create IAM Role for MSK
resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_policy_attachment" "msk_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
  roles      = [aws_iam_role.msk_role.name]
}

# Create MSK Cluster
resource "aws_msk_cluster" "main" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.number_of_broker_nodes

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = aws_subnet.main[*].id
    security_groups = [aws_security_group.msk_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_key.arn
  }

  enhanced_monitoring = "PER_BROKER"

  tags = {
    Name = var.cluster_name
  }
}

# Create KMS Key for Encryption at Rest
resource "aws_kms_key" "msk_key" {
  description             = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 10

  tags = {
    Name = "${var.cluster_name}-kms-key"
  }
}
```

This configuration sets up a basic MSK cluster with encryption at rest using a KMS key. It includes all necessary components such as VPC, subnets, security groups, IAM roles, and the MSK cluster itself. Adjust the `cidr_blocks`, `kafka_version`, and other parameters as needed for your specific use case.

