To create a serverless MSK (Managed Streaming for Kafka) cluster in the `us-east-1` region using Terraform, we need to configure the AWS provider, define the necessary IAM roles, and set up the MSK cluster. Since MSK serverless is not directly available as a resource type in Terraform, we'll focus on creating a provisioned MSK cluster. However, if you specifically need a serverless MSK, please note that as of my last update, AWS does not offer a serverless version of MSK; it only supports provisioned clusters.

Below is a Terraform configuration that sets up a provisioned MSK cluster in the `us-east-1` region:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Define the VPC for MSK
resource "aws_vpc" "msk_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

# Define subnets for MSK
resource "aws_subnet" "msk_subnets" {
  count                   = 3
  vpc_id                  = aws_vpc.msk_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.msk_vpc.cidr_block, 8, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "msk-subnet-${count.index}"
  }
}

# Define internet gateway for VPC
resource "aws_internet_gateway" "msk_igw" {
  vpc_id = aws_vpc.msk_vpc.id

  tags = {
    Name = "msk-igw"
  }
}

# Define route table for VPC
resource "aws_route_table" "msk_rt" {
  vpc_id = aws_vpc.msk_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.msk_igw.id
  }

  tags = {
    Name = "msk-route-table"
  }
}

# Associate subnets with route table
resource "aws_route_table_association" "msk_rta" {
  count          = length(aws_subnet.msk_subnets)
  subnet_id      = element(aws_subnet.msk_subnets.*.id, count.index)
  route_table_id = aws_route_table.msk_rt.id
}

# Define security group for MSK
resource "aws_security_group" "msk_sg" {
  name_prefix = "msk-sg"
  vpc_id      = aws_vpc.msk_vpc.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# Define IAM role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      },
    ]
  })
}

# Define IAM policy for MSK
resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach IAM policy to MSK role
resource "aws_iam_role_policy_attachment" "msk_policy_attachment" {
  policy_arn = aws_iam_policy.msk_policy.arn
  role       = aws_iam_role.msk_role.name
}

# Define MSK cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = aws_subnet.msk_subnets[*].id
    security_groups = [aws_security_group.msk_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  enhanced_monitoring = "PER_BROKER"

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

# Define KMS key for MSK encryption
resource "aws_kms_key" "msk_kms_key" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 10

  tags = {
    Name = "msk-kms-key"
  }
}

# Define CloudWatch log group for MSK logs
resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/my-msk-cluster"

  tags = {
    Name = "msk-log-group"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}
```

This configuration sets up a VPC, subnets, internet gateway, route table, security group, IAM role, and policy, and then creates an MSK cluster in the `us-east-1` region. The MSK cluster is configured with three broker nodes, enhanced monitoring, and logging to CloudWatch. Please ensure you have the necessary permissions to create these resources in your AWS account.

