To create a serverless Managed Streaming for Kafka (MSK) cluster with 3 broker nodes using Terraform, we need to configure the AWS MSK service. However, it's important to note that AWS MSK does not support serverless deployment directly; instead, it supports provisioned clusters. Therefore, I'll create a provisioned MSK cluster with 3 broker nodes.

The Terraform configuration will include:
- An AWS provider configuration.
- A VPC with subnets and an internet gateway.
- Security groups for the MSK cluster.
- An IAM role and policy for MSK.
- The MSK cluster itself.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "cluster_name" {
  default = "my-msk-cluster"
}

variable "kafka_version" {
  default = "2.8.1"
}

variable "broker_instance_type" {
  default = "kafka.m5.large"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

# Create public subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "msk-subnet-${count.index + 1}"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "msk-igw"
  }
}

# Create a route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "msk-route-table"
  }
}

# Associate subnets with the route table
resource "aws_route_table_association" "public" {
  count          = length(var.subnet_cidr_blocks)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Create a security group for MSK
resource "aws_security_group" "msk" {
  name_prefix = "msk-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes, allow all IPs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "msk-security-group"
  }
}

# Create an IAM role for MSK
resource "aws_iam_role" "msk" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "managedstreampinkafka.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_policy_attachment" "msk" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonMSKFullAccess"
  roles      = [aws_iam_role.msk.name]
}

# Create the MSK cluster
resource "aws_msk_cluster" "main" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = var.broker_instance_type
    client_subnets  = aws_subnet.public[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk.name
      }
      firehose {
        enabled = false
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = "my-msk-cluster"
  }
}

# Create a KMS key for MSK encryption
resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 7

  tags = {
    Name = "msk-kms-key"
  }
}

# Create a CloudWatch log group for MSK logs
resource "aws_cloudwatch_log_group" "msk" {
  name = "/aws/msk/my-msk-cluster"

  tags = {
    Name = "msk-log-group"
  }
}
```

This configuration sets up a VPC, subnets, an internet gateway, security groups, IAM roles, and policies, and finally creates a provisioned MSK cluster with 3 broker nodes. Adjust the `region` and other parameters as needed for your specific use case.

