LLM Output #0:
To address your request, I'll create a Terraform configuration that sets up an Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes. This MSK cluster will have encryption at rest enabled and open monitoring configured. Additionally, the MSK logs will be sent to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream.

Here's the detailed Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "msk_cluster_name" {
  default = "my-msk-cluster"
}

variable "s3_bucket_name" {
  default = "my-msk-logs-bucket"
}

variable "firehose_delivery_stream_name" {
  default = "my-msk-firehose-stream"
}

variable "cloudwatch_log_group_name" {
  default = "/aws/msk/my-msk-cluster"
}

# IAM Role for MSK to access CloudWatch Logs, S3, and Kinesis Firehose
resource "aws_iam_role" "msk_logging_role" {
  name = "${var.msk_cluster_name}-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "logs.kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_logging_policy" {
  name        = "${var.msk_cluster_name}-logging-policy"
  description = "Policy for MSK logging to CloudWatch Logs, S3, and Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:log-group:${var.cloudwatch_log_group_name}:*"
      },
      {
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::${var.s3_bucket_name}",
          "arn:aws:s3:::${var.s3_bucket_name}/*"
        ]
      },
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:firehose:*:*:deliverystream/${var.firehose_delivery_stream_name}"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_logging_policy_attachment" {
  policy_arn = aws_iam_policy.msk_logging_policy.arn
  role       = aws_iam_role.msk_logging_role.name
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = var.cloudwatch_log_group_name
}

# S3 Bucket for MSK Logs
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = var.s3_bucket_name

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name = "MSK Logs Bucket"
  }
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_stream" {
  name        = var.firehose_delivery_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn                 = aws_iam_role.msk_logging_role.arn
    bucket_arn               = aws_s3_bucket.msk_logs_bucket.arn
    buffering_size           = 5
    buffering_interval       = 300
    error_output_prefix      = "error/"
    prefix                   = "msk-logs/"
    compression_format       = "GZIP"
    data_format_conversion_configuration {
      input_format_configuration {
        deserializer {
          open_x_json_deserializer {}
        }
      }
      output_format_configuration {
        serializer {
          parquet_serializer {}
        }
      }
      schema_configuration {
        role_arn            = aws_iam_role.msk_logging_role.arn
        catalog_id          = data.aws_caller_identity.current.account_id
        database_name       = "default"
        table_name          = "msk_logs"
        region              = "us-west-2"
        versioning_enabled  = false
        register_with_glue  = false
      }
    }
  }
}

# MSK Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = var.msk_cluster_name
  kafka_version  = "3.4.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-abcdef01"] # Replace with your subnet IDs
    security_groups = ["sg-12345678"] # Replace with your security group ID

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled             = true
        delivery_stream     = aws_kinesis_firehose_delivery_stream.msk_firehose_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs_bucket.bucket
      }
    }
  }
}

# KMS Key for MSK Encryption at Rest
resource "aws_kms_key" "msk_kms_key" {
  description             = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 10
}

# Data Source for AWS Caller Identity
data "aws_caller_identity" "current" {}

output "msk_cluster_arn" {
  value = aws_msk_cluster.msk_cluster.arn
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.msk_logs_bucket.arn
}

output "firehose_delivery_stream_arn" {
  value = aws_kinesis_firehose_delivery_stream.msk_firehose_stream.arn
}

output "cloudwatch_log_group_arn" {
  value = aws_cloudwatch_log_group.msk_log_group.arn
}
```

### Explanation:
1. **Provider Configuration**: Configured to use AWS provider with a specific region (`us-west-2`).
2. **Variables**: Defined variables for the MSK cluster name, S3 bucket name, Firehose delivery stream name, and CloudWatch log group name with default values.
3. **IAM Role and Policy**: Created an IAM role and policy that allows MSK to write logs to CloudWatch Logs, S3, and Kinesis Firehose.
4. **CloudWatch Log Group**: Created a CloudWatch log group for MSK logs.
5. **S3 Bucket**: Created an S3 bucket for MSK logs with versioning and server-side encryption enabled.
6. **Kinesis Firehose Delivery Stream**: Created a Kinesis Firehose delivery stream to send MSK logs to the S3 bucket.
7. **MSK Cluster**: Created an MSK cluster with 3 broker nodes, encryption at rest using a KMS key, and open monitoring enabled.
8. **KMS Key**: Created a KMS key for encrypting MSK data at rest.
9. **Outputs**: Provided outputs for the ARNs of the MSK cluster, S3 bucket, Firehose delivery stream, and CloudWatch log group.

Make sure to replace the `client_subnets` and `security_groups` with your actual subnet IDs and security group IDs.

