LLM Output #0:
To address your request, I'll create a Terraform configuration that sets up the following:

1. An Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region.
2. An MSK Connect custom plugin using a `debezium.zip` file.
3. An MSK Connect connector that uses the custom plugin and connects to the MSK cluster.

The configuration will include necessary IAM roles and policies for MSK and MSK Connect. The `debezium.zip` file should be uploaded to an S3 bucket, and the bucket name will be provided as a variable with a default value.

Here's the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables
variable "s3_bucket_name" {
  description = "The name of the S3 bucket where debezium.zip is stored"
  default     = "your-s3-bucket-name"
}

variable "debezium_zip_key" {
  description = "The key of the debezium.zip file in the S3 bucket"
  default     = "debezium.zip"
}

variable "msk_cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_connect_connector_name" {
  description = "The name of the MSK Connect connector"
  default     = "my-msk-connect-connector"
}

# IAM Role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK access"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "ec2:Describe*",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ssm:GetParameter"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy_attachment" {
  policy_arn = aws_iam_policy.msk_policy.arn
  role       = aws_iam_role.msk_role.name
}

# MSK Cluster
resource "aws_msk_cluster" "this" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = "3.4.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m6.large"
    client_subnets = [
      aws_subnet.subnet_a.id,
      aws_subnet.subnet_b.id,
      aws_subnet.subnet_c.id
    ]
    security_groups = [aws_security_group.sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.kms_key.arn
  }

  enhanced_monitoring = "PER_BROKER"

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.log_group.name
      }
    }
  }

  tags = {
    Name = var.msk_cluster_name
  }
}

# VPC, Subnets, Security Group, KMS Key, and Log Group
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "msk-subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = true

  tags = {
    Name = "msk-subnet-b"
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = "us-east-1c"
  map_public_ip_on_launch = true

  tags = {
    Name = "msk-subnet-c"
  }
}

resource "aws_security_group" "sg" {
  vpc_id = aws_vpc.vpc.id

  ingress {
    from_port   = 0
