To address your request, I'll create a comprehensive Terraform configuration that sets up an Amazon Managed Streaming for Kafka (MSK) cluster with 3 broker nodes, configured for encryption at rest and open monitoring. The MSK logs will be sent to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. Additionally, I'll create an MSK Connect custom plugin using a `debezium.zip` file and an MSK Connect connector that utilizes this custom plugin to connect to the MSK cluster.

### Description of the Terraform Program

1. **Provider Configuration**: Configures the AWS provider with a specific region.
2. **IAM Roles and Policies**:
   - An IAM role for MSK with policies for logging to CloudWatch, S3, and Kinesis Firehose.
   - An IAM role for MSK Connect with policies for accessing the MSK cluster and using the custom plugin.
3. **CloudWatch Log Group**: Created for MSK logs.
4. **S3 Bucket**: Created for MSK logs.
5. **Kinesis Firehose Delivery Stream**: Created for MSK logs.
6. **MSK Cluster**: Configured with 3 broker nodes, encryption at rest, and open monitoring.
7. **MSK Connect Custom Plugin**: Uploaded from a local `debezium.zip` file.
8. **MSK Connect Connector**: Configured to use the custom plugin and connect to the MSK cluster.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for MSK
resource "aws_iam_role" "msk_role" {
  name = "msk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK
resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK to write logs to CloudWatch, S3, and Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Effect   = "Allow"
        Resource = ["arn:aws:s3:::msk-logs-bucket", "arn:aws:s3:::msk-logs-bucket/*"]
      },
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:firehose:*:*:deliverystream/msk-firehose-stream"
      }
    ]
  })
}

# Attach the policy to the MSK role
resource "aws_iam_role_policy_attachment" "msk_policy_attachment" {
  policy_arn = aws_iam_policy.msk_policy.arn
  role       = aws_iam_role.msk_role.name
}

# CloudWatch Log Group for MSK
resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/cluster/msk-cluster"
}

# S3 Bucket for MSK Logs
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket"
}

# Kinesis Firehose Delivery Stream for MSK Logs
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_stream" {
  name        = "msk-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn                 = aws_iam_role.msk_role.arn
    bucket_arn               = aws_s3_bucket.msk_logs_bucket.arn
    buffering_size           = 5
    buffering_interval       = 300
    error_logging_enabled    = true
    prefix                   = "msk-logs/"
    compression_format       = "GZIP"
    data_format_conversion_configuration {
      input_format_configuration {
        deserializer {
          open_x_json_ser_de {}
        }
      }
      output_format_configuration {
        serializer {
          parquet_ser_de {}
        }
      }
      schema_configuration {
        role_arn            = aws_iam_role.msk_role.arn
        catalog_id          = data.aws_caller_identity.current.account_id
        database_name       = "default"
        table_name          = "msk_logs"
        versioning_enabled  = false
        register_with_glue  = false
      }
    }
  }
}

# MSK Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "3.2.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type                = "kafka.m5.large"
    client_subnets               = ["subnet-12345678", "subnet-87654321", "subnet-abcdef12"] # Replace with your subnet IDs
    security_groups              = ["sg-12345678"] # Replace with your security group ID
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_kms_key.arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs_bucket.bucket
      }
    }
  }
}

# KMS Key for MSK Encryption
resource "aws_kms_key" "msk_kms_key" {
  description             = "KMS key for MSK encryption"
  deletion_window_in_days = 10
}

# IAM Role for MSK Connect
