4. Replicas of the DynamoDB table in the other region (`us-west-2`).

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-1"
}

# IAM Role for DynamoDB Streams
resource "aws_iam_role" "dynamodb_replication_role" {
  name = "dynamodb-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for DynamoDB Streams
resource "aws_iam_policy" "dynamodb_replication_policy" {
  name        = "dynamodb-replication-policy"
  description = "Policy for DynamoDB replication"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = [
          "dynamodb:DescribeStream",
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:ListStreams"
        ],
        Effect   = "Allow",
        Resource = "*"
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "dynamodb_replication_policy_attachment" {
  policy_arn = aws_iam_policy.dynamodb_replication_policy.arn
  role       = aws_iam_role.dynamodb_replication_role.name
}

# Main DynamoDB Table
resource "aws_dynamodb_table" "main_table" {
  name           = "my-dynamodb-table"
  billing_mode   = "PAY_PER_REQUEST"
  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "id"
    type = "S"
  }

  key_schema {
    name = "id"
    type = "HASH"
  }

  replica {
    region_name = "us-west-2"
    kms_key_arn = aws_kms_key.replica_kms_key.arn
  }
}

# KMS Key for the replica in us-west-2
resource "aws_kms_key" "replica_kms_key" {
  description             = "KMS key for DynamoDB replica in us-west-2"
  deletion_window_in_days = 7
}
```

### Explanation:
- **Provider Configuration**: The provider is set to `us-west-1` where the main DynamoDB table will reside.
- **IAM Role and Policy**: An IAM role and policy are created to allow DynamoDB to replicate data across regions.
- **DynamoDB Table**: The main table is created in `us-west-1` with a stream enabled for replication.
- **Replica**: A replica of the table is configured in `us-west-2`.
- **KMS Key**: A KMS key is created for the replica in `us-west-2` to encrypt the data.

This configuration ensures that the DynamoDB table is replicated across the two specified regions with proper permissions and encryption.

