    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_encryption_key.arn
  }
}

# Create an IAM role with permissions to manage the DynamoDB table and KMS key
resource "aws_iam_role" "dynamodb_kms_manager" {
  name = "DynamoDBKMSManagerRole"

