### Description

The Terraform program will create an AWS Virtual Private Cloud (VPC) with a single public subnet. It will also create and associate a Network Access Control List (NACL) to control both ingress and egress traffic for the subnet. The NACL will allow SSH (port 22) and HTTP (port 80) traffic from any IP address for ingress, and allow all outbound traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

# Create a public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet"
  }
}

# Create a Network ACL
resource "aws_network_acl" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainNACL"
  }
}

# Ingress rule for SSH (port 22)
resource "aws_network_acl_rule" "ssh_ingress" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 100
  protocol       = "tcp"
  from_port      = 22
  to_port        = 22
  cidr_block     = "0.0.0.0/0"
  action         = "allow"
  egress         = false
}

# Ingress rule for HTTP (port 80)
resource "aws_network_acl_rule" "http_ingress" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 200
  protocol       = "tcp"
  from_port      = 80
  to_port        = 80
  cidr_block     = "0.0.0.0/0"
  action         = "allow"
  egress         = false
}

# Egress rule to allow all outbound traffic
resource "aws_network_acl_rule" "all_egress" {
  network_acl_id = aws_network_acl.main.id
  rule_number    = 300
  protocol       = "-1"
  from_port      = 0
  to_port        = 0
  cidr_block     = "0.0.0.0/0"
  action         = "allow"
  egress         = true
}

# Associate the Network ACL with the subnet
resource "aws_network_acl_association" "public_subnet" {
  network_acl_id = aws_network_acl.main.id
  subnet_id      = aws_subnet.public.id
}
```

This configuration sets up a basic VPC infrastructure with a subnet and a NACL to control traffic. You can customize the `vpc_cidr_block` and `subnet_cidr_block` variables if needed. The region is set to `us-west-2`, but you can change it to any other region supported by AWS.

