To set up a basic AWS Neptune cluster with a custom parameter group using Terraform, we will create the following resources:

1. **AWS Provider Configuration**: Specifies the region and version constraints.
2. **IAM Role for Neptune**: An IAM role with necessary policies for Neptune operations.
3. **Neptune Parameter Group**: A custom parameter group for Neptune.
4. **Neptune Subnet Group**: A subnet group to specify which subnets Neptune can use.
5. **Neptune Cluster**: The main Neptune cluster using the custom parameter group and subnet group.
6. **Neptune Instance**: At least one instance within the Neptune cluster.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Neptune
resource "aws_iam_role" "neptune_role" {
  name = "neptune-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "neptune_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonNeptuneServiceRolePolicy"
  role       = aws_iam_role.neptune_role.name
}

# Neptune Parameter Group
resource "aws_neptune_parameter_group" "custom_neptune_params" {
  name   = "custom-neptune-params"
  family = "neptune1"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  parameter {
    name  = "neptune_query_timeout"
    value = "120"
  }
}

# Neptune Subnet Group
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = ["subnet-12345678", "subnet-87654321"] # Replace with your subnet IDs

  tags = {
    Name = "NeptuneSubnetGroup"
  }
}

# Neptune Cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster"
  engine                              = "neptune"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
  iam_database_authentication_enabled = true
  iam_roles                           = [aws_iam_role.neptune_role.arn]
  parameter_group_name                = aws_neptune_parameter_group.custom_neptune_params.name
  subnet_group_name                   = aws_neptune_subnet_group.neptune_subnet_group.name

  tags = {
    Name = "NeptuneCluster"
  }
}

# Neptune Instance
resource "aws_neptune_instance" "neptune_instance" {
  count              = 1
  identifier         = "neptune-instance-${count.index}"
  instance_class     = "db.r5.large"
  cluster_identifier = aws_neptune_cluster.neptune_cluster.id

  tags = {
    Name = "NeptuneInstance"
  }
}
```

### Notes:
- Replace `"subnet-12345678"` and `"subnet-87654321"` with your actual subnet IDs.
- Ensure that the subnets are in different availability zones for high availability.
- The `neptune_enable_audit_log` and `neptune_query_timeout` parameters are examples; you can modify them according to your requirements.
- The IAM role and attached policy are necessary for Neptune to perform certain operations, such as backups and maintenance.

