To set up a basic AWS Neptune cluster with a custom parameter group that only allows connections from two example subnets, we need to perform the following steps:

1. **Provider Configuration**: Define the AWS provider with a specific region.
2. **VPC and Subnets**: Create a VPC and two subnets for the Neptune cluster.
3. **Security Group**: Create a security group that allows inbound traffic from the specified subnets.
4. **Neptune Parameter Group**: Create a custom Neptune parameter group.
5. **Neptune Cluster**: Create a Neptune cluster using the custom parameter group and place it in the specified subnets.

Below is the complete Terraform HCL configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "neptune_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "neptune-vpc"
  }
}

# Create two subnets in the VPC
resource "aws_subnet" "neptune_subnets" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.neptune_vpc.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = false

  tags = {
    Name = "neptune-subnet-${count.index + 1}"
  }
}

# Data source to get available AZs
data "aws_availability_zones" "available" {}

# Create a security group for Neptune
resource "aws_security_group" "neptune_sg" {
  name_prefix = "neptune-sg-"
  vpc_id      = aws_vpc.neptune_vpc.id

  ingress {
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.neptune_subnets[0].cidr_block, aws_subnet.neptune_subnets[1].cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "neptune-security-group"
  }
}

# Create a Neptune parameter group
resource "aws_neptune_parameter_group" "neptune_param_group" {
  name   = "custom-neptune-param-group"
  family = "neptune1"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  tags = {
    Name = "custom-neptune-param-group"
  }
}

# Create a Neptune cluster
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster"
  engine                              = "neptune"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
  iam_database_authentication_enabled = false
  storage_encrypted                 = true
  apply_immediately                 = true
  skip_final_snapshot                 = true

  parameter_group_name = aws_neptune_parameter_group.neptune_param_group.name

  vpc_security_group_ids = [aws_security_group.neptune_sg.id]

  subnet_ids = aws_subnet.neptune_subnets[*].id

  tags = {
    Name = "neptune-cluster"
  }
}

# Create a Neptune instance
resource "aws_neptune_instance" "neptune_instance" {
  count               = 1
  identifier          = "neptune-instance-${count.index + 1}"
  instance_class      = "db.r5.large"
  engine              = aws_neptune_cluster.neptune_cluster.engine
  engine_version      = aws_neptune_cluster.neptune_cluster.engine_version
  cluster_identifier  = aws_neptune_cluster.neptune_cluster.cluster_identifier
  parameter_group_name = aws_neptune_parameter_group.neptune_param_group.name
  promotion_tier      = 0

  tags = {
    Name = "neptune-instance-${count.index + 1}"
  }
}
```

This configuration sets up a Neptune cluster in a VPC with two subnets, a custom parameter group, and a security group that restricts access to the Neptune cluster from the specified subnets. The Neptune cluster consists of one instance, but you can adjust the `count` in the `aws_neptune_instance` resource to add more instances if needed.

