Here's the Terraform HCL program:

```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to your preferred region
}

# Define the IAM policy for Chime operations
resource "aws_iam_policy" "chime_policy" {
  name        = "ChimeVoiceConnectorPolicy"
  description = "IAM policy for Chime Voice Connector operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "chime:CreateVoiceConnector",
          "chime:DeleteVoiceConnector",
          "chime:GetVoiceConnector",
          "chime:PutVoiceConnectorLoggingConfiguration"
        ]
        Resource = "*"
      }
    ]
  })
}

# Define the IAM role for Chime operations
