  name = "ChimeVoiceConnectorRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "voiceconnector.chime.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

