To achieve the task of creating an AWS Chime Voice Connector and setting up a configuration to stream media to Amazon Kinesis, we need to perform the following steps:

1. **Create an AWS Chime Voice Connector**: This involves using the `aws_chime_voice_connector` resource.
2. **Create an Amazon Kinesis Stream**: This involves using the `aws_kinesis_stream` resource.
3. **Set up permissions for Chime to send media to Kinesis**: This involves creating an IAM role with the necessary policies and attaching it to the Chime Voice Connector.

Below is the Terraform HCL configuration that accomplishes these tasks:

```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to your preferred region
}

# Variables with default values
variable "voice_connector_name" {
  description = "The name of the Chime Voice Connector"
  default     = "MyChimeVoiceConnector"
}

variable "kinesis_stream_name" {
  description = "The name of the Kinesis Stream"
  default     = "MyKinesisStream"
}

variable "kinesis_shard_count" {
  description = "The number of shards for the Kinesis Stream"
  default     = 1
}

# Create an AWS Chime Voice Connector
resource "aws_chime_voice_connector" "voice_connector" {
  name            = var.voice_connector_name
  require_encryption = true
}

# Create an Amazon Kinesis Stream
resource "aws_kinesis_stream" "kinesis_stream" {
  name        = var.kinesis_stream_name
  shard_count = var.kinesis_shard_count
}

# Create an IAM role for Chime to send media to Kinesis
resource "aws_iam_role" "chime_kinesis_role" {
  name = "ChimeKinesisRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "media-chime.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role to allow writing to the Kinesis stream
resource "aws_iam_role_policy" "chime_kinesis_policy" {
  name = "ChimeKinesisPolicy"
  role = aws_iam_role.chime_kinesis_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_stream.kinesis_stream.arn
      },
    ]
  })
}

# Associate the IAM role with the Chime Voice Connector
resource "aws_chime_voice_connector_logging" "logging" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id

  media_insights_configuration {
    configuration_arn = aws_iam_role.chime_kinesis_role.arn
    enabled           = true
  }
}
```

