To create an AWS Redshift cluster with endpoint access from two subnets, we need to set up the following resources:

1. **VPC**: A Virtual Private Cloud to contain our subnets.
2. **Subnets**: Two subnets within the VPC for the Redshift cluster.
3. **Internet Gateway**: To allow communication between the VPC and the internet.
4. **Route Table**: To route traffic from the subnets to the internet gateway.
5. **Security Group**: To control inbound and outbound traffic to the Redshift cluster.
6. **IAM Role**: For Redshift to access other AWS services if necessary.
7. **Redshift Cluster**: The main resource that we want to create.

Below is the Terraform HCL configuration that accomplishes this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "redshift_cluster_identifier" {
  default = "my-redshift-cluster"
}

variable "redshift_node_type" {
  default = "dc2.large"
}

variable "redshift_master_username" {
  default = "adminuser"
}

variable "redshift_master_password" {
  default = "yourStrong(!)Password123"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "redshift-vpc"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "redshift-igw"
  }
}

# Create Route Table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "redshift-route-table"
  }
}

# Create Subnets
resource "aws_subnet" "main" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "redshift-subnet-${count.index + 1}"
  }
}

# Associate Route Table with Subnets
resource "aws_route_table_association" "main" {
  count          = length(var.subnet_cidr_blocks)
  subnet_id      = element(aws_subnet.main.*.id, count.index)
  route_table_id = aws_route_table.main.id
}

# Create Security Group
resource "aws_security_group" "redshift" {
  name        = "redshift-sg"
  description = "Allow Redshift access"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust this to your needs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-security-group"
  }
}

# Create IAM Role for Redshift
resource "aws_iam_role" "redshift" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "redshift-role"
  }
}

# Attach Policy to IAM Role
resource "aws_iam_role_policy_attachment" "redshift" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.redshift.name
}

# Create Redshift Cluster
resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = var.redshift_cluster_identifier
  node_type                           = var.redshift_node_type
  master_username                     = var.redshift_master_username
  master_password                     = var.redshift_master_password
  iam_roles                           = [aws_iam_role.redshift.arn]
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  publicly_accessible                 = true
  skip_final_snapshot                 = true

  tags = {
    Name = "my-redshift-cluster"
  }
}

# Create Redshift Subnet Group
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-subnet-group"
  subnet_ids = aws_subnet.main[*].id

  tags = {
    Name = "redshift-subnet-group"
  }
}
```

This configuration sets up a VPC with two subnets, an internet gateway, a route table, and a security group. It also creates an IAM role with S3 read-only access, which can be useful if your Redshift cluster needs to access data stored in S3. Finally, it creates a Redshift cluster that is accessible from the two subnets. 

Make sure to adjust the `cidr_blocks` and `master_password` to fit your requirements. Also, consider tightening the security group rules to only allow necessary traffic.

