To create an AWS Redshift cluster with notifications on events, we will define a Terraform configuration that includes:

1. An AWS Redshift cluster.
2. An SNS topic for receiving notifications.
3. An IAM role with permissions to publish to the SNS topic.
4. A subscription to the SNS topic for the Redshift cluster.

The Redshift cluster will be configured to send event notifications to the SNS topic. We'll also ensure that the necessary permissions are set up so that the Redshift service can publish to the SNS topic using the IAM role.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "redshift_cluster_identifier" {
  description = "The identifier of the Redshift cluster."
  default     = "my-redshift-cluster"
}

variable "redshift_node_type" {
  description = "The node type to be provisioned for the cluster."
  default     = "dc2.large"
}

variable "redshift_master_username" {
  description = "Username for the master user."
  default     = "masteruser"
}

variable "redshift_master_password" {
  description = "Password for the master user."
  default     = "yourStrong!Passw0rd"
}

variable "redshift_db_name" {
  description = "Name of the database to be created when the cluster is created."
  default     = "dev"
}

variable "redshift_cluster_type" {
  description = "The type of the cluster. It can be either 'single-node' or 'multi-node'."
  default     = "single-node"
}

variable "redshift_number_of_nodes" {
  description = "The number of nodes in the cluster. This parameter is required if cluster_type is 'multi-node'."
  default     = 1
}

# SNS Topic for Redshift Notifications
resource "aws_sns_topic" "redshift_notifications" {
  name = "redshift-notifications-topic"
}

# IAM Role for Redshift to Publish to SNS
resource "aws_iam_role" "redshift_sns_publisher" {
  name = "redshift-sns-publisher"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for Redshift to Publish to SNS
resource "aws_iam_policy" "redshift_sns_publish_policy" {
  name        = "redshift-sns-publish-policy"
  description = "Policy to allow Redshift to publish to SNS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sns:Publish"
        ]
        Effect   = "Allow"
        Resource = aws_sns_topic.redshift_notifications.arn
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "redshift_sns_publish_policy_attach" {
  policy_arn = aws_iam_policy.redshift_sns_publish_policy.arn
  role       = aws_iam_role.redshift_sns_publisher.name
}

# Redshift Cluster
resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier                  = var.redshift_cluster_identifier
  node_type                           = var.redshift_node_type
  master_username                     = var.redshift_master_username
  master_password                     = var.redshift_master_password
  db_name                             = var.redshift_db_name
  iam_roles                           = [aws_iam_role.redshift_sns_publisher.arn]
  cluster_type                        = var.redshift_cluster_type
  number_of_nodes                     = var.redshift_number_of_nodes
  automated_snapshot_retention_period = 1

  # Enable logging and specify the bucket name
  logging_enabled                     = true
  bucket_name                         = "my-redshift-logs-bucket"

  # Configure event subscriptions
  snapshot_copy_grant_name            = "my-snapshot-copy-grant"
  snapshot_copy_manual                = false
  snapshot_copy_retention_period      = 7

  tags = {
    Name = "MyRedshiftCluster"
  }

  # Event Subscription
  depends_on = [aws_sns_topic.redshift_notifications]

  cluster_subnet_group_name           = "default"
}

# SNS Subscription for Redshift Events
resource "aws_sns_topic_subscription" "redshift_events" {
  topic_arn = aws_sns_topic.redshift_notifications.arn
  protocol  = "email"
  endpoint  = "your-email@example.com"
}
```

### Notes:
- Replace `yourStrong!Passw0rd` with a strong password for the Redshift master user.
- Replace `your-email@example.com` with your email address to receive notifications.
- Ensure that the S3 bucket `my-redshift-logs-bucket` exists or modify the `bucket_name` variable to use an existing bucket.
- The `snapshot_copy_grant_name` should correspond to an existing snapshot copy grant or you can create one as per your requirements.
- The `cluster_subnet_group_name` should correspond to an existing subnet group or you can create one as per your requirements.

This configuration sets up a Redshift cluster with event notifications sent to an SNS topic, which then sends emails to the specified endpoint.

