```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Redshift (if needed)
resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      },
    ]
  })
}

# Redshift Cluster Parameter Group
resource "aws_redshift_cluster_parameter_group" "example" {
  name   = "example-cluster-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  parameter {
    name  = "require_ssl"
    value = "true"
  }
}

# Redshift Cluster
resource "aws_redshift_cluster" "example" {
  cluster_identifier                  = "example-redshift-cluster"
  node_type                           = "dc2.large"
  master_username                     = "adminuser"
  master_password                     = "yourpassword123"
  iam_roles                           = [aws_iam_role.redshift_role.arn]
  cluster_parameter_group_name        = aws_redshift_cluster_parameter_group.example.name
  automated_snapshot_retention_period = 1

  tags = {
    Name = "ExampleRedshiftCluster"
  }
}

# SNS Topic for Notifications
resource "aws_sns_topic" "redshift_events" {
  name = "redshift-events"
}

# SNS Subscription for Email Notifications
resource "aws_sns_topic_subscription" "redshift_events_email" {
  topic_arn = aws_sns_topic.redshift_events.arn
  protocol  = "email"
  endpoint  = "your-email@example.com"
}

# Event Subscription for Redshift Events
resource "aws_db_event_subscription" "redshift_events" {
  name                = "redshift-events-subscription"
  sns_topic           = aws_sns_topic.redshift_events.arn
  source_type         = "cluster"
  source_ids          = [aws_redshift_cluster.example.cluster_identifier]
  event_categories    = ["configuration", "management", "monitoring", "security"]
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-west-2`).
- **IAM Role**: Defines an IAM role that Redshift can assume if it needs to access other AWS services.
- **Redshift Cluster Parameter Group**: Creates a parameter group with example parameters like enabling user activity logging and requiring SSL.
- **Redshift Cluster**: Sets up a Redshift cluster using the defined parameter group and IAM role.
- **SNS Topic and Subscription**: Configures an SNS topic and subscription to send email notifications about Redshift events.
- **Event Subscription**: Subscribes to Redshift events and sends notifications to the SNS topic.

Make sure to replace `"yourpassword123"` and `"your-email@example.com"` with your desired password and email address respectively. This configuration is deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`.

