### Terraform HCL Program:

```hcl
# Configure the AWS Provider
provider "aws" {
  region = "us-west-2"
}

# Define a variable for the S3 bucket name
variable "bucket_name" {
  description = "The name of the S3 bucket"
  type        = string
  default     = "example-bucket"
}

# Create an S3 bucket
resource "aws_s3_bucket" "example_bucket" {
  bucket = var.bucket_name

  # Enable versioning for the bucket
  versioning {
    enabled = true
  }

  # Enable server-side encryption for the bucket
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Add tags to the bucket
  tags = {
    Name        = "ExampleBucket"
    Environment = "Test"
  }
}
```

This configuration will create an S3 bucket named `example-bucket` in the `us-west-2` region. It also enables versioning and server-side encryption for the bucket, and adds some basic tags for organization. You can customize the `bucket_name`, `region`, and other settings as needed.

