To store images for your website, we can use Amazon S3 (Simple Storage Service). S3 is a scalable object storage service that provides high availability, data durability, security, and performance. We'll create an S3 bucket to store your images and configure it to serve the images over HTTP/HTTPS.

Additionally, we'll create an IAM role with policies that allow read access to the S3 bucket, which can be attached to your web server or any other AWS service that needs to access the images.

Here's the Terraform configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Variable for the S3 bucket name
variable "bucket_name" {
  description = "The name of the S3 bucket"
  type        = string
  default     = "my-website-images-bucket"
}

# Create an S3 bucket
resource "aws_s3_bucket" "images_bucket" {
  bucket = var.bucket_name

  # Enable static website hosting
  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  # Enable versioning
  versioning {
    enabled = true
  }

  # Enable logging
  logging {
    target_bucket = "${var.bucket_name}-log"
    target_prefix = "log/"
  }

  # Enable server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name        = "ImagesBucket"
    Environment = "production"
  }
}

# Create a log bucket for the S3 bucket
resource "aws_s3_bucket" "log_bucket" {
  bucket = "${var.bucket_name}-log"

  acl = "private"

  tags = {
    Name        = "LogBucket"
    Environment = "production"
  }
}

# Create an IAM policy for read access to the S3 bucket
resource "aws_iam_policy" "s3_read_access_policy" {
  name        = "S3ReadAccessPolicy"
  description = "Policy to allow read access to the S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "s3:GetObject"
        ],
        Resource = [
          "arn:aws:s3:::${aws_s3_bucket.images_bucket.id}/*"
        ]
      }
    ]
  })
}

# Create an IAM role for the web server or other AWS services
resource "aws_iam_role" "web_server_role" {
  name = "WebServerRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "ec2.amazonaws.com"  # Change this if your web server is not running on EC2
        },
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "WebServerRole"
    Environment = "production"
  }
}

# Attach the S3 read access policy to the IAM role
resource "aws_iam_role_policy_attachment" "s3_read_access_attachment" {
  policy_arn = aws_iam_policy.s3_read_access_policy.arn
  role       = aws_iam_role.web_server_role.name
}

# Output the S3 bucket URL
output "bucket_url" {
  value = aws_s3_bucket.images_bucket.website_endpoint
}
```

This configuration creates an S3 bucket configured for static website hosting, enables versioning, logging, and server-side encryption. It also sets up an IAM role with a policy that allows read access to the S3 bucket, which can be used by your web server or other AWS services. The `bucket_url` output provides the URL where your images can be accessed.

