Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Create the main S3 bucket
resource "aws_s3_bucket" "main_bucket" {
  bucket = "mybucket"
  acl    = "private"

  tags = {
    Name        = "MainBucket"
    Environment = "production"
  }
}

# Create the destination S3 bucket for analytics results
resource "aws_s3_bucket" "analytics_bucket" {
  bucket = "mybucket-analytics-results"
  acl    = "private"

  tags = {
    Name        = "AnalyticsResultsBucket"
    Environment = "production"
  }
}

# Create an IAM policy for S3 analytics to write to the destination bucket
resource "aws_iam_policy" "s3_analytics_policy" {
  name        = "S3AnalyticsPolicy"
  description = "Policy to allow S3 analytics to write to the destination bucket"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = ["s3:PutObject"],
        Resource = "${aws_s3_bucket.analytics_bucket.arn}/*"
      }
    ]
  })
}

# Create an IAM role for S3 analytics
resource "aws_iam_role" "s3_analytics_role" {
  name = "S3AnalyticsRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "s3.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "s3_analytics_policy_attachment" {
  policy_arn = aws_iam_policy.s3_analytics_policy.arn
  role       = aws_iam_role.s3_analytics_role.name
}

# Configure S3 analytics on the main bucket
resource "aws_s3_bucket_analytics_configuration" "analytics_config" {
  bucket = aws_s3_bucket.main_bucket.id

  name = "MyAnalyticsConfig"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"
      destination {
        s3_bucket_destination {
          format     = "CSV"
          bucket_arn = aws_s3_bucket.analytics_bucket.arn
          prefix     = "analytics/"
        }
      }
    }
  }
}
```

This configuration ensures that the S3 analytics are set up correctly, using bucket references instead of hardcoded bucket names. The IAM role and policy are configured to allow S3 analytics to write the results to the designated analytics bucket.

