To achieve this, we will create two AWS S3 buckets using Terraform. The first bucket will store the objects for which we want to generate the inventory report. The second bucket will store the generated CSV inventory reports. We will also configure an S3 bucket inventory to generate a weekly report of all current object versions in the first bucket and store it in the second bucket.

Here's the Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "source_bucket_name" {
  description = "The name of the source S3 bucket."
  type        = string
  default     = "my-source-bucket-unique-name"
}

variable "inventory_bucket_name" {
  description = "The name of the inventory S3 bucket."
  type        = string
  default     = "my-inventory-bucket-unique-name"
}

# IAM policy for S3 bucket inventory
resource "aws_iam_policy" "s3_inventory_policy" {
  name        = "s3-inventory-policy"
  description = "Policy to allow S3 bucket inventory to write to the inventory bucket."

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = ["s3:PutObject"],
        Resource = "${aws_s3_bucket.inventory_bucket.arn}/*",
      },
      {
        Effect   = "Allow",
        Action   = ["s3:GetBucketAcl"],
        Resource = aws_s3_bucket.inventory_bucket.arn,
      }
    ]
  })
}

# IAM role for S3 bucket inventory
resource "aws_iam_role" "s3_inventory_role" {
  name = "s3-inventory-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "s3.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "s3_inventory_policy_attachment" {
  policy_arn = aws_iam_policy.s3_inventory_policy.arn
  role       = aws_iam_role.s3_inventory_role.name
}

# Source S3 bucket
resource "aws_s3_bucket" "source_bucket" {
  bucket = var.source_bucket_name

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# Inventory S3 bucket
resource "aws_s3_bucket" "inventory_bucket" {
  bucket = var.inventory_bucket_name

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

# S3 bucket inventory configuration
resource "aws_s3_bucket_inventory" "bucket_inventory" {
  bucket = aws_s3_bucket.source_bucket.id

  destination {
    bucket {
      format = "CSV"
      bucket_arn = aws_s3_bucket.inventory_bucket.arn
      prefix = "inventory/"
    }
  }

  included_object_versions = "Current"

  schedule {
    frequency = "Weekly"
  }

  optional_fields = ["Size", "LastModifiedDate", "StorageClass", "ETag", "IsMultipartUploaded", "ReplicationStatus"]
}
```

This configuration sets up two S3 buckets, configures versioning on the source bucket, and sets up an S3 bucket inventory to generate a weekly CSV report of all current object versions in the source bucket, storing the report in the inventory bucket. The necessary IAM role and policy are created to allow the S3 service to write the inventory report to the inventory bucket.

