The Terraform program will create an AWS S3 bucket and configure it to use server-side encryption with a KMS key. The program will define both the S3 bucket and the KMS key resource. It will also create an IAM role with the necessary permissions for the S3 bucket to use the KMS key for encryption.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a KMS Key
resource "aws_kms_key" "s3_encryption_key" {
  description             = "KMS key for encrypting S3 bucket"
  deletion_window_in_days = 10
  policy                  = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid       = "Enable IAM User Permissions",
        Effect    = "Allow",
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        },
        Action = [
          "kms:*"
        ],
        Resource = "*"
      }
    ]
  })
}

# Data source to get the current caller identity
data "aws_caller_identity" "current" {}

# Define an IAM role for S3 to use the KMS key
resource "aws_iam_role" "s3_kms_role" {
  name = "s3-kms-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "s3.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach a policy to the IAM role to allow S3 to use the KMS key
resource "aws_iam_role_policy" "s3_kms_policy" {
  name = "s3-kms-policy"
  role = aws_iam_role.s3_kms_role.id

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ],
        Resource = aws_kms_key.s3_encryption_key.arn
      }
    ]
  })
}

# Define an S3 bucket with KMS server-side encryption
resource "aws_s3_bucket" "encrypted_bucket" {
  bucket = "my-encrypted-bucket-${data.aws_caller_identity.current.account_id}"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = aws_kms_key.s3_encryption_key.arn
      }
    }
  }

  # Ensure the bucket is deleted when the resource is destroyed
  lifecycle {
    prevent_destroy = false
  }
}
```

