To address your request, I'll create a Terraform configuration that sets up two S3 buckets. The first bucket will be the main storage bucket, and the second bucket will store the access logs for the first bucket. Additionally, I'll create an IAM role with the necessary permissions to allow the main bucket to write its access logs to the log bucket.

Here's the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to any region you prefer
}

# Variable for the main bucket name
variable "main_bucket_name" {
  type        = string
  description = "The name of the main S3 bucket"
  default     = "my-main-bucket-unique-name"
}

# Variable for the log bucket name
variable "log_bucket_name" {
  type        = string
  description = "The name of the S3 bucket to store access logs"
  default     = "my-log-bucket-unique-name"
}

# Create the main S3 bucket
resource "aws_s3_bucket" "main_bucket" {
  bucket = var.main_bucket_name

  logging {
    target_bucket = aws_s3_bucket.log_bucket.id
    target_prefix = "log/"
  }

  acl = "private"

  tags = {
    Name        = "MainBucket"
    Environment = "production"
  }
}

# Create the log S3 bucket
resource "aws_s3_bucket" "log_bucket" {
  bucket = var.log_bucket_name

  acl = "private"

  tags = {
    Name        = "LogBucket"
    Environment = "production"
  }
}

# Create an IAM policy that allows writing to the log bucket
resource "aws_iam_policy" "s3_log_delivery_policy" {
  name        = "S3LogDeliveryPolicy"
  description = "Policy to allow S3 log delivery to the log bucket"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action = [
          "s3:PutObject"
        ],
        Resource = "${aws_s3_bucket.log_bucket.arn}/*",
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Effect = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action = [
          "s3:GetBucketAcl"
        ],
        Resource = aws_s3_bucket.log_bucket.arn
      }
    ]
  })
}

# Create an IAM role for S3 log delivery
resource "aws_iam_role" "s3_log_delivery_role" {
  name = "S3LogDeliveryRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "logging.s3.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "S3LogDeliveryInlinePolicy"
    policy = data.aws_iam_policy_document.s3_log_delivery_policy.json
  }
}

# Data source to get the JSON policy document for the IAM role
data "aws_iam_policy_document" "s3_log_delivery_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.log_bucket.arn}/*"
    ]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl"
    ]
    resources = [
      aws_s3_bucket.log_bucket.arn
    ]
  }
}
```

### Explanation:
1. **Provider Configuration**: Specifies the AWS provider and region.
2. **Variables**: Defines variables for the main and log bucket names with default values.
3. **Main S3 Bucket**: Creates the main S3 bucket with logging enabled, directing logs to the log bucket.
4. **Log S3 Bucket**: Creates the log S3 bucket where access logs will be stored.
5. **IAM Policy**: Defines an IAM policy that allows S3 to deliver logs to the log bucket.
6. **IAM Role**: Creates an IAM role that assumes the necessary permissions for S3 log delivery.
7. **Data Source**: Retrieves the JSON policy document for the IAM role.

This configuration ensures that the main bucket's access logs are stored in the log bucket securely. Make sure to replace the `default` values for `main_bucket_name` and `log_bucket_name` with unique names to avoid conflicts.

