To set up an infrastructure for an autograder using AWS CodeBuild, we need to create the following resources:

1. **IAM Role**: An IAM role that CodeBuild can assume to perform actions like pulling code from GitHub and storing results in S3.
2. **S3 Bucket**: A bucket to store the results of the autograding process.
3. **CodeBuild Project**: A project that defines how to build and test the student's code.

The CodeBuild project will be configured to trigger on a webhook from GitHub, pull the code, execute the tests, and store the results in the S3 bucket.

Below is the Terraform HCL configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "github_token" {
  type        = string
  description = "GitHub personal access token with repo permissions"
}

variable "github_repo_owner" {
  type        = string
  description = "Owner of the GitHub repository"
  default     = "your-github-username"
}

variable "github_repo_name" {
  type        = string
  description = "Name of the GitHub repository"
  default     = "your-repo-name"
}

variable "s3_bucket_name" {
  type        = string
  description = "Name of the S3 bucket to store results"
  default     = "autograder-results-bucket"
}

# S3 Bucket to store results
resource "aws_s3_bucket" "autograder_results" {
  bucket = var.s3_bucket_name

  versioning {
    enabled = true
  }

  tags = {
    Name        = "Autograder Results"
    Environment = "production"
  }
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-policy"
  description = "Policy for CodeBuild to access GitHub and S3"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ],
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/*"
        ]
      },
      {
        Effect = "Allow",
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ],
        Resource = [
          "arn:aws:logs:*:*:log-group:/aws/codebuild/*"
        ]
      },
      {
        Effect = "Allow",
        Action = [
          "codebuild:CreateReportGroup",
          "codebuild:CreateReport",
          "codebuild:UpdateReport",
          "codebuild:BatchPutTestCases"
        ],
        Resource = "*"
      }
    ]
  })
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "codebuild.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "codebuild-inline-policy"
    policy = data.aws_iam_policy_document.codebuild_policy.json
  }
}

# Data Source for CodeBuild Policy Document
data "aws_iam_policy_document" "codebuild_policy" {
  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.autograder_results.arn,
      "${aws_s3_bucket.autograder_results.arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "arn:aws:logs:*:*:log-group:/aws/codebuild/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "codebuild:CreateReportGroup",
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases"
    ]
    resources = "*"
  }
}

# CodeBuild Project
resource "aws_codebuild_project" "autograder" {
  name          = "autograder-project"
  description   = "CodeBuild project for running autograder"
  service_role  = aws_iam_role.codebuild_role.arn
  source_version = "main"

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_repo_owner}/${var.github_repo_name}.git"
    git_clone_depth = 1
    auth {
      type        = "OAUTH"
      resource    = var.github_token
    }
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:6.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "S3_BUCKET_NAME"
      value = aws_s3_bucket.autograder_results.bucket
    }
  }

  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
      group_name = "/aws/codebuild/autograder-project"
      stream_name = "autograder-stream"
    }
  }

  tags = {
    Name        = "Autograder Project"
    Environment = "production"
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region.
- **Variables**: Define necessary inputs such as GitHub credentials and S3 bucket name.
- **S3 Bucket**: Created to store the results of the autograding.
- **IAM Policy and Role**: Define the permissions required for CodeBuild to interact with S3 and CloudWatch Logs.
- **CodeBuild Project**: Configured to pull code from GitHub, use a standard build image, and execute the build process.

Make sure to replace `your-github-username` and `your-repo-name` with your actual GitHub repository owner and name, and provide a valid GitHub personal access token with repository permissions.

