To set up an infrastructure for an autograder using AWS S3 and AWS CodeBuild, we need to create the following resources:

1. **AWS S3 Bucket**: To store the results of the autograding process.
2. **AWS CodeBuild Project**: To build and run the autograding scripts.
3. **IAM Role**: For CodeBuild to access the S3 bucket and other necessary AWS services.
4. **GitHub Webhook (Optional)**: To trigger the CodeBuild project when new code is pushed to the repository.

Below is the Terraform HCL configuration that sets up these resources. This configuration assumes that you have already configured your AWS credentials and that you have a GitHub repository ready to use.

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables
variable "github_owner" {
  description = "The owner of the GitHub repository"
  type        = string
  default     = "your-github-username"
}

variable "github_repo" {
  description = "The name of the GitHub repository"
  type        = string
  default     = "your-repo-name"
}

variable "github_token" {
  description = "A personal access token with repo scope for GitHub"
  type        = string
  sensitive   = true
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket to store autograding results"
  type        = string
  default     = "autograding-results-bucket"
}

# S3 Bucket for storing autograding results
resource "aws_s3_bucket" "autograding_results" {
  bucket = var.s3_bucket_name

  versioning {
    enabled = true
  }

  tags = {
    Name        = "AutogradingResultsBucket"
    Environment = "production"
  }
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-autograding-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for CodeBuild to access S3
resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild-autograding-policy"
  description = "Policy for CodeBuild to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.autograding_results.arn,
          "${aws_s3_bucket.autograding_results.arn}/*"
        ]
      },
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "autograding" {
  name          = "autograding-project"
  description   = "CodeBuild project for running autograding scripts"
  service_role  = aws_iam_role.codebuild_role.arn
  source_version = "main"

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_owner}/${var.github_repo}.git"
    git_clone_depth = 1
    auth {
      type     = "PERSONAL_ACCESS_TOKEN"
      resource = var.github_token
    }
  }

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.autograding_results.bucket}/artifacts"
    name = "autograding-artifacts"
    namespace_type = "BUILD_ID"
    packaging = "ZIP"
  }

