    cloudwatch_logs {
      status = "ENABLED"
      group_name = "/aws/codebuild/autograding-project"
      stream_name_prefix = "autograding"
    }
  }

  tags = {
    Name        = "AutogradingProject"
    Environment = "production"
  }
}
```

