  description = "The owner of the GitHub repository."
  default     = "your-github-username"
}

variable "github_repo_name" {
  description = "The name of the GitHub repository."
  default     = "autograder-repo"
}

variable "github_connection_arn" {
  description = "The ARN of the GitHub connection created in AWS CodePipeline or AWS CodeBuild."
  default     = "arn:aws:codestar-connections:us-west-2:123456789012:connection/abcdef12-3456-7890-abcd-ef1234567890"
}

