  description = "Policy for CodeBuild to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.autograder_results.arn,
          "${aws_s3_bucket.autograder_results.arn}/*"
        ]
      },
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "autograder" {
  name          = "autograder-project"
  description   = "CodeBuild project for running autograder scripts"
  service_role  = aws_iam_role.codebuild_role.arn
  timeout_in_minutes = 60

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.bucket
    path = "artifacts/"
    namespace_type = "BUILD_ID"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "GITHUB_REPO_OWNER"
      value = var.github_repo_owner
    }
    environment_variable {
      name  = "GITHUB_REPO_NAME"
      value = var.github_repo_name
    }
  }

  source {
    type            = "GITHUB"
    location        = "https://github.com/${var.github_repo_owner}/${var.github_repo_name}.git"
    git_clone_depth = 1
    auth {
      type = "OAUTH"
      resource = var.github_connection_arn
    }
  }

  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
      group_name = "/aws/codebuild/autograder-project"
      stream_name = "autograder-project"
    }
  }

  tags = {
    Name        = "Autograder Project"
    Environment = "Production"
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-west-2`).
- **Variables**: Define the S3 bucket name, GitHub repository details, and GitHub connection ARN with default values.
- **S3 Bucket**: Creates an S3 bucket to store the results of the autograding process.
- **IAM Role and Policy**: Creates an IAM role and policy that allows CodeBuild to access the S3 bucket.
- **CodeBuild Project**: Configures a CodeBuild project to clone the GitHub repository, run the autograding scripts, and store the results in the S3 bucket.

Make sure to replace the `github_connection_arn` with the actual ARN of your GitHub connection in AWS. You can create this connection via the AWS Management Console under AWS CodePipeline or AWS CodeBuild.

