LLM Output #0:
To set up an infrastructure for an autograder using AWS CodeBuild and AWS VPC, we need to create the following components:

1. **VPC**: A Virtual Private Cloud to isolate the CodeBuild environment.
2. **Subnets**: Public and private subnets within the VPC.
3. **Internet Gateway**: To allow the VPC to communicate with the internet (only for necessary services like pulling code from GitHub).
4. **NAT Gateway**: To allow instances in the private subnet to access the internet for package installations or other dependencies.
5. **Security Groups**: To control inbound and outbound traffic to the CodeBuild environment.
6. **IAM Role**: An IAM role with permissions for CodeBuild to access necessary AWS services.
7. **CodeBuild Project**: Configured to run in the private subnet and pull code from GitHub.

Below is the Terraform HCL configuration to achieve this setup:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  default = "10.0.2.0/24"
}

variable "github_token" {
  type    = string
  default = ""
  sensitive = true
}

# Create VPC
resource "aws_vpc" "autograder_vpc" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "Autograder-VPC"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id

  tags = {
    Name = "Autograder-IGW"
  }
}

# Create Public Subnet
resource "aws_subnet" "autograder_public_subnet" {
  vpc_id                  = aws_vpc.autograder_vpc.id
  cidr_block              = var.public_subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "Autograder-Public-Subnet"
  }
}

# Create Route Table for Public Subnet
resource "aws_route_table" "autograder_public_rt" {
  vpc_id = aws_vpc.autograder_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.autograder_igw.id
  }

  tags = {
    Name = "Autograder-Public-RT"
  }
}

# Associate Public Subnet with Route Table
resource "aws_route_table_association" "autograder_public_rta" {
  subnet_id      = aws_subnet.autograder_public_subnet.id
  route_table_id = aws_route_table.autograder_public_rt.id
}

# Create Elastic IP for NAT Gateway
resource "aws_eip" "autograder_eip" {
  vpc = true

  tags = {
    Name = "Autograder-EIP"
  }
}

# Create NAT Gateway
resource "aws_nat_gateway" "autograder_ngw" {
  allocation_id = aws_eip.autograder_eip.id
  subnet_id     = aws_subnet.autograder_public_subnet.id

  tags = {
    Name = "Autograder-NGW"
  }
}

# Create Private Subnet
resource "aws_subnet" "autograder_private_subnet" {
  vpc_id     = aws_vpc.autograder_vpc.id
  cidr_block = var.private_subnet_cidr_block

  tags = {
    Name = "Autograder-Private-Subnet"
  }
}

# Create Route Table for Private Subnet
resource "aws_route_table" "autograder_private_rt" {
  vpc_id = aws_vpc.autograder_vpc.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.autograder_ngw.id
  }

  tags = {
    Name = "Autograder-Private-RT"
  }
}

# Associate Private Subnet with Route Table
resource "aws_route_table_association" "autograder_private_rta" {
  subnet_id      = aws_subnet.autograder_private_subnet.id
  route_table_id = aws_route_table.autograder_private_rt.id
}

# Create Security Group for CodeBuild
resource "aws_security_group" "autograder_sg" {
  name_prefix = "autograder-sg"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "Autograder-SG"
  }
}

# Create IAM Role for CodeBuild
resource "aws_iam_role" "autograder_codebuild_role" {
  name = "autograder-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM Role
resource "aws_iam_role_policy_attachment" "autograder_codebuild_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
  role       = aws_iam_role.autograder_codebuild_role.name
}

# Create CodeBuild Project
resource "aws_codebuild_project" "autograder_codebuild_project" {
  name          = "autograder-codebuild-project"
  description   = "CodeBuild project for running student code"
  service_role  = aws_iam_role.autograder_codebuild_role.arn
  build_timeout = 60

  source {
    type            = "GITHUB"
    location        = "https://github.com/your-repo/your-autograder.git"
    git_clone_depth = 1
    auth {
      type        = "OAUTH"
      resource    = var.github_token
    }
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "GITHUB_TOKEN"
      value = var.github_token
    }
  }

  vpc_config {
    vpc_id     = aws_vpc.autograder_vpc.id
    subnets    = [aws_subnet.autograder_private_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }

  tags = {
    Name = "Autograder-CodeBuild-Project"
  }
}
```

### Explanation:
- **VPC and Subnets**: We create a VPC with public and private subnets. The public subnet is used for the NAT Gateway, while the private subnet is where the CodeBuild project runs.
- **Internet Gateway and NAT Gateway**: The Internet Gateway allows the VPC to communicate with the internet, and the NAT Gateway allows the private subnet to access the internet for necessary operations.
- **Security Group**: The security group allows SSH access (port 22) and outbound traffic.
- **IAM Role**: The IAM role allows CodeBuild to perform necessary actions.
- **CodeBuild Project**: The CodeBuild project is configured to run in the private subnet and pull code from a GitHub repository using an OAuth token.

Make sure to replace `"https://github.com/your-repo/your-autograder.git"` with the actual URL of your GitHub repository. Also, provide a valid GitHub token in the `github_token` variable for authentication.

