To accomplish the task of creating a web service that allows users to upload cat pictures and provides random cat pictures on demand using AWS services, we will use the following components:

- **Amazon S3**: To store the uploaded cat pictures.
- **AWS API Gateway**: To create RESTful APIs for uploading and retrieving random cat pictures.
- **AWS Lambda**: To handle the logic for uploading pictures to S3 and retrieving random pictures from S3.
- **IAM Roles and Policies**: To grant necessary permissions to Lambda functions to interact with S3.

Below is the Terraform HCL configuration that sets up this infrastructure:

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store cat pictures"
  type        = string
  default     = "cat-pictures-bucket-unique-name"
}

resource "aws_s3_bucket" "cat_pictures" {
  bucket = var.bucket_name

  versioning {
    enabled = true
  }

  tags = {
    Name        = "CatPicturesBucket"
    Environment = "production"
  }
}

resource "aws_iam_role" "lambda_exec_role" {
  name = "lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_policy" "lambda_s3_access" {
  name        = "lambda-s3-access-policy"
  description = "Policy to allow Lambda to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_s3_access_attach" {
  policy_arn = aws_iam_policy.lambda_s3_access.arn
  role       = aws_iam_role.lambda_exec_role.name
}

resource "aws_lambda_function" "upload_cat_picture" {
  function_name = "upload-cat-picture"
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  role          = aws_iam_role.lambda_exec_role.arn

  filename         = "path/to/upload-cat-picture.zip"
  source_code_hash = filebase64sha256("path/to/upload-cat-picture.zip")

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.bucket
    }
  }
}

resource "aws_lambda_function" "get_random_cat_picture" {
  function_name = "get-random-cat-picture"
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  role          = aws_iam_role.lambda_exec_role.arn

  filename         = "path/to/get-random-cat-picture.zip"
  source_code_hash = filebase64sha256("path/to/get-random-cat-picture.zip")

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.bucket
    }
  }
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.upload_cat_picture.invoke_arn
}

resource "aws_lambda_permission" "allow_apigateway_upload" {
  statement_id  = "AllowExecutionFromAPIGatewayUpload"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload_cat_picture.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_pictures_api.execution_arn}/*/*/*"
}

resource "aws_api_gateway_resource" "random" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random"
}

resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random.id
  http_method             = aws_api_gateway_method.random_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.get_random_cat_picture.invoke_arn
}

resource "aws_lambda_permission" "allow_apigateway_random" {
  statement_id  = "AllowExecutionFromAPIGatewayRandom"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.get_random_cat_picture.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_pictures_api.execution_arn}/*/*/*"
}

resource "aws_api_gateway_deployment" "cat_pictures_deployment" {
  depends_on = [
    aws_api_gateway_integration.upload_integration,
    aws_api_gateway_integration.random_integration
  ]

  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"
}
```

### Explanation:
- **S3 Bucket**: Stores the cat pictures.
- **IAM Role and Policy**: Grants Lambda functions permission to read/write to the S3 bucket.
- **Lambda Functions**: 
  - `upload-cat-picture`: Handles the upload of cat pictures to S3.
  - `get-random-cat-picture`: Retrieves a random cat picture from S3.
- **API Gateway**: Exposes two endpoints:
  - `/upload` for POST requests to upload pictures.
  - `/random` for GET requests to retrieve a random picture.

### Notes:
- Replace `"path/to/upload-cat-picture.zip"` and `"path/to/get-random-cat-picture.zip"` with the actual paths to your Lambda function deployment packages.
- Ensure that the bucket name (`var.bucket_name`) is globally unique across all AWS accounts.
- The Lambda functions are written in Node.js 18.x, but you can change the runtime and code as per your preference.

