To accomplish the task of provisioning an EC2 instance and backing it up every day at midnight using AWS EC2 and AWS Backup, we need to create the following resources:

1. **EC2 Instance**: This will be the main resource that we want to back up.
2. **IAM Role and Policy**: The EC2 instance needs an IAM role with permissions to allow AWS Backup to perform backups.
3. **AWS Backup Vault**: A storage location for our backups.
4. **AWS Backup Plan**: Defines how often backups should occur and what resources should be backed up.
5. **AWS Backup Selection**: Specifies which resources (in this case, the EC2 instance) should be included in the backup plan.

Below is the Terraform HCL configuration that sets up these resources:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a VPC for the EC2 instance
resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "example-vpc"
  }
}

# Define an Internet Gateway for the VPC
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id

  tags = {
    Name = "example-igw"
  }
}

# Define a Subnet for the EC2 instance
resource "aws_subnet" "example" {
  vpc_id                  = aws_vpc.example.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "example-subnet"
  }
}

# Define a Security Group for the EC2 instance
resource "aws_security_group" "example" {
  name        = "example-sg"
  description = "Allow SSH and HTTP"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-sg"
  }
}

# Define an IAM role for the EC2 instance
resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Define an IAM policy for the EC2 instance to allow AWS Backup
resource "aws_iam_policy" "backup_policy" {
  name        = "backup-policy"
  description = "Policy for AWS Backup"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "backup:StartBackupJob",
          "backup:Describe*",
          "backup:Get*",
          "backup:List*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  policy_arn = aws_iam_policy.backup_policy.arn
  role       = aws_iam_role.backup_role.name
}

# Define an EC2 instance
resource "aws_instance" "example" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.example.id
  vpc_security_group_ids = [aws_security_group.example.id]

  iam_instance_profile = aws_iam_instance_profile.backup_profile.name

  tags = {
    Name = "example-instance"
  }
}

# Define an IAM instance profile for the EC2 instance
resource "aws_iam_instance_profile" "backup_profile" {
  name = "backup-profile"
  role = aws_iam_role.backup_role.name
}

# Define an AWS Backup Vault
resource "aws_backup_vault" "example" {
  name = "example-backup-vault"
}

# Define an AWS Backup Plan
resource "aws_backup_plan" "example" {
  name = "example-backup-plan"

  rule {
    rule_name         = "daily-backup"
    target_vault_name = aws_backup_vault.example.name
    schedule          = "cron(0 0 * * ? *)" # Daily at midnight UTC

    lifecycle {
      move_to_cold_storage_after_days = 30
      delete_after_days               = 120
    }

    recovery_point_tags = {
      Name = "example-recovery-point"
    }
  }
}

# Define an AWS Backup Selection
resource "aws_backup_selection" "example" {
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.example.id

  selection_tag {
    type = "STRINGEQUALS"
    key  = "Name"
    value = "example-instance"
  }
}
```

