2. **AWS EC2 Instance**: This resource will launch an Amazon Linux 2023 x86-64 instance using the key pair created above and will have an instance type of `t2.micro`.
3. **AWS Backup Vault**: This resource will create a backup vault where backups will be stored.
4. **AWS Backup Plan**: This resource will define a backup plan that runs daily at midnight, retains backups for 7 days, and specifies the resource type to back up.
5. **AWS Backup Selection**: This resource will associate the backup plan with the EC2 instance.
6. **IAM Role for Backup**: This resource will create an IAM role with the necessary permissions for AWS Backup to perform its tasks.

Below is the complete Terraform HCL configuration that implements the above resources:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Create an EC2 Key Pair
resource "aws_key_pair" "example_key_pair" {
  key_name   = "example-key-pair"
  public_key = file("./key.pub")
}

# Create an EC2 Instance
resource "aws_instance" "example_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Amazon Linux 2023 AMI ID for us-west-2
  instance_type = "t2.micro"
  key_name      = aws_key_pair.example_key_pair.key_name

  tags = {
    Name = "ExampleInstance"
  }
}

# Create a Backup Vault
resource "aws_backup_vault" "example_backup_vault" {
  name        = "example-backup-vault"
  description = "Backup vault for example instance"
}

# Create an IAM Role for Backup
resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the AWSBackupServiceRolePolicyForBackup policy to the IAM Role
resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
  role       = aws_iam_role.backup_role.name
}

# Create a Backup Plan
resource "aws_backup_plan" "example_backup_plan" {
  name = "example-backup-plan"

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.example_backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight UTC

    lifecycle {
      delete_after = 7  # Retain backups for 7 days
    }

    recovery_point_tags = {
      Name = "ExampleRecoveryPoint"
    }
  }

  advanced_backup_setting {
    resource_type = "EC2"

    backup_options = {
      WindowsVSS = "enabled"
    }
  }
}

# Create a Backup Selection
resource "aws_backup_selection" "example_backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.example_backup_plan.id

  selection_tag {
    type = "STRINGEQUALS"
    key  = "Name"
    value = "ExampleInstance"
  }
}
```

### Notes:
- The `ami` ID for Amazon Linux 2023 in the `us-west-2` region is provided. If you're deploying in a different region, you'll need to update this ID accordingly.
- The `schedule` for the backup plan is set to run daily at midnight UTC. Adjust the cron expression if you need a different schedule.
- The `advanced_backup_setting` includes a backup option for Windows VSS, which is not necessary for Linux instances but is included here as an example. You can remove it if not needed.
- Ensure that the `./key.pub` file exists in your working directory before running the Terraform configuration.

