To set up the infrastructure for a video streaming site using AWS CloudFront and AWS S3, we need to create the following resources:

1. **S3 Bucket**: To store the video content.
2. **IAM Role and Policy**: For CloudFront to access the S3 bucket.
3. **CloudFront Distribution**: To distribute the video content globally.

Below is the Terraform HCL configuration that accomplishes this:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variable for the name of the S3 bucket
variable "s3_bucket_name" {
  type        = string
  description = "The name of the S3 bucket to store video content"
  default     = "video-streaming-content-bucket"
}

# Create an S3 bucket to store video content
resource "aws_s3_bucket" "video_content_bucket" {
  bucket = var.s3_bucket_name

  # Enable versioning for the bucket
  versioning {
    enabled = true
  }

  # Enable server-side encryption
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  # Enable logging
  logging {
    target_bucket = "${var.s3_bucket_name}-logs"
    target_prefix = "log/"
  }

  tags = {
    Name        = "VideoContentBucket"
    Environment = "production"
  }
}

# Create an S3 bucket for logging
resource "aws_s3_bucket" "video_content_bucket_logs" {
  bucket = "${var.s3_bucket_name}-logs"

  tags = {
    Name        = "VideoContentBucketLogs"
    Environment = "production"
  }
}

# Create an IAM policy for CloudFront to access the S3 bucket
resource "aws_iam_policy" "cloudfront_access_policy" {
  name        = "cloudfront-access-policy"
  description = "Policy to allow CloudFront to access the S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudfront.amazonaws.com"
        },
        Action = "s3:GetObject",
        Resource = "${aws_s3_bucket.video_content_bucket.arn}/*",
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })
}

# Create an IAM role for CloudFront
resource "aws_iam_role" "cloudfront_origin_access_identity" {
  name = "cloudfront-origin-access-identity"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudfront.amazonaws.com"
        },
        Action = "sts:AssumeRole",
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "cloudfront_access_policy_attachment" {
  policy_arn = aws_iam_policy.cloudfront_access_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity.name
}

# Create a CloudFront distribution
resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin {
    domain_name = "${aws_s3_bucket.video_content_bucket.bucket}.s3.amazonaws.com"
    origin_id   = "video-content-origin"

    s3_origin_config {
      origin_access_identity = "origin-access-identity/cloudfront/${aws_cloudfront_origin_access_identity.canonical_user_id}"
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Video Streaming Distribution"
  default_root_object = "index.html"

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "video-content-origin"

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name        = "VideoStreamingDistribution"
    Environment = "production"
  }
}
```

This configuration sets up an S3 bucket to store video content, an IAM role and policy to allow CloudFront to access the S3 bucket, and a CloudFront distribution to serve the content globally. The S3 bucket is configured with versioning, server-side encryption, and logging. The CloudFront distribution is set up to use HTTPS and has no geographic restrictions.

