  description = "Policy to allow CloudFront to access the S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudfront.amazonaws.com"
        },
        Action = "s3:GetObject",
        Resource = "${aws_s3_bucket.video_content_bucket.arn}/*",
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })
}

# Create an IAM role for CloudFront
resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "CloudFrontOriginAccessIdentityRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudfront.amazonaws.com"
        },
        Action = "sts:AssumeRole",
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "cloudfront_access_policy_attachment" {
  policy_arn = aws_iam_policy.cloudfront_access_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
}

# Create a CloudFront distribution
resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin {
    domain_name = "${aws_s3_bucket.video_content_bucket.bucket}.s3.amazonaws.com"
    origin_id   = "S3-${var.bucket_name}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.origin_access_identity.cloudfront_origin_access_identity_id
    }
  }

  enabled             = true
    is_ipv6_enabled     = true
    comment             = "Video Streaming Distribution"
    default_root_object = "index.html"

    default_cache_behavior {
      allowed_methods  = ["GET", "HEAD"]
      cached_methods   = ["GET", "HEAD"]
      target_origin_id = "S3-${var.bucket_name}"

      forwarded_values {
        query_string = false

        cookies {
          forward = "none"
        }
      }

      viewer_protocol_policy = "redirect-to-https"
      min_ttl                = 0
      default_ttl            = 3600
      max_ttl                = 86400
    }

    restrictions {
      geo_restriction {
        restriction_type = "none"
      }
    }

    viewer_certificate {
      acm_certificate_arn = var.acm_certificate_arn
      ssl_support_method  = "sni-only"
    }
}

# Create a CloudFront Origin Access Identity
resource "aws_cloudfront_origin_access_identity" "origin_access_identity" {
  comment = "OAI for Video Streaming Distribution"
}

# Create a Route53 record for the video subdomain
resource "aws_route53_record" "video_subdomain_record" {
  zone_id = var.route53_zone_id
  name    = "${var.subdomain_name}.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_streaming_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_streaming_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}

# Variables for Route53 and ACM
variable "route53_zone_id" {
  description = "The Route53 hosted zone ID for the domain"
  default     = "Z1234567890ABCDEF"
}

variable "acm_certificate_arn" {
  description = "The ARN of the ACM certificate for the domain"
  default     = "arn:aws:acm:us-east-1:123456789012:certificate/12345678-1234-1234-1234-123456789012"
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region.
- **Variables**: Define configurable parameters with default values.
- **S3 Bucket**: Stores video content with versioning and encryption.
- **IAM Role and Policy**: Allow CloudFront to access the S3 bucket.
- **CloudFront Distribution**: Distributes content globally with HTTPS support.
- **Route53 Record**: Manages DNS records for the video subdomain.

Make sure to replace the `default` values for `route53_zone_id` and `acm_certificate_arn` with your actual Route53 hosted zone ID and ACM certificate ARN respectively.

