LLM Output #0:
To set up the infrastructure for a video streaming site that distributes video content globally, we will use the following AWS resources:

1. **AWS S3 Bucket**: To store the video content.
2. **AWS CloudFront Origin Access Control (OAC)**: To restrict access to the S3 bucket from CloudFront only.
3. **AWS CloudFront Distribution**: To distribute the video content globally.
4. **AWS Route53 Hosted Zone**: To manage DNS records for the domain name.
5. **AWS Route53 Record**: To create an A record pointing to the CloudFront distribution.

Additionally, we will create an IAM role and policy to allow CloudFront to access the S3 bucket through the OAC.

Below is the complete Terraform HCL configuration to achieve this setup:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Variables with default values
variable "domain_name" {
  description = "The domain name for the video streaming site"
  default     = "example.com"
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store video content"
  default     = "video-streaming-content-bucket"
}

# Create an S3 bucket to store video content
resource "aws_s3_bucket" "video_content" {
  bucket = var.bucket_name

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name        = "VideoContentBucket"
    Environment = "production"
  }
}

# Create a CloudFront Origin Access Control (OAC)
resource "aws_cloudfront_origin_access_control" "oac" {
  name          = "video-streaming-oac"
  description   = "Origin Access Control for video streaming"
  origin_access_control_config {
    name                              = "video-streaming-oac-config"
    signing_behavior                  = "always"
    signing_protocol                  = "sigv4"
  }
}

# Create an IAM policy for CloudFront to access the S3 bucket via OAC
resource "aws_iam_policy" "cloudfront_oac_policy" {
  name        = "cloudfront-oac-policy"
  description = "Policy allowing CloudFront to access S3 bucket via OAC"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudfront.amazonaws.com"
        },
        Action = "s3:GetObject",
        Resource = "${aws_s3_bucket.video_content.arn}/*",
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })
}

# Create an IAM role for CloudFront to assume
resource "aws_iam_role" "cloudfront_oac_role" {
  name = "cloudfront-oac-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "cloudfront.amazonaws.com"
        },
        Action = "sts:AssumeRole",
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })

  inline_policy {
    name = "cloudfront-oac-inline-policy"
    policy = data.aws_iam_policy_document.cloudfront_oac_policy.json
  }
}

# Create a CloudFront distribution
resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin {
    domain_name              = "${aws_s3_bucket.video_content.bucket}.s3.amazonaws.com"
    origin_id                = "video-streaming-origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id

    s3_origin_config {
      origin_access_identity = ""
    }
  }

  enabled             = true
    is_ipv6_enabled       = true
    comment             = "Video Streaming Distribution"
    default_root_object   = "index.html"

    default_cache_behavior {
      allowed_methods  = ["GET", "HEAD"]
      cached_methods   = ["GET", "HEAD"]
      target_origin_id = "video-streaming-origin"
      viewer_protocol_policy = "redirect-to-https"

      forwarded_values {
        query_string = false

        cookies {
          forward = "none"
        }
      }

      min_ttl                = 0
      default_ttl            = 3600
      max_ttl                = 86400
    }

    restrictions {
      geo_restriction {
        restriction_type = "none"
      }
    }

    viewer_certificate {
      cloudfront_default_certificate = true
    }
}

# Create a Route53 hosted zone
resource "aws_route53_zone" "primary" {
  name = var.domain_name
}

# Create a Route53 record pointing to the CloudFront distribution
resource "aws_route53_record" "video_streaming_cname" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_streaming_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_streaming_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}
```

This configuration sets up the necessary AWS resources to distribute video content globally using CloudFront, with restricted access to the S3 bucket via an Origin Access Control (OAC). It also configures DNS management using Route53. Make sure to replace `example.com` and `video-streaming-content-bucket` with your actual domain name and desired bucket name if different.

