### Description

The Terraform program will create the following AWS resources:

1. **AWS CloudFront Distribution**:
   - Configured with an S3 bucket as the origin.
   - Uses a CloudFront Origin Access Control (OAC) for secure access to the S3 bucket.
   - Default cache behavior configured to allow GET and HEAD methods.
   - Price class set to `PriceClass_200`.
   - Geographical restrictions to allow only specific countries (US, CA, GB, DE).
   - Uses the default CloudFront SSL/TLS certificate.

2. **AWS Route53 Hosted Zone**:
   - Created for the domain `netflix.com`.

3. **AWS Route53 Record Resources**:
   - Two records linked to the Route53 hosted zone.
   - These records will point to the CloudFront distribution.

4. **CloudFront Origin Access Control (OAC)**:
   - Configured to always sign requests using the `sigv4` protocol.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# Define variables with default values
variable "bucket_domain_name" {
  description = "The domain name of the S3 bucket"
  type        = string
  default     = "your-s3-bucket-name.s3.amazonaws.com"
}

variable "oac_name" {
  description = "The name of the CloudFront Origin Access Control"
  type        = string
  default     = "S3VideoContentOAC"
}

# Create a CloudFront Origin Access Control
resource "aws_cloudfront_origin_access_control" "oac" {
  name                            = var.oac_name
  origin_access_control_origin_type = "s3"
  signing_behavior                = "always"
  signing_protocol                = "sigv4"
}

# Create a CloudFront distribution
resource "aws_cloudfront_distribution" "distribution" {
  origin {
    domain_name            = var.bucket_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.oac.id
    origin_id              = "s3_video_content_origin"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3_video_content_origin"
    viewer_protocol_policy = "allow-all"
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# Create a Route53 hosted zone
resource "aws_route53_zone" "zone" {
  name = "netflix.com"
}

# Create Route53 records pointing to the CloudFront distribution
resource "aws_route53_record" "record_a" {
  zone_id = aws_route53_zone.zone.id
  name    = "www.netflix.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.distribution.domain_name
    zone_id                = aws_cloudfront_distribution.distribution.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "record_cname" {
  zone_id = aws_route53_zone.zone.id
  name    = "video.netflix.com"
  type    = "CNAME"

  records = [aws_cloudfront_distribution.distribution.domain_name]
}
```

### Notes
- Replace `"your-s3-bucket-name.s3.amazonaws.com"` with the actual domain name of your S3 bucket.
- The `region` in the provider block can be adjusted based on your preference, but it must be a region where CloudFront is supported.
- Ensure that the S3 bucket policy allows the CloudFront OAC to access the bucket. This is not included in this configuration but is necessary for the setup to work correctly.

