	instance_valid(instance, ami)

	lb_resources_valid(lb, lb_listener, target_group, target_group_attachment, instance, vpc, subnets, security_group)
	security_group_valid(security_group, vpc)

	subnets_valid(subnets, vpc)
	vpc_valid(vpc)
