LLM Output #0:
To set up the infrastructure for a video streaming site with multiple servers balanced using AWS Load Balancing, we will create an AWS EC2 Auto Scaling group behind an Application Load Balancer (ALB). This setup ensures that the load is distributed across multiple instances, providing high availability and scalability.

The Terraform configuration will include:
- An AWS VPC with public subnets in multiple availability zones.
- An Internet Gateway to allow internet access from the instances.
- Route tables and route table associations.
- Security groups for both the ALB and EC2 instances.
- An IAM role and policy for the EC2 instances to allow them to access necessary AWS services.
- An Application Load Balancer with a listener on port 80.
- A target group to which the EC2 instances will register.
- An Auto Scaling group to manage the number of EC2 instances based on demand.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "instance_type" {
  default = "t3.micro"
}

variable "min_instances" {
  default = 2
}

variable "max_instances" {
  default = 4
}

variable "ami_id" {
  default = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI ID for us-west-2
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "video-streaming-vpc"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = ["10.0.${count.index + 1}.0/24", "10.0.${count.index + 3}.0/24"][count.index]
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "video-streaming-public-subnet-${count.index}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "video-streaming-igw"
  }
}

# Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "video-streaming-public-route-table"
  }
}

# Route Table Association
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "video-streaming-alb-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-alb-sg"
  }
}

# Security Group for EC2 Instances
resource "aws_security_group" "ec2_sg" {
  name_prefix = "video-streaming-ec2-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-ec2-sg"
  }
}

# IAM Role for EC2 Instances
resource "aws_iam_role" "ec2_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for EC2 Instances
resource "aws_iam_policy" "ec2_policy" {
  name        = "video-streaming-ec2-policy"
  description = "Policy for EC2 instances in video streaming setup"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "cloudwatch:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "ec2_policy_attachment" {
  policy_arn = aws_iam_policy.ec2_policy.arn
  role       = aws_iam_role.ec2_role.name
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "ec2_profile" {
  name = "video-streaming-ec2-profile"
  role = aws_iam_role.ec2_role.name
}

# Launch Template for EC2 Instances
resource "aws_launch_template" "video_streaming_lt" {
  name_prefix   = "video-streaming-lt"
  image_id      = var.ami_id
  instance_type = var.instance_type
  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_profile.name
  }
  network_interfaces {
    associate_public_ip_address = true
    security_groups           = [aws_security_group.ec2_sg.id]
    subnet_id                 = element(aws_subnet.public.*.id, 0)
  }
  user_data = <<-EOF
              #!/bin/bash
              yum update -y
              yum install -y httpd
              systemctl start httpd
              systemctl enable httpd
              echo "<html><body><h1>Welcome to Video Streaming Server ${hostname}</h1></body></html>" > /var/www/html/index.html
              EOF
}

# Application Load Balancer
resource "aws_lb" "video_streaming_alb" {
  name               = "video-streaming-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "video-streaming-alb"
  }
}

# Target Group
resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video-streaming-tg"
  }
}

# Listener for ALB
resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

# Auto Scaling Group
resource "aws_autoscaling_group" "video_streaming_asg" {
  launch_template {
    id      = aws_launch_template.video_streaming_lt.id
    version = "$Latest"
  }

  vpc_zone_identifier = aws_subnet.public[*].id

  min_size = var.min_instances
  max_size = var.max_instances

  target_group_arns = [aws_lb_target_group.video_streaming_tg.arn]

  tag {
    key                 = "Name"
    value               = "video-streaming-instance"
    propagate_at_launch = true
  }
}

# Data Source for Availability Zones
data "aws_availability_zones" "available" {}
```

This configuration sets up a basic infrastructure for a video streaming site with load balancing using AWS services. It includes networking components, security configurations, and auto-scaling capabilities to handle varying loads efficiently.

