LLM Output #0:
To build the infrastructure for a video streaming site with load balancing using AWS services, we will create the following components:

1. **AWS VPC**: A Virtual Private Cloud to host our resources securely.
2. **AWS EC2 Instances**: Multiple EC2 instances to serve the video streaming content.
3. **AWS Elastic Load Balancer (ELB)**: To distribute incoming traffic across multiple EC2 instances.
4. **AWS Route 53**: To manage DNS records and route traffic to the ELB.
5. **IAM Roles and Policies**: Necessary IAM roles and policies for EC2 instances and other AWS services.

Below is the Terraform HCL configuration that sets up this infrastructure:

```hcl
provider "aws" {
  region = var.region
}

# Variables with default values
variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "instance_count" {
  description = "Number of EC2 instances to launch"
  default     = 3
}

variable "instance_type" {
  description = "Type of EC2 instance"
  default     = "t3.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
}

variable "key_name" {
  description = "Name of the SSH key pair to use for EC2 instances"
  default     = "my-key-pair"
}

variable "domain_name" {
  description = "Domain name for the video streaming site"
  default     = "video-streaming.example.com"
}

# VPC Module
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 3.0"

  name = "video-streaming-vpc"
  cidr = "10.0.0.0/16"

  azs             = ["${var.region}a", "${var.region}b", "${var.region}c"]
  public_subnets  = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_subnets = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "video-streaming-vpc"
  }
}

# Security Group for EC2 Instances
resource "aws_security_group" "ec2_sg" {
  name        = "video-streaming-ec2-sg"
  description = "Allow HTTP and SSH traffic"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-ec2-sg"
  }
}

# IAM Role for EC2 Instances
resource "aws_iam_role" "ec2_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "video-streaming-ec2-role"
  }
}

# IAM Policy for EC2 Instances
resource "aws_iam_policy" "ec2_policy" {
  name        = "video-streaming-ec2-policy"
  description = "Policy for EC2 instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "cloudwatch:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
    ]
  })

  tags = {
    Name = "video-streaming-ec2-policy"
  }
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "ec2_policy_attachment" {
  policy_arn = aws_iam_policy.ec2_policy.arn
  role       = aws_iam_role.ec2_role.name
}

# EC2 Instances
resource "aws_instance" "video_streaming_instances" {
  count         = var.instance_count
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = element(module.vpc.public_subnets, count.index)
  key_name      = var.key_name
  iam_instance_profile = aws_iam_instance_profile.ec2_instance_profile.name

  tags = {
    Name = "video-streaming-instance-${count.index}"
  }
}

# IAM Instance Profile
resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "video-streaming-ec2-instance-profile"
  role = aws_iam_role.ec2_role.name
}

# Elastic Load Balancer
resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  security_groups    = [aws_security_group.ec2_sg.id]
  subnets            = module.vpc.public_subnets
  enable_deletion_protection = false

  tags = {
    Name = "video-streaming-lb"
  }
}

# Target Group for ELB
resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video-streaming-tg"
  }
}

# Register EC2 Instances with Target Group
resource "aws_lb_target_group_attachment" "video_streaming_tg_attachments" {
  count            = var.instance_count
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = element(aws_instance.video_streaming_instances.*.id, count.index)
  port             = 80
}

# Listener for ELB
resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }

  tags = {
    Name = "video-streaming-listener"
  }
}

# Route 53 Hosted Zone
resource "aws_route53_zone" "video_streaming_zone" {
  name = var.domain_name

  tags = {
    Name = "video-streaming-zone"
  }
}

# Route 53 Record Set
resource "aws_route53_record" "video_streaming_record" {
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.video_streaming_lb.dns_name
    zone_id                = aws_lb.video_streaming_lb.zone_id
    evaluate_target_health = true
  }

  tags = {
    Name = "video-streaming-record"
  }
}
```

This Terraform configuration sets up a complete infrastructure for a video streaming site, including a VPC, EC2 instances, an Elastic Load Balancer, and Route 53 for DNS management. It also includes necessary IAM roles and policies for the EC2 instances. Make sure to replace `ami-0c55b159cbfafe1f0` with a valid AMI ID available in your region and ensure that the `key_name` variable points to an existing SSH key pair in your AWS account.

