To set up the infrastructure for a video streaming site with load balancing, we'll create a VPC with subnets, a security group, EC2 instances, an Application Load Balancer (ALB), a target group, and a Route53 zone and record. We'll also create an IAM role for the EC2 instances to allow them to access necessary AWS services if required.

Here's the Terraform configuration:

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  type        = string
  default     = "us-west-2"
}

variable "instance_count" {
  description = "Number of EC2 instances to launch"
  type        = number
  default     = 3
}

variable "instance_type" {
  description = "Type of EC2 instance"
  type        = string
  default     = "t3.micro"
}

variable "ami_id" {
  description = "AMI ID for the EC2 instances"
  type        = string
  default     = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
}

variable "domain_name" {
  description = "Domain name for the Route53 record"
  type        = string
  default     = "example.com"
}

variable "hosted_zone_id" {
  description = "Hosted Zone ID for the Route53 record"
  type        = string
  default     = "Z1234567890ABCDEF" # Replace with your actual Hosted Zone ID
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 3.0"

  name = "video-streaming-vpc"
  cidr = "10.0.0.0/16"

  azs             = ["${var.region}a", "${var.region}b", "${var.region}c"]
  public_subnets  = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
  private_subnets = ["10.0.101.0/24", "10.0.102.0/24", "10.0.103.0/24"]

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "video-streaming-vpc"
  }
}

resource "aws_security_group" "video_streaming_sg" {
  name_prefix = "video-streaming-sg"
  vpc_id      = module.vpc.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video-streaming-sg"
  }
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "video-streaming-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.ec2_instance_role.name
}

resource "aws_instance" "video_streaming_instances" {
  count         = var.instance_count
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = element(module.vpc.public_subnets, count.index)
  vpc_security_group_ids = [aws_security_group.video_streaming_sg.id]
  iam_instance_profile = aws_iam_instance_profile.ec2_instance_profile.name

  tags = {
    Name = "video-streaming-instance-${count.index}"
  }
}

resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "video-streaming-ec2-profile"
  role = aws_iam_role.ec2_instance_role.name
}

resource "aws_lb" "video_streaming_alb" {
  name               = "video-streaming-alb"
  internal           = false
  security_groups    = [aws_security_group.video_streaming_sg.id]
  subnets            = module.vpc.public_subnets
  enable_deletion_protection = false

  tags = {
    Name = "video-streaming-alb"
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = module.vpc.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video-streaming-tg"
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }
}

resource "aws_lb_target_group_attachment" "video_streaming_tg_attachments" {
  count            = var.instance_count
  target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  target_id        = element(aws_instance.video_streaming_instances.*.id, count.index)
  port             = 80
}

resource "aws_route53_record" "video_streaming_record" {
  zone_id = var.hosted_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.video_streaming_alb.dns_name
    zone_id                = aws_lb.video_streaming_alb.zone_id
    evaluate_target_health = true
  }
}
```

This configuration sets up a VPC with public and private subnets, a security group allowing HTTP and HTTPS traffic, EC2 instances, an Application Load Balancer, a target group, and a Route53 record pointing to the ALB. The EC2 instances are attached to the target group, and the ALB forwards traffic to these instances. An IAM role is created for the EC2 instances to allow them to use SSM for management purposes.

