Here's the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_blocks" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "database_identifier" {
  description = "Identifier for the RDS instance"
  default     = "dolphinscheduler"
}

variable "database_version" {
  description = "Version of the PostgreSQL database"
  default     = "17.1"
}

variable "database_allocated_storage" {
  description = "Allocated storage for the PostgreSQL database in GB"
  default     = 5
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainIGW"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.public_subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet-${count.index + 1}"
  }
}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

# Associate Route Table with Public Subnets
resource "aws_route_table_association" "public" {
  count          = length(var.public_subnet_cidr_blocks)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Security Group for Database Access
resource "aws_security_group" "db_sg" {
  name_prefix = "db-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust this to restrict access as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBSecurityGroup"
  }
}

# IAM Role for RDS
resource "aws_iam_role" "rds_role" {
  name = "rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy for RDS
resource "aws_iam_policy" "rds_policy" {
  name        = "rds-policy"
  description = "Policy for RDS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "rds_policy_attachment" {
  policy_arn = aws_iam_policy.rds_policy.arn
  role       = aws_iam_role.rds_role.name
}

# Create RDS PostgreSQL Instance
resource "aws_db_instance" "postgres" {
  allocated_storage    = var.database_allocated_storage
  engine               = "postgres"
  engine_version       = var.database_version
  instance_class       = "db.t3.micro"
  name                 = var.database_identifier
  username             = "admin"
  password             = "securepassword123" # Change this to a secure password
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.db_sg.id]
  db_subnet_group_name = aws_db_subnet_group.main.name
  iam_database_authentication_enabled = true
  iam_roles = [aws_iam_role.rds_role.arn]

  tags = {
    Name = "PostgreSQLInstance"
  }
}

# Create DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "MainDBSubnetGroup"
  }
}
```

### Explanation:
1. **Provider Configuration**: Configured to use AWS provider with a specific region (`us-west-2`).
2. **Variables**: Defined variables for VPC CIDR block, public subnet CIDR blocks, database identifier, version, and allocated storage with default values.
3. **VPC Setup**: Created a VPC with DNS support and hostnames enabled.
4. **Internet Gateway**: Created an internet gateway and associated it with the VPC.
5. **Public Subnets**: Created public subnets based on the provided CIDR blocks.
6. **Route Table**: Created a route table for public subnets and associated it with the internet gateway.
