### Description

The Terraform program will set up an Amazon Virtual Private Cloud (VPC) with two public subnets across two availability zones. It will also create a security group specifically for database access. A MySQL RDS instance with version 8.4.3 and a storage capacity of 5GB will be deployed within this VPC, secured by the designated security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_class" {
  description = "Instance class for the RDS MySQL instance"
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the RDS MySQL instance in GB"
  default     = 5
}

variable "db_engine_version" {
  description = "Engine version for the RDS MySQL instance"
  default     = "8.4.3"
}

variable "db_name" {
  description = "Name of the RDS MySQL database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the RDS MySQL database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS MySQL database"
  sensitive   = true
  default     = "securepassword123"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MyVPC"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MyInternetGateway"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet-${count.index + 1}"
  }
}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

# Associate Route Table with Public Subnets
resource "aws_route_table_association" "public" {
  count          = length(var.subnet_cidr_blocks)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Create Security Group for Database Access
resource "aws_security_group" "db" {
  name_prefix = "db-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBSecurityGroup"
  }
}

# Create MySQL RDS Instance
resource "aws_db_instance" "mysql" {
  allocated_storage       = var.db_allocated_storage
  engine                  = "mysql"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_class
  name                    = var.db_name
  username                = var.db_username
  password                = var.db_password
  skip_final_snapshot     = true
  publicly_accessible     = true
  vpc_security_group_ids  = [aws_security_group.db.id]
  db_subnet_group_name    = aws_db_subnet_group.main.name

  tags = {
    Name = "MySQLDBInstance"
  }
}

# Create DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "MainDBSubnetGroup"
  }
}
```

### Notes:
- The `db_password` variable is marked as sensitive. In a real-world scenario, it's recommended to use AWS Secrets Manager or another secure method to manage sensitive information.
- The security group allows inbound traffic on port 3306 from any IP (`0.0.0.0/0`). This is for demonstration purposes and should be restricted to specific IPs or ranges in production environments.
- The RDS instance is set to be publicly accessible. Ensure this setting aligns with your security requirements. Consider using a private subnet and an Elastic Load Balancer or NAT Gateway for more secure configurations.
- The `skip_final_snapshot` parameter is set to `true` for convenience during testing. In production, you should manage snapshots appropriately to avoid data loss.

