  description = "The username for the PostgreSQL database."
  type        = string
  default     = "myuser"
}

variable "database_password" {
  description = "The password for the PostgreSQL database."
  type        = string
  sensitive   = true
  default     = "mypassword"
}

# Create a KMS Key for encrypting the RDS instance
resource "aws_kms_key" "rds_encryption_key" {
  description             = "KMS key for encrypting RDS instance"
  deletion_window_in_days = 10
}

# Create a KMS alias for the key
resource "aws_kms_alias" "rds_encryption_key_alias" {
  name          = "alias/rds-encryption-key"
  target_key_id = aws_kms_key.rds_encryption_key.key_id
}

# Create a custom parameter group for PostgreSQL
resource "aws_db_parameter_group" "postgres_custom_param_group" {
  name   = "custom-postgres-param-group"
  family = "postgres14"

  parameter {
    name         = "max_connections"
    value        = "100"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "shared_buffers"
    value        = "25%"
    apply_method = "pending-reboot"
  }
}

# Create a security group for the RDS instance
resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  description = "Security group for RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Change this to a more restrictive CIDR block in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create the RDS instance
resource "aws_db_instance" "postgres_rds_instance" {
  allocated_storage    = 20
  engine               = "postgres"
  engine_version       = "14.6"
  instance_class       = "db.t3.micro"
  name                 = var.database_name
  username             = var.database_username
  password             = var.database_password
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  multi_az             = true
  backup_retention_period = 7
  parameter_group_name = aws_db_parameter_group.postgres_custom_param_group.name
  kms_key_id           = aws_kms_key.rds_encryption_key.arn
  skip_final_snapshot  = true # Set to false in production to avoid accidental data loss
}

# Create a DB subnet group for the RDS instance
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = var.subnet_ids

  tags = {
    Name = "RDS Subnet Group"
  }
}
```

This configuration includes:
- A KMS key and alias for encrypting the RDS instance.
- A custom parameter group for PostgreSQL settings.
- A security group to control access to the RDS instance.
- An RDS instance configured with the specified parameters.
- A DB subnet group to place the RDS instance within the specified subnets.

Make sure to replace the default values for `vpc_id` and `subnet_ids` with your actual VPC and subnet IDs. Also, consider restricting the `cidr_blocks` in the security group ingress rule to only allow access from trusted IP addresses.

