### Description

The Terraform program will provision a secure PostgreSQL database instance within a specified AWS VPC. The setup includes:

- **VPC and Subnets**: Utilizes existing VPC and subnets for the RDS instance deployment.
- **RDS Instance**: Configured with PostgreSQL as the database engine, specifying the engine version, storage size, and enabling multi-AZ deployment for high availability.
- **KMS Key**: Creates a KMS key for encrypting the RDS instance data at rest.
- **DB Parameter Group**: Defines a custom parameter group for PostgreSQL settings.
- **Security Group**: Manages inbound and outbound traffic rules for the RDS instance.
- **Final Snapshot Identifier**: Specifies "pgsnapshot" as the final snapshot identifier for the RDS instance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

# Variables with default values
variable "region" {
  description = "AWS region"
  default     = "us-west-2"
}

variable "vpc_id" {
  description = "ID of the VPC where the RDS instance will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs within the VPC"
  type        = list(string)
}

variable "db_instance_identifier" {
  description = "Identifier for the RDS instance"
  default     = "secure-postgres-db"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "dbadmin"
}

variable "db_password" {
  description = "Password for the database"
  sensitive   = true
  default     = "securepassword123!"
}

variable "storage_size" {
  description = "Storage size for the RDS instance in GB"
  default     = 20
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  default     = "14.6"
}

# Create a KMS key for encrypting the RDS instance
resource "aws_kms_key" "rds_encryption_key" {
  description             = "KMS key for encrypting RDS instance"
  deletion_window_in_days = 10
}

# Create a DB parameter group for PostgreSQL
resource "aws_db_parameter_group" "postgres_param_group" {
  name   = "custom-postgres-param-group"
  family = "postgres14"

  parameter {
    name         = "max_connections"
    value        = "100"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "shared_buffers"
    value        = "4MB"
    apply_method = "pending-reboot"
  }
}

# Create a security group for the RDS instance
resource "aws_security_group" "rds_sg" {
  name        = "rds-security-group"
  description = "Security group for RDS instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust this to your needs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create the RDS instance
resource "aws_db_instance" "postgres_db" {
  allocated_storage       = var.storage_size
  engine                  = "postgres"
  engine_version          = var.engine_version
  instance_class          = "db.t3.medium"
  name                    = var.db_name
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  multi_az                = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "pgsnapshot"
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  kms_key_id              = aws_kms_key.rds_encryption_key.arn
}

# Create a DB subnet group for the RDS instance
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = var.subnet_ids

  tags = {
    Name = "RDS Subnet Group"
  }
}
```

### Notes:
- Ensure that the `vpc_id` and `subnet_ids` variables are set to appropriate values for your AWS environment.
- The `cidr_blocks` in the security group ingress rule should be adjusted to restrict access to the RDS instance only to trusted IP addresses or ranges.
- The `db_password` variable is marked as sensitive to prevent it from being logged or displayed in the console output.
- The `skip_final_snapshot` is set to `false` to ensure that a final snapshot is taken when the RDS instance is deleted, using the identifier `pgsnapshot`.

