The Terraform program I will define will create an AWS RDS MySQL database instance with the following specifications:
- Database Engine: MySQL 5.7
- Instance Class: db.t3.micro
- Allocated Storage: 200 GB
- Public Accessibility: Enabled
- Security Group: A new security group that allows inbound traffic on port 3306 from any IP address (0.0.0.0/0)
- Master Password: Randomly generated and stored in AWS Secrets Manager for security

Additionally, the program will create an IAM role with the necessary permissions to allow the RDS instance to store its credentials in AWS Secrets Manager.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a random password for the MySQL DB
resource "random_password" "db_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}|;:,.<>?/~`"
}

# Store the generated password in AWS Secrets Manager
resource "aws_secretsmanager_secret" "db_credentials" {
  name = "rds-mysql-credentials"
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({ username = "admin", password = random_password.db_password.result })
}

# Create a security group for the RDS instance
resource "aws_security_group" "rds_sg" {
  name        = "rds-mysql-sg"
  description = "Allow MySQL access from anywhere"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create an IAM role for the RDS instance to access Secrets Manager
resource "aws_iam_role" "rds_secrets_manager_access" {
  name = "rds-secrets-manager-access"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the necessary policy to the IAM role
resource "aws_iam_role_policy_attachment" "secrets_manager_access" {
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
  role       = aws_iam_role.rds_secrets_manager_access.name
}

# Create the RDS MySQL instance
resource "aws_db_instance" "mysql" {
  allocated_storage    = 200
  engine               = "mysql"
  engine_version       = "5.7"
  instance_class       = "db.t3.micro"
  name                 = "mydb"
  username             = "admin"
  password             = random_password.db_password.result
  publicly_accessible  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
  skip_final_snapshot  = true

  # Reference the IAM role for Secrets Manager access
  iam_database_authentication_enabled = true
  iam_roles                           = [aws_iam_role.rds_secrets_manager_access.arn]
}
```

This configuration ensures that the RDS MySQL instance is created with the specified parameters, and the password is securely managed using AWS Secrets Manager. The security group allows public access on port 3306, and the IAM role provides the necessary permissions for the RDS instance to interact with Secrets Manager.

