The Terraform program I will define will set up a PostgreSQL database instance in AWS. It will include the following components:

- **VPC**: A custom Virtual Private Cloud with one public subnet.
- **Security Group**: Configured to allow inbound traffic on port 5432 for PostgreSQL.
- **DB Subnet Group**: Associates the subnet with the RDS instance.
- **IAM Role**: For the RDS instance, though it's not strictly necessary for this setup, it's included for future extensibility.
- **RDS Instance**: Configured with the specified PostgreSQL engine version, instance class, allocated storage, backup retention period, and maintenance window.

The configuration will use default values where possible and will be deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`.

Here is the complete Terraform HCL program:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "instance_class" {
  description = "Instance class for the RDS instance"
  default     = "db.t3.micro"
}

variable "allocated_storage" {
  description = "Allocated storage for the RDS instance in GB"
  default     = 20
}

variable "engine_version" {
  description = "PostgreSQL engine version"
  default     = "13.6"
}

variable "backup_retention_period" {
  description = "Backup retention period in days"
  default     = 5
}

variable "maintenance_window" {
  description = "Maintenance window for the RDS instance"
  default     = "Mon:03:00-Mon:06:00"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "custom-vpc"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "custom-igw"
  }
}

# Create a public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

# Create a route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

# Associate the route table with the public subnet
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Create a security group for the RDS instance
resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Allow inbound traffic on port 5432"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust as necessary for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-security-group"
  }
}

# Create a DB subnet group
resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.public.id]

  tags = {
    Name = "main-db-subnet-group"
  }
}

# Create an IAM role for the RDS instance (optional, for future extensibility)
resource "aws_iam_role" "rds" {
  name = "rds-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "rds-role"
  }
}

# Create the RDS instance
resource "aws_db_instance" "postgres" {
  allocated_storage    = var.allocated_storage
  engine               = "postgres"
  engine_version       = var.engine_version
  instance_class       = var.instance_class
  name                 = "mydb"
  username             = "admin"
  password             = "password123" # Change this to a secure password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot  = true
  backup_retention_period = var.backup_retention_period
  maintenance_window    = var.maintenance_window

  tags = {
    Name = "my-postgres-db"
  }
}
