The Terraform program I will define will set up an AWS RDS Aurora MySQL cluster along with an RDS Proxy for enhanced connection management. The setup includes creating a Virtual Private Cloud (VPC), subnets, security groups, necessary IAM roles, and using AWS Secrets Manager to securely store database credentials. The configuration will be deployable with Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`. All required resources and variables will be fully specified.

Here is the complete Terraform HCL program:

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region to deploy the resources"
  type        = string
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "List of CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_class" {
  description = "Instance class for the Aurora DB instances"
  type        = string
  default     = "db.r6g.large"
}

variable "db_cluster_identifier" {
  description = "Identifier for the Aurora DB cluster"
  type        = string
  default     = "aurora-cluster"
}

variable "db_name" {
  description = "Name of the database"
  type        = string
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  type        = string
  sensitive   = true
  default     = "securepassword123!"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "aurora-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "aurora-subnet-${count.index}"
  }
}

resource "aws_security_group" "db" {
  name_prefix = "aurora-db-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict this in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-db-sg"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "aurora-subnet-group"
  }
}

resource "aws_rds_cluster" "main" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.02.2"
  master_username         = var.db_username
  master_password         = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"

  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]

  tags = {
    Name = "aurora-cluster"
  }
}

resource "aws_rds_cluster_instance" "instances" {
  count              = 2
  identifier         = "${var.db_cluster_identifier}-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.main.id
  instance_class     = var.db_instance_class
  engine             = aws_rds_cluster.main.engine
  engine_version     = aws_rds_cluster.main.engine_version

  tags = {
    Name = "aurora-instance-${count.index}"
  }
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-db-credentials"

  tags = {
    Name = "aurora-db-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = var.db_password
  })
}

resource "aws_iam_role" "rds_proxy" {
  name = "aurora-rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "aurora-rds-proxy-role"
  }
}

resource "aws_iam_policy" "rds_proxy" {
  name = "aurora-rds-proxy-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Effect = "Allow"
        Resource = aws_secretsmanager_secret.db_credentials.arn
      },
    ]
  })

  tags = {
    Name = "aurora-rds-proxy-policy"
  }
}

resource "aws_iam_role_policy_attachment" "rds_proxy" {
  policy_arn = aws_iam_policy.rds_proxy.arn
  role       = aws_iam_role.rds_proxy.name
}

resource "aws_db_proxy" "main" {
  name                   = "aurora-db-proxy"
  engine_family          = "MYSQL"
  require_tls            = true
  idle_client_timeout    = 300
  auth {
    auth_scheme = "SECRETS"
    iam_auth    = false
    description = "Aurora DB Proxy Auth"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  vpc_subnet_ids = aws_subnet.public[*].id
  vpc_security_group_ids = [aws_security_group.db.id]

  tags = {
    Name = "aurora-db-proxy"
  }
}
```

This Terraform configuration sets up an Aurora MySQL cluster with two instances, a VPC with public subnets, a security group, a DB subnet group, and an RDS Proxy. It also uses AWS Secrets Manager to store the database credentials securely. The IAM role and policy required for the RDS Proxy to access the secrets are also created.

