The Terraform program I will define sets up an AWS RDS Aurora MySQL cluster with an associated proxy for enhanced connection management. This setup includes creating a Virtual Private Cloud (VPC), subnets, security groups, IAM roles, and AWS Secrets Manager for securely storing database credentials. The RDS Aurora MySQL cluster will have a backup retention period of 5 days and a preferred backup window from 7 AM to 9 AM.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "aurora_cluster_identifier" {
  default = "my-aurora-cluster"
}

variable "aurora_instance_class" {
  default = "db.r5.large"
}

variable "aurora_engine_version" {
  default = "5.7.mysql_aurora.2.10.2"
}

variable "aurora_database_name" {
  default = "mydatabase"
}

variable "aurora_username" {
  default = "admin"
}

variable "aurora_password" {
  default = "securepassword123"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "aurora-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "aurora-igw"
  }
}

# Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "aurora-public-subnet-${count.index + 1}"
  }
}

# Security Group for RDS
resource "aws_security_group" "rds" {
  name_prefix = "aurora-rds-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict this in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-rds-sg"
  }
}

# Security Group for RDS Proxy
resource "aws_security_group" "proxy" {
  name_prefix = "aurora-proxy-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict this in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-proxy-sg"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "aurora-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "aurora-db-subnet-group"
  }
}

# RDS Aurora Cluster
resource "aws_rds_cluster" "main" {
  cluster_identifier      = var.aurora_cluster_identifier
  engine                  = "aurora-mysql"
  engine_version          = var.aurora_engine_version
  master_username         = var.aurora_username
  master_password         = var.aurora_password
  database_name           = var.aurora_database_name
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"

  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = {
    Name = "aurora-cluster"
  }
}

# RDS Aurora Instances
resource "aws_rds_cluster_instance" "instances" {
  count              = 2
  identifier         = "${var.aurora_cluster_identifier}-instance-${count.index + 1}"
  cluster_identifier = aws_rds_cluster.main.id
  instance_class     = var.aurora_instance_class
  engine             = aws_rds_cluster.main.engine
  engine_version     = aws_rds_cluster.main.engine_version

  tags = {
    Name = "aurora-instance-${count.index + 1}"
  }
}

# Secrets Manager Secret for RDS Credentials
resource "aws_secretsmanager_secret" "rds_credentials" {
  name = "aurora-rds-credentials"

  tags = {
    Name = "aurora-rds-credentials"
  }
}

# Secrets Manager Secret Version for RDS Credentials
resource "aws_secretsmanager_secret_version" "rds_credentials" {
  secret_id     = aws_secretsmanager_secret.rds_credentials.id
  secret_string = jsonencode({ username = var.aurora_username, password = var.aurora_password })
}

# IAM Role for RDS Proxy
resource "aws_iam_role" "rds_proxy" {
  name = "aurora-rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "aurora-rds-proxy-role"
  }
}

# IAM Policy for RDS Proxy
resource "aws_iam_policy" "rds_proxy" {
  name        = "aurora-rds-proxy-policy"
  description = "Policy for RDS Proxy to access Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Effect   = "Allow"
        Resource = aws_secretsmanager_secret.rds_credentials.arn
      },
    ]
  })

  tags = {
    Name = "aurora-rds-proxy-policy"
  }
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "rds_proxy" {
  policy_arn = aws_iam_policy.rds_proxy.arn
  role       = aws_iam_role.rds_proxy.name
}

# RDS Proxy
resource "aws_db_proxy" "main" {
  name                   = "aurora-rds-proxy"
  engine_family          = "MYSQL"
  require_tls            = true
  idle_client_timeout    = 1800
  debug_logging          = false
  auth {
    auth_scheme = "SECRETS"
    iam_auth    = false
    description = "RDS Proxy Auth"
    secret_arn  = aws_secretsmanager_secret.rds_credentials.arn
  }
  vpc_subnet_ids         = aws_subnet.public[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]

  tags = {
    Name = "aurora-rds-proxy"
  }
}
```

