The Terraform program will set up an AWS RDS Aurora MySQL cluster along with an RDS Proxy for enhanced connection management. It will include the necessary networking components such as a VPC, subnets, and security groups. Additionally, it will create an IAM role for the RDS Proxy and use AWS Secrets Manager to securely store the database credentials. The RDS cluster will be configured to create a final snapshot with the identifier "snapshot" upon deletion.

Here is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_class" {
  default = "db.r5.large"
}

variable "db_cluster_identifier" {
  default = "aurora-cluster"
}

variable "db_name" {
  default = "mydatabase"
}

variable "db_username" {
  default = "admin"
}

variable "db_password" {
  default = "securepassword123"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "aurora-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "aurora-igw"
  }
}

# Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "aurora-subnet-${count.index + 1}"
  }
}

# Security Group for RDS Cluster
resource "aws_security_group" "rds" {
  name_prefix = "aurora-rds-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-rds-sg"
  }
}

# Security Group for RDS Proxy
resource "aws_security_group" "proxy" {
  name_prefix = "aurora-proxy-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-proxy-sg"
  }
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "aurora-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = {
    Name = "aurora-subnet-group"
  }
}

# RDS Aurora Cluster
resource "aws_rds_cluster" "main" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = "aurora-mysql"
  engine_version          = "8.0.mysql_aurora.3.02.2"
  master_username         = var.db_username
  master_password         = var.db_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"

  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  lifecycle {
    create_before_destroy = true
  }

  final_snapshot_identifier = "snapshot"

  tags = {
    Name = "aurora-cluster"
  }
}

# RDS Aurora Instances
resource "aws_rds_cluster_instance" "instances" {
  count              = length(var.subnet_cidr_blocks)
  identifier         = "${var.db_cluster_identifier}-instance-${count.index + 1}"
  cluster_identifier = aws_rds_cluster.main.id
  instance_class     = var.db_instance_class
  engine             = aws_rds_cluster.main.engine
  engine_version     = aws_rds_cluster.main.engine_version

  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "aurora-instance-${count.index + 1}"
  }
}

# Secrets Manager Secret for Database Credentials
resource "aws_secretsmanager_secret" "db_credentials" {
  name = "aurora-db-credentials"

  tags = {
    Name = "aurora-db-credentials"
  }
}

# Secrets Manager Secret Version for Database Credentials
resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id     = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({ username = var.db_username, password = var.db_password })
}

# IAM Role for RDS Proxy
resource "aws_iam_role" "rds_proxy" {
  name = "aurora-rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      },
    ]
  })

  tags = {
    Name = "aurora-rds-proxy-role"
  }
}

# IAM Policy for RDS Proxy
resource "aws_iam_policy" "rds_proxy" {
  name        = "aurora-rds-proxy-policy"
  description = "Policy for RDS Proxy to access Secrets Manager"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Effect   = "Allow"
        Resource = aws_secretsmanager_secret.db_credentials.arn
      },
    ]
  })

  tags = {
    Name = "aurora-rds-proxy-policy"
  }
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "rds_proxy" {
  policy_arn = aws_iam_policy.rds_proxy.arn
  role       = aws_iam_role.rds_proxy.name
}

# RDS Proxy
resource "aws_db_proxy" "main" {
  name                   = "aurora-proxy"
  engine_family          = "MYSQL"
  require_tls            = true
  idle_client_timeout    = 1800
  auth {
    auth_scheme = "SECRETS"
    iam_auth    = false
    description = "RDS Proxy Auth"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  vpc_subnet_ids         = aws_subnet.public[*].id
  vpc_security_group_ids = [aws_security_group.proxy.id]

  role_arn = aws_iam_role.rds_proxy.arn

  tags = {
    Name = "aurora-proxy"
  }
}
```

This configuration sets up the entire infrastructure required for an Aurora MySQL cluster with an RDS Proxy, including networking, security, and credential management. Adjust the `cidr_blocks`, `db_instance_class`, and other parameters as needed for your specific requirements.

