Certainly! Below is a Terraform configuration that sets up a basic Amazon Lightsail instance with user data. The user data script will install Apache HTTP Server on the instance at launch.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role and Policy**: Creates an IAM role and policy for the Lightsail instance. The policy allows the instance to perform actions like logging to CloudWatch.
- **Lightsail Instance**: Launches a Lightsail instance with the specified blueprint, bundle, and region. It also includes user data to install Apache HTTP Server.
- **Output**: Provides the public IP address of the created Lightsail instance.

### Terraform HCL Program:

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an IAM role for the Lightsail instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role
resource "aws_iam_role_policy_attachment" "lightsail_instance_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
  role       = aws_iam_role.lightsail_instance_role.name
}

# Create a Lightsail instance
resource "aws_lightsail_instance" "basic_instance" {
  name              = "basic-lightsail-instance"
  availability_zone = "us-east-1a"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_1_0"
  key_pair_name     = var.key_pair_name

  user_data = <<-EOF
              #!/bin/bash
              sudo yum update -y
              sudo yum install -y httpd
              sudo systemctl start httpd
              sudo systemctl enable httpd
              echo "<html><body><h1>Hello from Terraform!</h1></body></html>" | sudo tee /var/www/html/index.html
              EOF

  tags = {
    Name = "Basic-Lightsail-Instance"
  }
}

# Output the public IP address of the Lightsail instance
output "public_ip" {
  value = aws_lightsail_instance.basic_instance.public_ip
}

# Variable for key pair name
variable "key_pair_name" {
  description = "The name of the SSH key pair to use for the Lightsail instance."
  type        = string
  default     = "default-key-pair"
}
```

### Notes:
- Replace `default-key-pair` with your actual key pair name if you have one.
- The `availability_zone` should match the region specified in the provider configuration.
- The `blueprint_id` and `bundle_id` can be adjusted based on your requirements.
- Ensure that the AWS credentials configured in your environment have the necessary permissions to create Lightsail instances and manage IAM roles.

