### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role for Lightsail**: Creates an IAM role with the necessary permissions for Lightsail operations.
- **Lightsail Instance**: Creates a Lightsail instance with automatic snapshots enabled.

### Terraform HCL Configuration:

```hcl
# Provider configuration
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# IAM Role for Lightsail
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM role
resource "aws_iam_role_policy_attachment" "lightsail_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
  role       = aws_iam_role.lightsail_instance_role.name
}

