variable "instance_plan" {
  description = "The plan for the Lightsail instance"
  default     = "nano_1_0"
}

# Create an IAM role for the Lightsail instance (optional, but good practice)
resource "aws_iam_role" "lightsail_instance_role" {
  name = "${var.instance_name}-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role (optional, adjust as needed)
resource "aws_iam_role_policy_attachment" "lightsail_instance_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.lightsail_instance_role.name
}

# Create a Lightsail instance
