  name        = "lightsail-bucket-access-policy"
  description = "Policy to allow access to the Lightsail bucket"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ],
        Resource = [
          "arn:aws:s3:::${aws_lightsail_bucket.example.name}",
          "arn:aws:s3:::${aws_lightsail_bucket.example.name}/*"
        ]
      }
    ]
  })
}

# Create an IAM role for the Lightsail instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "lightsail.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_lightsail_bucket_access" {
  policy_arn = aws_iam_policy.lightsail_bucket_access.arn
  role       = aws_iam_role.lightsail_instance_role.name
}

# Attach the IAM role to the Lightsail instance
resource "aws_lightsail_instance" "example_with_role" {
  name              = var.instance_name
  availability_zone = "us-east-1a"  # Ensure this matches the region
  blueprint_id      = "ubuntu_20_04"
  bundle_id         = "nano_1_0"
  iam_instance_profile_name = aws_iam_role.lightsail_instance_role.name
}
```

### Explanation:
1. **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region. You can change this to any other region where Lightsail is available.
2. **Variables**: Two variables, `instance_name` and `bucket_name`, are defined with default values.
3. **Lightsail Instance**: A Lightsail instance is created with the specified name, availability zone, blueprint, and bundle.
4. **Lightsail Bucket**: A Lightsail bucket is created with the specified name.
5. **IAM Policy**: An IAM policy is created to allow the Lightsail instance to perform actions on the Lightsail bucket.
6. **IAM Role**: An IAM role is created that the Lightsail instance can assume.
7. **IAM Role Policy Attachment**: The IAM policy is attached to the IAM role.
8. **Attach IAM Role to Lightsail Instance**: The IAM role is attached to the Lightsail instance, allowing it to access the Lightsail bucket.

This configuration ensures that the Lightsail instance has the necessary permissions to interact with the Lightsail bucket.

