### Description

The Terraform program will create an Amazon S3 Glacier vault for long-term data archiving. The configuration includes:

- **Provider Configuration**: Specifies the AWS provider and region.
- **IAM Role**: Creates an IAM role with policies necessary for interacting with S3 Glacier.
- **S3 Glacier Vault**: Creates an S3 Glacier vault with a specified name.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to your preferred region
}

# Define a variable for the S3 Glacier vault name with a default value
variable "glacier_vault_name" {
  description = "Name of the S3 Glacier vault"
  type        = string
  default     = "long-term-archive-vault"
}

# Create an IAM role for accessing S3 Glacier
resource "aws_iam_role" "glacier_access_role" {
  name = "${var.glacier_vault_name}-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

# Attach a policy to the IAM role to allow access to S3 Glacier
resource "aws_iam_role_policy" "glacier_access_policy" {
  name = "${var.glacier_vault_name}-access-policy"
  role = aws_iam_role.glacier_access_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:CreateVault",
          "glacier:DeleteArchive",
          "glacier:DescribeVault",
          "glacier:GetJobOutput",
          "glacier:InitiateJob",
          "glacier:ListJobs",
          "glacier:ListVaults",
          "glacier:UploadArchive"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Create the S3 Glacier vault
resource "aws_glacier_vault" "long_term_archive" {
  name = var.glacier_vault_name

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:GetJobOutput",
          "glacier:DescribeVault",
          "glacier:ListVaults",
          "glacier:ListJobs"
        ]
        Effect   = "Allow"
        Resource = aws_glacier_vault.long_term_archive.arn
        Principal = {
          AWS = aws_iam_role.glacier_access_role.arn
        }
      }
    ]
  })

  lifecycle {
    ignore_changes = [access_policy]
  }
}
