Below is a Terraform configuration that sets up an S3 bucket with versioning, server-side encryption, and a lifecycle policy:

### Description:
- **S3 Bucket**: A new S3 bucket is created with a unique name.
- **Versioning**: Versioning is enabled to keep multiple versions of an object.
- **Server-Side Encryption**: Server-side encryption is enabled using AWS-managed keys (SSE-S3).
- **Lifecycle Policy**: A lifecycle policy is configured to transition objects to the `GLACIER` storage class after 30 days and delete them after 365 days.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

resource "aws_s3_bucket" "long_term_storage" {
  bucket = "my-long-term-storage-bucket-${var.environment}"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  lifecycle_rule {
    id      = "transition-and-expiration-rule"
    enabled = true

    transition {
      days          = 30
      storage_class = "GLACIER"
    }

    expiration {
      days = 365
    }
  }

  tags = {
    Name        = "LongTermStorageBucket"
    Environment = var.environment
  }
}

variable "environment" {
  description = "The environment for which the bucket is being created (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}
```

