### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role**: Creates an IAM role with a trust relationship to allow S3 Glacier to assume it.
- **IAM Policy**: Defines an IAM policy that specifies the actions allowed on the S3 Glacier vault.
- **IAM Role Policy Attachment**: Attaches the IAM policy to the IAM role.
- **S3 Glacier Vault**: Creates an S3 Glacier vault.
- **Access Policy**: Sets an access policy on the S3 Glacier vault to control who can perform actions on it.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to your preferred region
}

# Create an IAM role for S3 Glacier
resource "aws_iam_role" "glacier_role" {
  name = "glacier-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      },
    ]
  })
}

# Create an IAM policy for accessing the S3 Glacier vault
resource "aws_iam_policy" "glacier_access_policy" {
  name        = "glacier-access-policy"
  description = "Policy to allow access to the S3 Glacier vault"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:GetJobOutput",
          "glacier:DescribeJob",
          "glacier:ListJobs"
        ]
        Effect   = "Allow"
        Resource = aws_glacier_vault.glacier_vault.arn
      },
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "glacier_role_policy_attachment" {
  policy_arn = aws_iam_policy.glacier_access_policy.arn
  role       = aws_iam_role.glacier_role.name
}

# Create an S3 Glacier vault
resource "aws_glacier_vault" "glacier_vault" {
  name = "my-glacier-vault"
}

# Set an access policy on the S3 Glacier vault
resource "aws_glacier_vault_lock" "glacier_vault_lock" {
  vault_name = aws_glacier_vault.glacier_vault.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:GetJobOutput",
          "glacier:DescribeJob",
          "glacier:ListJobs"
        ]
        Effect   = "Allow"
        Resource = aws_glacier_vault.glacier_vault.arn
        Principal = {
          AWS = aws_iam_role.glacier_role.arn
        }
      },
    ]
  })

  complete_lock = true
}
```

### Notes:
- The `region` in the provider block can be changed to any AWS region where you want to create the S3 Glacier vault.
- The `complete_lock` attribute in the `aws_glacier_vault_lock` resource is set to `true`, which means once the lock is applied, it cannot be changed. Ensure this is what you intend before applying the configuration.
- The IAM role and policy are created specifically for accessing the S3 Glacier vault, ensuring that only entities with the appropriate permissions can interact with the vault.

