Certainly! Below is a Terraform script that sets up an AWS Network Load Balancer (NLB) and attaches it to an EC2 instance of type `t2.micro`. The script includes necessary IAM roles, security groups, and other configurations required for the setup.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **IAM Role and Policy**: Creates an IAM role with a policy that allows the EC2 instance to perform basic actions like logging.
- **Security Group**: Sets up a security group to allow traffic on port 80 (HTTP).
- **EC2 Instance**: Launches an EC2 instance of type `t2.micro` with the specified security group and IAM role.
- **Network Load Balancer (NLB)**: Creates a Network Load Balancer.
- **Target Group**: Creates a target group for the NLB.
- **Listener**: Attaches a listener to the NLB that forwards traffic to the target group.

### Terraform HCL Script:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for the EC2 instance
resource "aws_iam_role" "ec2_role" {
  name = "ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach a policy to the IAM role
resource "aws_iam_role_policy_attachment" "ec2_policy_attach" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
  role       = aws_iam_role.ec2_role.name
}

# Create an IAM instance profile
resource "aws_iam_instance_profile" "ec2_profile" {
  name = "ec2-profile"
  role = aws_iam_role.ec2_role.name
}

# Create a security group for the EC2 instance
resource "aws_security_group" "ec2_sg" {
  name        = "ec2-sg"
  description = "Allow HTTP traffic"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

# Create an internet gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Create a subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet"
  }
}

# Create a route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-route-table"
  }
}

# Associate the route table with the subnet
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Launch an EC2 instance
resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.public.id
  iam_instance_profile = aws_iam_instance_profile.ec2_profile.name

  vpc_security_group_ids = [aws_security_group.ec2_sg.id]

  tags = {
    Name = "web-instance"
  }
}

# Create a Network Load Balancer
resource "aws_lb" "nlb" {
  name               = "my-nlb"
  internal           = false
  load_balancer_type = "network"
  subnets            = [aws_subnet.public.id]

  tags = {
    Name = "my-nlb"
  }
}

# Create a target group for the NLB
resource "aws_lb_target_group" "tg" {
  name     = "my-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    matcher             = "200"
    path                = "/"
    protocol_version    = "HTTP1"
  }

  tags = {
    Name = "my-tg"
  }
}

# Register the EC2 instance with the target group
resource "aws_lb_target_group_attachment" "attachment" {
  target_group_arn = aws_lb_target_group.tg.arn
  target_id        = aws_instance.web.id
  port             = 80
}

# Create a listener for the NLB
resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.nlb.arn
  protocol          = "TCP"
  port              = "80"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.tg.arn
  }
}
```

### Notes:
- The AMI ID (`ami-0c55b159cbfafe1f0`) is for Amazon Linux 2 in the `us-west-2` region. You may need to change this if you're deploying in a different region.
- The script assumes that the EC2 instance will be running a web server on port 80. If your application runs on a different port, adjust the security group rules and target group settings accordingly.
- Ensure that the region specified in the provider block matches the region where you intend to deploy the resources.

