Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) in AWS. This configuration includes creating a VPC, subnets, security groups, and an IAM role for the ALB. The ALB will be set up to listen on HTTP (port 80).

### Description:
- **VPC**: A Virtual Private Cloud with one public subnet in each availability zone.
- **Security Group**: Allows inbound traffic on port 80 (HTTP).
- **IAM Role**: An IAM role with necessary permissions for the ALB.
- **Application Load Balancer**: Configured to listen on HTTP (port 80) across the public subnets.

### Terraform Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index + 1}"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}

# Create Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Create IAM Role for ALB
resource "aws_iam_role" "alb_role" {
  name = "alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM Role
resource "aws_iam_role_policy_attachment" "alb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonElasticLoadBalancingFullAccess"
  role       = aws_iam_role.alb_role.name
}

# Create Application Load Balancer
resource "aws_lb" "main" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "example-alb"
  }
}

# Create a target group for the ALB
resource "aws_lb_target_group" "main" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-target-group"
  }
}

# Create a listener for the ALB
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}
```

This configuration sets up a basic infrastructure for an Application Load Balancer in AWS. You can customize the `region`, `vpc_cidr_block`, and `subnet_cidr_blocks` variables as needed. To deploy this configuration, save it to a `.tf` file, initialize Terraform (`terraform init`), and apply the changes (`terraform apply`).

