The Terraform program I will define will create an Application Load Balancer (ALB) named `test-lb-tf` in AWS. This ALB will be configured with appropriate security groups and subnets, and it will not be internal. Additionally, deletion protection will be enabled to prevent accidental deletion of the load balancer.

Below is the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

# Define the VPC for the ALB
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

# Define two public subnets for the ALB
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  availability_zone = "us-west-2a"  # Adjust based on your region

  tags = {
    Name = "public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  availability_zone = "us-west-2b"  # Adjust based on your region

  tags = {
    Name = "public-subnet-b"
  }
}

# Define an Internet Gateway for the VPC
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

# Define a route table for the public subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

# Associate the public subnets with the route table
resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# Define a security group for the ALB
resource "aws_security_group" "alb_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

# Define the Application Load Balancer
resource "aws_lb" "test_lb_tf" {
  name               = "test-lb-tf"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  enable_deletion_protection = true

  tags = {
    Name = "test-lb-tf"
  }
}
```

This configuration sets up a VPC with two public subnets, an internet gateway, and a route table to allow traffic to and from the internet. It also creates a security group that allows HTTP traffic on port 80 and associates it with the ALB. The ALB itself is configured to use these subnets and security group, and deletion protection is enabled.

