Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) in AWS, along with Elastic IPs (EIPs) for its listeners. The configuration includes creating an IAM role for the ALB, necessary security groups, and subnets within a VPC.

### Description:
- **VPC**: A Virtual Private Cloud with two public subnets in different availability zones.
- **Security Group**: Allows HTTP (port 80) and HTTPS (port 443) traffic.
- **Elastic IPs (EIPs)**: Two EIPs are allocated and associated with the ALB's listeners.
- **Application Load Balancer (ALB)**: Configured with two listeners (HTTP and HTTPS) using the allocated EIPs.
- **IAM Role**: An IAM role with the necessary permissions for the ALB to perform its functions.

### Terraform Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index + 1}"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "example-public-route-table"
  }
}

# Associate Route Table with Public Subnets
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Create Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Allocate Elastic IPs
resource "aws_eip" "alb_eip" {
  count = 2
  vpc   = true

  tags = {
    Name = "alb-eip-${count.index + 1}"
  }
}

# Create Application Load Balancer
resource "aws_lb" "main" {
  name               = "example-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id

  ip_address_type = "ipv4"

  tags = {
    Name = "example-alb"
  }
}

# Create HTTP Listener for ALB
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"
  alpn_policy       = "HTTP2Preferred"

  default_action {
    type = "forward"

    forward {
      target_group_arns = [aws_lb_target_group.main.arn]
    }
  }

  # Associate Elastic IP with HTTP Listener
  resource "aws_lb_listener_rule" "http_redirect" {
    listener_arn = aws_lb_listener.http.arn
    priority     = 100

    action {
      type             = "redirect"
      redirect {
        protocol       = "HTTPS"
        port           = "443"
        host           = "#{host}"
        path           = "/#{path}"
        query          = "#{query}"
        status_code    = "HTTP_301"
      }
    }

    condition {
      field  = "http-request-method"
      values = ["GET"]
    }
  }
}

# Create HTTPS Listener for ALB
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"

  certificate_arn = "arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn-here"

  default_action {
    type = "forward"

    forward {
      target_group_arns = [aws_lb_target_group.main.arn]
    }
  }

  # Associate Elastic IP with HTTPS Listener
  resource "aws_lb_listener_certificate" "https_cert" {
    listener_arn    = aws_lb_listener.https.arn
    certificate_arn = "arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn-here"
  }
}

# Create Target Group for ALB
resource "aws_lb_target_group" "main" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    matcher             = "200-299"
  }

  tags = {
    Name = "example-target-group"
  }
}

# IAM Role for ALB
resource "aws_iam_role" "alb_role" {
  name = "alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM Role
resource "aws_iam_role_policy_attachment" "alb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSServiceRoleForElasticLoadBalancing"
  role       = aws_iam_role.alb_role.name
}
```

### Notes:
- Replace `"arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-arn-here"` with your actual ACM certificate ARN.
- Ensure that the region specified in the `provider` block matches the region where your ACM certificate is located.
- This configuration assumes that you have the necessary permissions to create these resources in your AWS account.

This Terraform script will create a fully functional Application Load Balancer with Elastic IPs, security groups, and necessary IAM roles.

