Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) that forwards traffic to a Network Load Balancer (NLB). This configuration includes the necessary IAM roles, security groups, and other resources required for the setup.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region.
- **VPC and Subnets**: Creates a VPC with two public subnets across two availability zones.
- **Security Groups**: Defines security groups for both the ALB and NLB.
- **Network Load Balancer (NLB)**: Sets up a NLB with target groups.
- **Application Load Balancer (ALB)**: Configures an ALB that forwards traffic to the NLB.
- **IAM Roles**: Creates an IAM role for the ALB to perform necessary actions.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index + 1}"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "example-public-route-table"
  }
}

# Associate Route Table with Public Subnets
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Security Group for NLB
resource "aws_security_group" "nlb_sg" {
  name_prefix = "nlb-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "nlb-security-group"
  }
}

# Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Network Load Balancer
resource "aws_lb" "nlb" {
  name               = "example-nlb"
  internal           = false
  load_balancer_type = "network"
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.nlb_sg.id]

  tags = {
    Name = "example-nlb"
  }
}

# Target Group for NLB
resource "aws_lb_target_group" "nlb_tg" {
  name     = "example-nlb-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-nlb-target-group"
  }
}

# Listener for NLB
resource "aws_lb_listener" "nlb_listener" {
  load_balancer_arn = aws_lb.nlb.arn
  protocol          = "TCP"
  port              = "80"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_tg.arn
  }
}

# Application Load Balancer
resource "aws_lb" "alb" {
  name               = "example-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb_sg.id]

  tags = {
    Name = "example-alb"
  }
}

# Target Group for ALB
resource "aws_lb_target_group" "alb_tg" {
  name     = "example-alb-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-alb-target-group"
  }
}

# Listener for ALB
resource "aws_lb_listener" "alb_listener" {
  load_balancer_arn = aws_lb.alb.arn
  protocol          = "HTTP"
  port              = "80"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb_tg.arn
  }
}

# Forward Action from ALB to NLB
resource "aws_lb_listener_rule" "forward_to_nlb" {
  listener_arn = aws_lb_listener.alb_listener.arn
  priority     = 100

  action {
    type = "forward"
    forward {
      target_group {
        arn    = aws_lb_target_group.nlb_tg.arn
        weight = 1
      }
    }
  }

  condition {
    field  = "http-request-method"
    values = ["GET"]
  }
}

# IAM Role for ALB
resource "aws_iam_role" "alb_role" {
  name = "example-alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      },
    ]
  })
}

# IAM Policy Attachment for ALB
resource "aws_iam_role_policy_attachment" "alb_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSServiceRoleForElasticLoadBalancing"
  role       = aws_iam_role.alb_role.name
}
```

This configuration sets up a VPC, public subnets, internet gateway, security groups, NLB, ALB, and the necessary listeners and rules to forward traffic from the ALB to the NLB. The IAM role and policy attachment ensure that the ALB has the necessary permissions to operate correctly.

