Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) with a listener that performs a redirect action. The ALB will redirect HTTP traffic on port 80 to HTTPS on port 443.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region.
- **IAM Role**: Created for the ALB to perform necessary actions.
- **VPC and Subnets**: Assumes existing VPC and subnets. If not provided, they will be created.
- **Security Group**: Allows inbound traffic on ports 80 and 443.
- **Load Balancer**: An Application Load Balancer (ALB) is created.
- **Listeners**: 
  - Listener on port 80 that redirects to port 443.
  - Listener on port 443 that forwards traffic to a target group (not implemented here but can be added).
- **Target Group**: A basic target group is created (not used in this example but can be configured to use with the HTTPS listener).

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_id" {
  description = "The ID of the VPC where the ALB will be deployed."
  type        = string
  default     = "vpc-0123456789abcdef0"
}

variable "subnet_ids" {
  description = "A list of subnet IDs within the VPC where the ALB will be deployed."
  type        = list(string)
  default     = ["subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
}

# Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg-"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Application Load Balancer
resource "aws_lb" "alb" {
  name               = "redirect-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = var.subnet_ids
  enable_deletion_protection = false

  tags = {
    Name = "RedirectALB"
  }
}

# Listener on port 80 for HTTP traffic
resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# Listener on port 443 for HTTPS traffic
resource "aws_lb_listener" "https_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"

  # Assuming you have an ACM certificate ARN for HTTPS
  certificate_arn = "arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-id"

  default_action {
    type = "forward"

    forward {
      target_group_arns = [aws_lb_target_group.target_group.arn]
    }
  }
}

# Target Group for HTTPS listener
resource "aws_lb_target_group" "target_group" {
  name     = "target-group"
  port     = 443
  protocol = "HTTPS"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}
```

### Notes:
- Replace `var.vpc_id` and `var.subnet_ids` with your actual VPC and subnet IDs.
- Replace `"arn:aws:acm:us-west-2:123456789012:certificate/your-certificate-id"` with your actual ACM certificate ARN for HTTPS.
- This configuration includes a basic setup for an ALB with a redirect from HTTP to HTTPS. You can extend it by adding more listeners, target groups, and other configurations as needed.

