Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) with a fixed-response action. This means that when traffic hits the load balancer, it will respond with a predefined message instead of forwarding the request to any backend targets.

### Description:
- **Provider Configuration**: Configured for AWS with a specific region.
- **IAM Role**: Created with necessary permissions for the ALB to perform its actions.
- **VPC and Subnets**: Creates a VPC with two public subnets across two availability zones.
- **Internet Gateway**: Attaches an internet gateway to the VPC to allow public access.
- **Security Group**: Allows HTTP traffic on port 80.
- **Load Balancer**: An Application Load Balancer is created with a listener on port 80.
- **Fixed Response Action**: Configures the listener to return a fixed response with a status code and message body.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "example" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create two public subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.example.id
  cidr_block              = ["10.0.1.0/24", "10.0.2.0/24"][count.index]
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index}"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "example" {
  vpc_id = aws_vpc.example.id

  tags = {
    Name = "example-igw"
  }
}

# Create a Security Group for the Load Balancer
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Create an Application Load Balancer
resource "aws_lb" "example" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "example-alb"
  }
}

# Create a Listener for the Load Balancer
resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.arn
  protocol          = "HTTP"
  port              = "80"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, this is a fixed response!"
      status_code  = "200"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}
```

This configuration creates a simple setup where an Application Load Balancer responds with a fixed message whenever it receives an HTTP request. The load balancer is publicly accessible and listens on port 80. The security group allows inbound HTTP traffic from any IP address.

