To create an AWS Application Load Balancer (ALB) with an Authenticate-OIDC action using Terraform, we need to set up several components:

1. **VPC and Subnets**: Define a VPC and subnets where the ALB will reside.
2. **Security Group**: Create a security group for the ALB to control inbound and outbound traffic.
3. **IAM Role and Policy**: Set up an IAM role and policy required for the ALB to authenticate users via OIDC.
4. **Load Balancer**: Create the ALB itself.
5. **Listener**: Define a listener for the ALB.
6. **Authenticate-OIDC Action**: Configure the Authenticate-OIDC action on the listener.

Below is the complete Terraform configuration to achieve this:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "oidc_issuer" {
  description = "The OIDC issuer URL"
  default     = "https://example.com"
}

variable "oidc_authorization_endpoint" {
  description = "The authorization endpoint of the OIDC provider"
  default     = "https://example.com/auth"
}

variable "oidc_token_endpoint" {
  description = "The token endpoint of the OIDC provider"
  default     = "https://example.com/token"
}

variable "oidc_user_info_endpoint" {
  description = "The user info endpoint of the OIDC provider"
  default     = "https://example.com/userinfo"
}

variable "oidc_client_id" {
  description = "The client ID for the OIDC provider"
  default     = "your-client-id"
}

variable "oidc_client_secret" {
  description = "The client secret for the OIDC provider"
  default     = "your-client-secret"
}

variable "oidc_session_cookie_name" {
  description = "The name of the cookie used to maintain session information"
  default     = "AWSELBAuthSessionCookie"
}

variable "oidc_scope" {
  description = "The scope to use during the authentication request"
  default     = "openid"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "alb-vpc"
  }
}

# Create public subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "alb-subnet-${count.index}"
  }
}

# Create an internet gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "alb-igw"
  }
}

# Create a route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "alb-route-table"
  }
}

# Associate subnets with the route table
resource "aws_route_table_association" "public" {
  count          = length(var.subnet_cidr_blocks)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Create a security group for the ALB
resource "aws_security_group" "alb" {
  name_prefix = "alb-sg"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Create an IAM role for the ALB
resource "aws_iam_role" "alb_oidc_auth" {
  name = "alb-oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Create an IAM policy for the ALB
resource "aws_iam_policy" "alb_oidc_auth" {
  name        = "alb-oidc-auth-policy"
  description = "Policy for ALB to authenticate users via OIDC"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "alb_oidc_auth" {
  policy_arn = aws_iam_policy.alb_oidc_auth.arn
  role       = aws_iam_role.alb_oidc_auth.name
}

# Create the ALB
resource "aws_lb" "main" {
  name               = "alb-main"
  internal           = false
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "alb-main"
  }
}

# Create a target group for the ALB
resource "aws_lb_target_group" "main" {
  name     = "alb-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    matcher             = "200-299"
  }

  tags = {
    Name = "alb-target-group"
  }
}

# Create a listener for the ALB
resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint = var.oidc_authorization_endpoint
      client_id              = var.oidc_client_id
      client_secret          = var.oidc_client_secret
      issuer                 = var.oidc_issuer
      token_endpoint         = var.oidc_token_endpoint
      user_info_endpoint     = var.oidc_user_info_endpoint
      session_cookie_name    = var.oidc_session_cookie_name
      scope                  = var.oidc_scope
      session_timeout        = 604800
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}
```

This configuration sets up a VPC, subnets, security groups, IAM roles and policies, an ALB, a target group, and a listener with an Authenticate-OIDC action. The `oidc_*` variables should be replaced with your actual OIDC provider details.

