Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) along with a Target Group in AWS. This configuration includes creating necessary IAM roles and policies if required, but for this specific setup, we don't need any additional IAM roles since ALBs do not require them directly.

The configuration will:
- Define a VPC with two public subnets (one per availability zone).
- Create an Internet Gateway and attach it to the VPC.
- Set up a Route Table and associate it with the public subnets.
- Create an Application Load Balancer in the public subnets.
- Create a Target Group associated with the ALB.

Here's the complete Terraform HCL code:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

# Create public subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index + 1}"
  }
}

# Data source to get available AZs
data "aws_availability_zones" "available" {}

# Create a Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "example-public-route-table"
  }
}

# Associate Route Table with public subnets
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Create an Application Load Balancer
resource "aws_lb" "main" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "example-alb"
  }
}

# Create a Security Group for the ALB
resource "aws_security_group" "alb_sg" {
  name        = "example-alb-sg"
  description = "Allow HTTP traffic from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-alb-sg"
  }
}

# Create a Target Group
resource "aws_lb_target_group" "main" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-target-group"
  }
}
```

This configuration sets up a basic infrastructure with an Application Load Balancer and a Target Group. You can customize the `vpc_cidr_block` and `subnet_cidr_blocks` variables if you need different IP ranges. The ALB is configured to listen on port 80 and the target group is also set to use port 80 with HTTP protocol. The security group allows inbound HTTP traffic from any IP address.

