LLM Output #0:
Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) with an IP-based target group. This setup includes creating the necessary IAM roles, security groups, subnets, and VPC. The ALB will listen on port 80 for HTTP traffic and forward it to the IP target group.

### Description:
- **VPC**: A Virtual Private Cloud with two public subnets in different availability zones.
- **Security Groups**: 
  - One for the ALB to allow inbound HTTP traffic from any IP.
  - Another for the targets in the target group to allow inbound traffic from the ALB.
- **IAM Role**: An IAM role with the necessary permissions for the ALB to perform health checks.
- **Application Load Balancer (ALB)**: Configured to listen on port 80 for HTTP traffic.
- **Target Group**: An IP-based target group where you can register your backend services using their IP addresses.

### Terraform Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

# Create Public Subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index + 1}"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}

# Create Route Table for Public Subnets
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "example-public-route-table"
  }
}

# Associate Route Table with Public Subnets
resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}

# Security Group for ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Security Group for Targets
resource "aws_security_group" "target_sg" {
  name_prefix = "target-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    source_security_group_id = aws_security_group.alb_sg.id
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "target-security-group"
  }
}

# Create IAM Role for ALB
resource "aws_iam_role" "alb_role" {
  name = "alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      },
    ]
  })
}

# Attach necessary policies to the IAM Role
resource "aws_iam_policy_attachment" "alb_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSServiceRoleForElasticLoadBalancing"
  roles      = [aws_iam_role.alb_role.name]
}

# Create Application Load Balancer
resource "aws_lb" "main" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "example-alb"
  }
}

# Create Target Group
resource "aws_lb_target_group" "ip_target_group" {
  name     = "example-ip-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
  target_type = "ip"

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    matcher             = "200-299"
  }

  tags = {
    Name = "example-ip-target-group"
  }
}

# Create Listener for ALB
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "forward"
    forward {
      target_group_arns = [aws_lb_target_group.ip_target_group.arn]
    }
  }
}
```

This configuration creates a fully functional ALB with an IP-based target group in AWS. You can customize the `vpc_cidr_block` and `subnet_cidr_blocks` variables if needed. To deploy this configuration, save it to a `.tf` file, initialize Terraform with `terraform init`, and apply it with `terraform apply`.

