Certainly! Below is a Terraform configuration that sets up an Application Load Balancer (ALB) along with a Target Group. This configuration includes creating necessary IAM roles and policies if required, but for this basic setup, we won't need any specific IAM roles since ALBs don't require them directly. The configuration will also include a VPC, subnets, and security groups to ensure the ALB and Target Group can be properly set up.

### Description:
- **VPC**: A Virtual Private Cloud with two public subnets in different availability zones.
- **Internet Gateway**: To allow internet access from the public subnets.
- **Security Groups**: One for the ALB to allow HTTP traffic and another for the target instances (if any).
- **Application Load Balancer (ALB)**: Configured to listen on port 80 for HTTP traffic.
- **Target Group**: Associated with the ALB, configured to check the health of the targets using HTTP on port 80.

### Terraform Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  type    = list(string)
  default = ["10.0.1.0/24", "10.0.2.0/24"]
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "example-igw"
  }
}

# Create public subnets
resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "example-public-subnet-${count.index + 1}"
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {}

# Create a Security Group for the ALB
resource "aws_security_group" "alb_sg" {
  name_prefix = "alb-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-security-group"
  }
}

# Create a Security Group for the Target Instances (if any)
resource "aws_security_group" "target_sg" {
  name_prefix = "target-sg-"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "target-security-group"
  }
}

# Create an Application Load Balancer
resource "aws_lb" "main" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = aws_subnet.public[*].id
  enable_deletion_protection = false

  tags = {
    Name = "example-alb"
  }
}

# Create a Target Group
resource "aws_lb_target_group" "main" {
  name     = "example-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "example-target-group"
  }
}

# Create a Listener for the ALB
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}
```

This configuration sets up a basic ALB and Target Group in AWS. You can customize the CIDR blocks, regions, and other parameters as needed. To deploy this configuration, save it to a `.tf` file, initialize Terraform (`terraform init`), and apply the changes (`terraform apply`).

