Certainly! Below is a Terraform configuration that creates a basic AWS RDS instance. This configuration includes setting up a VPC, subnet group, security group, and the RDS instance itself. It also creates an IAM role for enhanced monitoring if needed, though this is optional and can be adjusted based on your requirements.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **VPC**: Creates a simple VPC with one public subnet.
- **Subnet Group**: Defines a DB subnet group using the created subnet.
- **Security Group**: Sets up a security group to allow traffic on port 3306 (MySQL default).
- **RDS Instance**: Creates a MySQL RDS instance within the defined subnet group and security group.
- **IAM Role**: Creates an IAM role with permissions for enhanced monitoring (optional).

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  default = "10.0.1.0/24"
}

variable "db_instance_identifier" {
  default = "my-rds-instance"
}

variable "db_name" {
  default = "mydatabase"
}

variable "db_username" {
  default = "admin"
}

variable "db_password" {
  default = "password123"
}

variable "db_engine" {
  default = "mysql"
}

variable "db_engine_version" {
  default = "8.0"
}

variable "db_instance_class" {
  default = "db.t3.micro"
}

variable "allocated_storage" {
  default = 20
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MyVPC"
  }
}

# Create an Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MyIGW"
  }
}

# Create a Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet"
  }
}

# Create a DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "my-db-subnet-group"
  subnet_ids = [aws_subnet.public.id]

  tags = {
    Name = "MyDBSubnetGroup"
  }
}

# Create a Security Group for RDS
resource "aws_security_group" "rds" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "MyRDSSecurityGroup"
  }
}

# Create an IAM Role for Enhanced Monitoring (Optional)
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the necessary policy to the IAM Role
resource "aws_iam_policy_attachment" "rds_monitoring_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
  roles      = [aws_iam_role.rds_monitoring.name]
}

# Create the RDS Instance
resource "aws_db_instance" "main" {
  identifier           = var.db_instance_identifier
  allocated_storage    = var.allocated_storage
  engine               = var.db_engine
  engine_version       = var.db_engine_version
  instance_class       = var.db_instance_class
  name                 = var.db_name
  username             = var.db_username
  password             = var.db_password
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  skip_final_snapshot  = true

  # Optional: Enable Enhanced Monitoring
  # monitoring_interval = 60
  # monitoring_role_arn = aws_iam_role.rds_monitoring.arn

  tags = {
    Name = "MyRDSInstance"
  }
}
```

### Notes:
- The `skip_final_snapshot` parameter is set to `true` for simplicity, but it's recommended to manage snapshots according to your backup strategy.
- The security group allows all inbound traffic on port 3306 from any IP address (`0.0.0.0/0`). In a production environment, you should restrict this to specific IP addresses or ranges.
- The IAM role for enhanced monitoring is optional and can be enabled by uncommenting the relevant lines in the RDS instance resource block.
- Ensure that the `db_password` variable is securely managed, possibly using AWS Secrets Manager or another secure method.

