To address your request, I'll create a Terraform configuration that sets up an Amazon RDS instance with managed master passwords using AWS Secrets Manager. The master password will be encrypted using a specific AWS KMS key. Below is the complete Terraform HCL configuration:

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **KMS Key**: Creates a KMS key for encrypting the master password.
- **IAM Role**: Creates an IAM role with policies necessary for RDS to access Secrets Manager.
- **Secrets Manager Secret**: Creates a secret in Secrets Manager to store the master password, encrypted with the specified KMS key.
- **RDS Instance**: Creates an RDS instance with the master password managed by Secrets Manager.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired region
}

# Create a KMS Key for encrypting the master password
resource "aws_kms_key" "rds_master_password_key" {
  description             = "KMS Key for RDS Master Password"
  deletion_window_in_days = 10
}

# Create an IAM policy for RDS to access Secrets Manager
data "aws_iam_policy_document" "rds_secrets_manager_access_policy" {
  statement {
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret"
    ]
    resources = ["*"]
  }
}

# Create an IAM role for RDS to access Secrets Manager
resource "aws_iam_role" "rds_secrets_manager_access_role" {
  name               = "rds-secrets-manager-access-role"
  assume_role_policy = data.aws_iam_policy_document.rds_secrets_manager_assume_role.json
}

# Assume role policy for RDS to assume the IAM role
data "aws_iam_policy_document" "rds_secrets_manager_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
  }
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "rds_secrets_manager_access_policy_attachment" {
  policy_arn = aws_iam_policy_document.rds_secrets_manager_access_policy.arn
  role       = aws_iam_role.rds_secrets_manager_access_role.name
}

# Create a Secrets Manager secret for the RDS master password
resource "aws_secretsmanager_secret" "rds_master_password" {
  name                 = "rds-master-password"
  kms_key_id           = aws_kms_key.rds_master_password_key.key_id
  description          = "Master password for RDS instance"
  recovery_window_in_days = 30
}

# Create an RDS instance with managed master password
resource "aws_db_instance" "example" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  db_subnet_group_name = var.db_subnet_group_name
  vpc_security_group_ids = [var.vpc_security_group_id]
  skip_final_snapshot  = true

  # Use managed master password from Secrets Manager
  manage_master_user_password = true
  master_user_secret_kms_key_id = aws_kms_key.rds_master_password_key.key_id
  master_user_secret_secret_type = "random_password"

  # Reference the Secrets Manager secret for the master password
  master_user_secret = {
    secret_arn = aws_secretsmanager_secret.rds_master_password.arn
  }
}

# Variables with default values
variable "db_subnet_group_name" {
  description = "The DB subnet group to associate with the DB instance."
  default     = "default"
}

variable "vpc_security_group_id" {
  description = "The VPC security group ID to associate with the DB instance."
  default     = "sg-0123456789abcdef0"
}
```

### Notes:
- Replace `us-west-2` with your desired AWS region.
- Update the `db_subnet_group_name` and `vpc_security_group_id` variables with your actual subnet group and security group IDs.
- This configuration assumes you have the necessary permissions to create these resources in your AWS account.

This configuration will deploy an RDS instance with a master password managed by Secrets Manager, encrypted using a specific KMS key.

