Certainly! Below is a Terraform configuration that creates an AWS Elastic File System (EFS) with a system policy. The system policy will allow access to the EFS from any EC2 instance within the same VPC. This example includes creating a VPC, subnet, security group, and IAM role with the necessary permissions for EFS.

### Description:
- **Provider Configuration**: Configures the AWS provider with a specific region.
- **VPC and Subnet**: Creates a VPC and a public subnet within that VPC.
- **Security Group**: Creates a security group that allows inbound NFS traffic (port 2049) from instances within the same VPC.
- **IAM Role and Policy**: Creates an IAM role with policies that allow EC2 instances to access the EFS.
- **EFS File System**: Creates an EFS file system with a system policy that allows access from any EC2 instance within the VPC.

### Terraform HCL Configuration:

```hcl
provider "aws" {
  region = "us-west-2"
}

# Variables with default values
variable "vpc_cidr_block" {
  default = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  default = "10.0.1.0/24"
}

# Create a VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

# Create a public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "example-subnet-public"
  }
}

# Create a security group for EFS
resource "aws_security_group" "efs_sg" {
  vpc_id = aws_vpc.main.id

  ingress {
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-efs-sg"
  }
}

# Create an IAM role for EC2 instances to access EFS
resource "aws_iam_role" "ec2_efs_access" {
  name = "ec2-efs-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })
}

# Attach the necessary policies to the IAM role
resource "aws_iam_policy_attachment" "ec2_efs_access_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2RoleforSSM"
  roles      = [aws_iam_role.ec2_efs_access.name]
}

resource "aws_iam_policy_attachment" "efs_access_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemReadOnlyAccess"
  roles      = [aws_iam_role.ec2_efs_access.name]
}

# Create an EFS file system
resource "aws_efs_file_system" "main" {
  creation_token = "example-efs-token"

  tags = {
    Name = "example-efs"
  }
}

# Create an EFS mount target
resource "aws_efs_mount_target" "main" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.public.id
  security_groups = [aws_security_group.efs_sg.id]

  tags = {
    Name = "example-efs-mount-target"
  }
}
```

This configuration sets up a basic infrastructure to use AWS EFS with a system policy that allows access from any EC2 instance within the VPC. You can customize the CIDR blocks, region, and other parameters as needed.

