### Description

The Terraform program will create a Virtual Private Cloud (VPC) in AWS with multiple public subnets. Each public subnet will be associated with a route table that routes traffic to an Internet Gateway, enabling internet access for instances within these subnets. The program includes the creation of an Internet Gateway, a VPC, multiple public subnets, and a route table with a route to the Internet Gateway.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to create resources in"
  type        = string
  default     = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "List of CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "public_subnet_availability_zones" {
  description = "List of availability zones for the public subnets"
  type        = list(string)
  default     = ["us-west-2a", "us-west-2b"]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_subnet" "public" {
  count                   = length(var.subnet_cidr_blocks)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidr_blocks, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(var.public_subnet_availability_zones, count.index)

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.subnet_cidr_blocks)
  subnet_id      = element(aws_subnet.public.*.id, count.index)
  route_table_id = aws_route_table.public.id
}
```

This Terraform configuration sets up a VPC with two public subnets in different availability zones, each associated with a route table that routes traffic through an Internet Gateway. The default region is set to `us-west-2`, but this can be changed using the `region` variable. The VPC and subnets are tagged for easy identification.

