  allocation_id = aws_eip.nat_eip.id  # Use the Elastic IP allocation ID from the created EIP
  subnet_id     = var.subnet_id       # Specify the subnet ID where the NAT Gateway will be deployed

  tags = {
    pike = "permissions"
  }

  # Ensure the NAT Gateway is configured for private connectivity
  private_link_configuration {
    eip_address = aws_eip.nat_eip.public_ip
  }
}

# Variable definition for subnet_id
variable "subnet_id" {
  description = "The ID of the subnet in which to create the NAT Gateway"
  type        = string
  default     = "subnet-0123456789abcdef0"  # Replace with your actual subnet ID
}
```

