The Terraform program you requested will configure AWS as the cloud provider. It will create an AWS VPC with a CIDR block of `10.0.0.0/16`. Additionally, it will define a Network Access Control List (NACL) associated with this VPC. The NACL will have specific ingress and egress rules allowing TCP traffic on certain ports.

Here's the complete Terraform HCL configuration:

```hcl
provider "aws" {
  region = "us-west-2"  # You can change this to your preferred region
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "nacl_ingress_rules" {
  description = "List of ingress rules for the NACL"
  type        = list(object({
    rule_number    = number
    protocol       = string
    from_port      = number
    to_port        = number
    cidr_block     = string
    rule_action    = string
  }))
  default = [
    {
      rule_number    = 100
      protocol       = "tcp"
      from_port      = 22
      to_port        = 22
      cidr_block     = "0.0.0.0/0"
      rule_action    = "allow"
    },
    {
      rule_number    = 200
      protocol       = "tcp"
      from_port      = 80
      to_port        = 80
      cidr_block     = "0.0.0.0/0"
      rule_action    = "allow"
    }
  ]
}

variable "nacl_egress_rules" {
  description = "List of egress rules for the NACL"
  type        = list(object({
    rule_number    = number
    protocol       = string
    from_port      = number
    to_port        = number
    cidr_block     = string
      rule_action    = string
  }))
  default = [
    {
      rule_number    = 100
      protocol       = "tcp"
      from_port      = 0
      to_port        = 0
      cidr_block     = "0.0.0.0/0"
      rule_action    = "allow"
    }
  ]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_network_acl" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "MainNACL"
  }
}

resource "aws_network_acl_rule" "ingress" {
  count             = length(var.nacl_ingress_rules)
  network_acl_id    = aws_network_acl.main.id
  rule_number       = var.nacl_ingress_rules[count.index].rule_number
  protocol          = var.nacl_ingress_rules[count.index].protocol
  from_port         = var.nacl_ingress_rules[count.index].from_port
  to_port           = var.nacl_ingress_rules[count.index].to_port
  cidr_block        = var.nacl_ingress_rules[count.index].cidr_block
  rule_action       = var.nacl_ingress_rules[count.index].rule_action
  egress            = false
}

resource "aws_network_acl_rule" "egress" {
  count             = length(var.nacl_egress_rules)
  network_acl_id    = aws_network_acl.main.id
  rule_number       = var.nacl_egress_rules[count.index].rule_number
  protocol          = var.nacl_egress_rules[count.index].protocol
  from_port         = var.nacl_egress_rules[count.index].from_port
  to_port           = var.nacl_egress_rules[count.index].to_port
  cidr_block        = var.nacl_egress_rules[count.index].cidr_block
  rule_action       = var.nacl_egress_rules[count.index].rule_action
  egress            = true
}
